INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研制", "is_correct": true, "explanation": "研制：研究并制造出新产品，与“出”和“电脑”搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗出”多指洗出照片或污渍，不能说“洗出便宜的电脑”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“便宜的电脑”作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带宾语，无法与“出了便宜的电脑”搭配。"}], "explanations": {"研制": "研制：研究并制造出新产品，与“出”和“电脑”搭配。", "洗": "搭配：“洗出”多指洗出照片或污渍，不能说“洗出便宜的电脑”。", "哭": "配价：“哭”是不及物动词，不能带“便宜的电脑”作宾语。", "散步": "配价：“散步”是不及物动词，不能带宾语，无法与“出了便宜的电脑”搭配。"}, "sentence_index": 6, "correct_answer": "研制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民研制了一片小麦。", "explanation": "这里应该用〈种植〉。研制指研制新产品，农作物要用种植。"}, {"text": "他研制了一本英文小说。", "explanation": "这里应该用〈翻译〉。研制指研制新产品，把外文译成中文要用翻译。"}, {"text": "工人研制了一座新房子。", "explanation": "这里应该用〈盖〉。研制指研制新产品，房屋要用盖或建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂正在研制了新的电视。", "corrected_sentence": "这家工厂正在研制新的电视。", "error_description": "“正在”表示动作正在进行，不能与“了”同时用在“研制”上，应说“正在研制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司已经研制了出新手机。", "corrected_sentence": "这家公司已经研制出了新手机。", "error_description": "结果补语“出”应紧跟“研制”，说“研制出了”。错句把“了”放在“出”前，变成“研制了出”，语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
