INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91553, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91553, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发文是把写好的文章或通知发出去。", "primary_collocate": null, "pronunciation": "fā wén", "ipa": "fa˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "小王把通知写好了，马上发文。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在群里发文，告诉大家明天考试。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天晚上都在网上发文。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写完这篇文章，我就发文。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理已经发文，通知大家下周开会。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你发文以前，先检查一下有没有错字。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发文以后，一直没有人回复。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，公司马上发文通知大家。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校昨天发文，说下星期放假。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把时间写清楚再发文。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了文", "label": "完成体"}, {"form": "发过文", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把写好的文章或通知发出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发文", "is_correct": true, "explanation": "正确：发文指把写好的通知发出去，与“写好了”“马上”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象须是食物，“通知”不能被吃，句子无法成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是唱歌，与前面写通知的动作毫无关联。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是身体动作，与“写好通知”没有关联。"}], "explanations": {"发文": "正确：发文指把写好的通知发出去，与“写好了”“马上”相符。", "吃": "搭配：“吃”的对象须是食物，“通知”不能被吃，句子无法成立。", "唱": "语义：“唱”是唱歌，与前面写通知的动作毫无关联。", "跳": "语义：“跳”是身体动作，与“写好通知”没有关联。"}, "sentence_index": 0, "correct_answer": "发文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的快递昨天发文了。", "explanation": "这里应该用〈寄〉。发文只用于文章、通知等文字材料，快递要用寄，不能说快递发文。"}, {"text": "这盏台灯昨天发文了。", "explanation": "这里应该用〈发光〉。发文只用于文字材料，台灯发出光要用发光，不能用发文。"}, {"text": "这颗种子昨天发文了。", "explanation": "这里应该用〈发芽〉。发文不能用于植物，种子长出芽要用发芽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发文", "is_correct": true, "explanation": "正确：发文指发出通知或文件，发出后才会出现“没有人回复”，与句意相符。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”是表情动作，与“发出去以后没有人回复”的语境不相关。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不带消息类的对象，无法与“没有人回复”的结果对应。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”是娱乐活动，与发送消息后无人回复的语境不相关。"}], "explanations": {"发文": "正确：发文指发出通知或文件，发出后才会出现“没有人回复”，与句意相符。", "笑": "语义：“笑”是表情动作，与“发出去以后没有人回复”的语境不相关。", "游泳": "配价：“游泳”是不及物动词，不带消息类的对象，无法与“没有人回复”的结果对应。", "跳舞": "语义：“跳舞”是娱乐活动，与发送消息后无人回复的语境不相关。"}, "sentence_index": 6, "correct_answer": "发文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车昨天发文了。", "explanation": "这里应该用〈发车〉。发文只用于文字材料，车发出去要用发车。"}, {"text": "这块面团昨天发文了。", "explanation": "这里应该用〈发酵〉。发文不能用于面团，面团膨胀要用发酵。"}, {"text": "这台机器昨天发文了。", "explanation": "这里应该用〈发动〉。发文不能用于机器，机器启动要用发动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天发文着，通知大家。", "corrected_sentence": "他昨天发文了，通知大家。", "error_description": "体标错误：“昨天”指已完成的动作，“发文”后应用“了”，不能用“着”，应说“发文了”，不能说“发文着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天没发文了。", "corrected_sentence": "他昨天没发文。", "error_description": "体标错误：用“没”否定已发生的动作时，“发文”后不能再加“了”，应说“没发文”，不能说“没发文了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
