INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发布文章、帖子或公文。", "primary_collocate": null, "pronunciation": "fā wén", "ipa": "fa˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "他喜欢在博客上发文，分享自己的生活。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个账号每周发文三次。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府发文，要求大家注意安全。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发文以后，很多网友都点赞了。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想在论坛发文，要先注册。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不常发文，只是看别人的帖子。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司刚发文，禁止员工迟到。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天发文介绍了这家小店。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者发文感谢大家的支持。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上八点发文。", "target_word": "发文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发了文", "label": "完成体"}, {"form": "发过文", "label": "经历体"}], "register": "中性", "sense_fingerprint": "发布文章、帖子或公文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发文", "is_correct": true, "explanation": "正确：在博客上发布文章或帖子，与“分享自己的生活”相符。"}, {"text": "理发", "is_correct": false, "explanation": "语义：“理发”是剪头发，与在博客上分享生活无关。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是体育活动，与在博客上的分享行为不相干。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是休息，不能在博客上进行，与“分享自己的生活”的动作不相符。"}], "explanations": {"发文": "正确：在博客上发布文章或帖子，与“分享自己的生活”相符。", "理发": "语义：“理发”是剪头发，与在博客上分享生活无关。", "游泳": "语义：“游泳”是体育活动，与在博客上的分享行为不相干。", "睡觉": "语义：“睡觉”是休息，不能在博客上进行，与“分享自己的生活”的动作不相符。"}, "sentence_index": 0, "correct_answer": "发文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会上发文了三次。", "explanation": "这里应该用〈发言〉。发文指发布文字内容，在会上讲话要用发言。"}, {"text": "这块面包昨天发文了。", "explanation": "这里应该用〈发霉〉。发文不能用于食物，面包变质长毛要用发霉。"}, {"text": "这片树叶昨天发文了。", "explanation": "这里应该用〈发黄〉。发文不能用于树叶，树叶变色要用发黄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发文", "is_correct": true, "explanation": "正确：发文指发布文件，公司发布规定禁止员工迟到，与句意相符。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”意味着不上班，与“禁止员工迟到”的规定语境相矛盾。"}, {"text": "辞职", "is_correct": false, "explanation": "搭配：“辞职”的主语是个人，不能说“公司辞职”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与公司规定员工迟到无关，句子不通。"}], "explanations": {"发文": "正确：发文指发布文件，公司发布规定禁止员工迟到，与句意相符。", "放假": "语义：“放假”意味着不上班，与“禁止员工迟到”的规定语境相矛盾。", "辞职": "搭配：“辞职”的主语是个人，不能说“公司辞职”。", "唱歌": "语义：“唱歌”与公司规定员工迟到无关，句子不通。"}, "sentence_index": 6, "correct_answer": "发文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗卫星昨天发文了。", "explanation": "这里应该用〈发射〉。发文只用于文字内容，卫星升空要用发射。"}, {"text": "这个病人昨天发文了。", "explanation": "这里应该用〈发烧〉。发文只用于发布文字内容，病人体温升高要用发烧。"}, {"text": "这些树苗昨天发文了。", "explanation": "这里应该用〈发芽〉。发文不能用于植物，树苗长出芽要用发芽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她昨天发文着，分享自己的生活。", "corrected_sentence": "她昨天发文了，分享自己的生活。", "error_description": "体标错误：“昨天”指已完成的动作，“发文”后应用“了”，不能用“着”，应说“发文了”，不能说“发文着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天没发文了。", "corrected_sentence": "她昨天没发文。", "error_description": "体标错误：用“没”否定已发生的动作时，“发文”后不能再加“了”，应说“没发文”，不能说“没发文了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91555, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末期", "is_correct": true, "explanation": "末期：一段时间或事情的末尾阶段，与“初期”构成反义。"}, {"text": "过程", "is_correct": false, "explanation": "过程泛指事情进行的经过，与“初期”的阶段义没有反义关系。"}, {"text": "年代", "is_correct": false, "explanation": "年代指较长的历史时期，与“初期”没有反义关系。"}, {"text": "高峰", "is_correct": false, "explanation": "高峰指最高点，与“初期”没有反义关系。"}], "correct_answer": "末期", "explanations": {"末期": "末期：一段时间或事情的末尾阶段，与“初期”构成反义。", "过程": "过程泛指事情进行的经过，与“初期”的阶段义没有反义关系。", "年代": "年代指较长的历史时期，与“初期”没有反义关系。", "高峰": "高峰指最高点，与“初期”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
