INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "初期是一段时间最开始的那一小段。", "primary_collocate": null, "pronunciation": "chū qī", "ipa": "ʈʂʰu˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "学汉语的初期，我每天只学五个字。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的初期，天气还有一点热。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开店的初期，客人不多，我们很辛苦。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新城市的初期，我常常想家。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的初期，我们队一直没有进球。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的初期，我什么都不懂，常常问同事。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的初期，晚上还有一点凉。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥的初期，我每天跑步半小时。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学习的初期，别学得太快。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用新手机的初期，电池很好用，后来越来越差。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一段时间（如学习、工作、季节）最开始的短阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "初期", "is_correct": true, "explanation": "初期 chū qī，意思是一段时间开始的那一小段。"}, {"text": "出气", "is_correct": false, "explanation": "出气 chū qì 与 chū qī 只在第二个音节声调不同，意思是呼气或发泄怒气。"}, {"text": "出奇", "is_correct": false, "explanation": "出奇 chū qí 与 chū qī 只在第二个音节声调不同，意思是非同寻常。"}, {"text": "储气", "is_correct": false, "explanation": "储气 chǔ qì 两个音节的声调都不同，意思是储存气体。"}], "explanations": {"初期": "初期 chū qī，意思是一段时间开始的那一小段。", "出气": "出气 chū qì 与 chū qī 只在第二个音节声调不同，意思是呼气或发泄怒气。", "出奇": "出奇 chū qí 与 chū qī 只在第二个音节声调不同，意思是非同寻常。", "储气": "储气 chǔ qì 两个音节的声调都不同，意思是储存气体。"}, "sentence_index": null, "correct_answer": "初期"}, "level_3": {"options": [{"text": "初期", "is_correct": true, "explanation": "初期：学习的开始阶段，与“只学五个字”的起步状态一致。"}, {"text": "尾声", "is_correct": false, "explanation": "语义：“尾声”指结束阶段，与“只学五个字”的起步状态不符。"}, {"text": "高峰", "is_correct": false, "explanation": "语义：“高峰”指最高点，与“每天只学五个字”的起步状态矛盾。"}, {"text": "结局", "is_correct": false, "explanation": "语义：“结局”指最终结果，不是学习过程中的阶段，与“只学五个字”的句意不符。"}], "explanations": {"初期": "初期：学习的开始阶段，与“只学五个字”的起步状态一致。", "尾声": "语义：“尾声”指结束阶段，与“只学五个字”的起步状态不符。", "高峰": "语义：“高峰”指最高点，与“每天只学五个字”的起步状态矛盾。", "结局": "语义：“结局”指最终结果，不是学习过程中的阶段，与“只学五个字”的句意不符。"}, "sentence_index": 0, "correct_answer": "初期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆花的初期很红。", "explanation": "这里应该用〈颜色〉。初期指一段时间，不能用来形容花的颜色。"}, {"text": "他是我们班的初期。", "explanation": "这里应该用〈初学者〉。初期指一段时间的开端，不指人，刚开始学习的人要说“初学者”。"}, {"text": "他的初期很聪明。", "explanation": "这里应该用〈头脑〉。初期指一段时间，不能用来形容人的聪明程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初期", "is_correct": true, "explanation": "初期：夏天的开始阶段，与“晚上还有一点凉”相合。"}, {"text": "深冬", "is_correct": false, "explanation": "搭配：“夏天的深冬”自相矛盾，“深冬”属于冬季，与“夏天”不能搭配。"}, {"text": "冬季", "is_correct": false, "explanation": "搭配：“夏天的冬季”自相矛盾，“冬季”不能与“夏天”并列作时间限定。"}, {"text": "深秋", "is_correct": false, "explanation": "搭配：“深秋”属于另一个季节，与“夏天”不能搭配。"}], "explanations": {"初期": "初期：夏天的开始阶段，与“晚上还有一点凉”相合。", "深冬": "搭配：“夏天的深冬”自相矛盾，“深冬”属于冬季，与“夏天”不能搭配。", "冬季": "搭配：“夏天的冬季”自相矛盾，“冬季”不能与“夏天”并列作时间限定。", "深秋": "搭配：“深秋”属于另一个季节，与“夏天”不能搭配。"}, "sentence_index": 6, "correct_answer": "初期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他六岁，正在上初期。", "explanation": "这里应该用〈小学〉。初期指一段时间的开端，不是学校的阶段名称，表示上学要说“上小学”。"}, {"text": "他的初期很高。", "explanation": "这里应该用〈个子〉。初期指时间，不能用来形容人的身高。"}, {"text": "这条裙子的初期很漂亮。", "explanation": "这里应该用〈外观〉。初期指一段时间，不能用来形容衣服的样子，“外观”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在养猫的初期了，常常忘记喂它。", "corrected_sentence": "我在养猫的初期，常常忘记喂它。", "error_description": "“在……的初期”表示时间，“初期”是名词，后面不能加“了”。应说“在养猫的初期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在学开车的一次初期，常常紧张。", "corrected_sentence": "他在学开车的初期，常常紧张。", "error_description": "“初期”前不能加“一次”这样的数量词，表示时间阶段的名词不能被这样修饰，应说“他在学开车的初期，常常紧张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
