INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91556, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末期", "is_correct": true, "explanation": "末期：事情或时代的末尾阶段，与“初期”构成反义。"}, {"text": "中途", "is_correct": false, "explanation": "中途指事情进行的中间，与“初期”没有反义关系。"}, {"text": "高潮", "is_correct": false, "explanation": "高潮指事情发展最激烈的时候，与“初期”没有反义关系。"}, {"text": "旧事", "is_correct": false, "explanation": "旧事指过去的事情，与“初期”没有反义关系。"}], "correct_answer": "末期", "explanations": {"末期": "末期：事情或时代的末尾阶段，与“初期”构成反义。", "中途": "中途指事情进行的中间，与“初期”没有反义关系。", "高潮": "高潮指事情发展最激烈的时候，与“初期”没有反义关系。", "旧事": "旧事指过去的事情，与“初期”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情或时代的开头阶段。", "primary_collocate": null, "pronunciation": "chū qī", "ipa": "ʈʂʰu˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "唐朝初期，国家很安定。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病的初期，人常常没有感觉。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝初期，很多人搬到了北方。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国改革开放初期，生活还很苦。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影刚出现的初期，没有声音。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目初期，我们先做了一个小计划。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争初期，这个城市还很平静。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发明汽车的初期，路上的车很少。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司在发展初期遇到了很多困难。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民国初期，很多学校刚刚建立。", "target_word": "初期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事情、疾病或历史时代的开头阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "初期", "is_correct": true, "explanation": "初期 chū qī，意思是事情或时代的开头阶段。"}, {"text": "粗气", "is_correct": false, "explanation": "粗气 cū qì 与 chū qī 读音相近：第一个音节声母是 c 不是 ch，第二个音节是第四声，意思是呼吸很重。"}, {"text": "出气", "is_correct": false, "explanation": "出气 chū qì 与 chū qī 只在第二个音节声调不同，意思是呼气或发泄怒气。"}, {"text": "出奇", "is_correct": false, "explanation": "出奇 chū qí 与 chū qī 只在第二个音节声调不同，意思是非同寻常。"}], "explanations": {"初期": "初期 chū qī，意思是事情或时代的开头阶段。", "粗气": "粗气 cū qì 与 chū qī 读音相近：第一个音节声母是 c 不是 ch，第二个音节是第四声，意思是呼吸很重。", "出气": "出气 chū qì 与 chū qī 只在第二个音节声调不同，意思是呼气或发泄怒气。", "出奇": "出奇 chū qí 与 chū qī 只在第二个音节声调不同，意思是非同寻常。"}, "sentence_index": null, "correct_answer": "初期"}, "level_3": {"options": [{"text": "初期", "is_correct": true, "explanation": "初期：唐朝开头的阶段，与“国家很安定”的句意一致。"}, {"text": "末年", "is_correct": false, "explanation": "语义：“末年”指王朝走向衰落的时候，与“国家很安定”矛盾。"}, {"text": "动乱", "is_correct": false, "explanation": "语义：“动乱”指社会不安定，与“国家很安定”矛盾。"}, {"text": "陵墓", "is_correct": false, "explanation": "搭配：“陵墓”是地点，不表示一段时间，不能放在“唐朝”之后作时间限定。"}], "explanations": {"初期": "初期：唐朝开头的阶段，与“国家很安定”的句意一致。", "末年": "语义：“末年”指王朝走向衰落的时候，与“国家很安定”矛盾。", "动乱": "语义：“动乱”指社会不安定，与“国家很安定”矛盾。", "陵墓": "搭配：“陵墓”是地点，不表示一段时间，不能放在“唐朝”之后作时间限定。"}, "sentence_index": 0, "correct_answer": "初期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的初期很漂亮。", "explanation": "这里应该用〈外观〉。初期指一段时间，不能用来形容学校的样子。"}, {"text": "他是钢琴的初期。", "explanation": "这里应该用〈初学者〉。初期指一段时间的开端，不指人，刚开始学钢琴的人要说“初学者”。"}, {"text": "这架钢琴的初期很重。", "explanation": "这里应该用〈重量〉。初期指一段时间，不能用来形容钢琴的重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初期", "is_correct": true, "explanation": "初期：战争开始的阶段，与“这个城市还很平静”相合。"}, {"text": "炮火", "is_correct": false, "explanation": "语义：“炮火”指正在交战，与“这个城市还很平静”矛盾。"}, {"text": "战场", "is_correct": false, "explanation": "搭配：“战场”是地点，不能放在“战争”之后作时间限定。"}, {"text": "瘟疫", "is_correct": false, "explanation": "搭配：“瘟疫”不是一段时间，不能放在“战争”之后作时间限定。"}], "explanations": {"初期": "初期：战争开始的阶段，与“这个城市还很平静”相合。", "炮火": "语义：“炮火”指正在交战，与“这个城市还很平静”矛盾。", "战场": "搭配：“战场”是地点，不能放在“战争”之后作时间限定。", "瘟疫": "搭配：“瘟疫”不是一段时间，不能放在“战争”之后作时间限定。"}, "sentence_index": 6, "correct_answer": "初期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的初期很大。", "explanation": "这里应该用〈面积〉。初期指一段时间，不能用来形容桌子的大小。"}, {"text": "他的初期很聪明。", "explanation": "这里应该用〈脑子〉。初期指时间，不能用来形容人的头脑。"}, {"text": "这辆车的初期很干净。", "explanation": "这里应该用〈外观〉。初期指一段时间，不能用来形容车的样子，“外观”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市在建设一个初期，人口很少。", "corrected_sentence": "这座城市在建设初期，人口很少。", "error_description": "“初期”是表示时间阶段的名词，这里不能加“一个”，应说“这座城市在建设初期，人口很少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥一个修建初期，还没有通车。", "corrected_sentence": "这座桥的修建初期，还没有通车。", "error_description": "“一个”是数量词，不能直接修饰表示时间阶段的“初期”，应改为“的”，说“这座桥的修建初期，还没有通车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
