INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91559, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看错是把这个看成了那个。", "primary_collocate": null, "pronunciation": "kàn cuò", "ipa": "kʰan˥˩ tsʰuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "我看错了时间，来晚了。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是看错了人？", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我看错了你的电话号码。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看错了路牌，走错了路。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有看错，那就是我的老师。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看错了药名，吃错了药。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑了，我把那只猫看错了，以为是狗。", "target_word": "看错", "complexity_tier": "T3", "furigana": "tiān tài hēi le, wǒ bǎ nà zhī māo kàn cuò le, yǐ wéi shì gǒu.", "sentence_source": "generated"}, {"text": "小心点，别看错价格。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟看错了题，所以做错了。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为是他，原来是看错了。", "target_word": "看错", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看錯", "label": "繁体"}, {"form": "看错了", "label": "体标（了）"}, {"form": "看错过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "看错：把一个东西看成另一个，如看错时间、看错题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看错", "is_correct": true, "explanation": "正确：“看错”表示把时间看成了别的，所以来晚了。"}, {"text": "看对", "is_correct": false, "explanation": "语义：“看对”说明没有看错时间，与“来晚了”矛盾。"}, {"text": "看准", "is_correct": false, "explanation": "语义：“看准”表示看得准确，与“来晚了”矛盾。"}, {"text": "看懂", "is_correct": false, "explanation": "搭配：“看懂”的对象是文字或意思，不说看懂时间。"}], "explanations": {"看错": "正确：“看错”表示把时间看成了别的，所以来晚了。", "看对": "语义：“看对”说明没有看错时间，与“来晚了”矛盾。", "看准": "语义：“看准”表示看得准确，与“来晚了”矛盾。", "看懂": "搭配：“看懂”的对象是文字或意思，不说看懂时间。"}, "sentence_index": 0, "correct_answer": "看错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把电话里的声音看错了，以为是妈妈。", "explanation": "这里应该用〈听错〉。电话里的声音要用耳朵听，看错只用于视觉上把人或物认成别的。"}, {"text": "他很快看错了这个道理，所以没有学会。", "explanation": "这里应该用〈理解〉。看错用于把具体的人、物、字认错，道理是抽象内容，不能看错。"}, {"text": "他看错了我的愿望，所以没有帮忙。", "explanation": "这里应该用〈了解〉。愿望是内心想要的东西，要靠了解，看错只用于把看见的人或物认成别的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看错", "is_correct": true, "explanation": "正确：天黑看不清，把猫认成了狗，所以用“看错”。"}, {"text": "看清", "is_correct": false, "explanation": "语义：“看清”表示看得清楚，与“天太黑了”和“以为是狗”矛盾。"}, {"text": "看透", "is_correct": false, "explanation": "搭配：“看透”用于人心或道理，不说看透猫。"}, {"text": "看重", "is_correct": false, "explanation": "语义：“看重”表示重视，与“以为是狗”的误认无关，句意不通。"}], "explanations": {"看错": "正确：天黑看不清，把猫认成了狗，所以用“看错”。", "看清": "语义：“看清”表示看得清楚，与“天太黑了”和“以为是狗”矛盾。", "看透": "搭配：“看透”用于人心或道理，不说看透猫。", "看重": "语义：“看重”表示重视，与“以为是狗”的误认无关，句意不通。"}, "sentence_index": 6, "correct_answer": "看错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看错了他说的话，以为他不去了。", "explanation": "这里应该用〈听错〉。说的话要用耳朵听，看错只用于视觉上把人或物认成别的。"}, {"text": "我把花的香味看错了，以为是香水。", "explanation": "这里应该用〈闻错〉。香味要用鼻子闻，看错只用于视觉上把人或物认成别的。"}, {"text": "我把这锅汤的味道看错了，所以又加了一次盐。", "explanation": "这里应该用〈尝〉。味道要靠舌头品尝，看错只用于视觉上把人或物认成别的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把那个数字看错了了，多算了一百块钱。", "corrected_sentence": "我把那个数字看错了，多算了一百块钱。", "error_description": "“了”重复：“看错了”已经带“了”，后面不能再加一个“了”，应为“看错了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那张照片看错着，以为是朋友。", "corrected_sentence": "我把那张照片看错了，以为是朋友。", "error_description": "体标错误：“看错”表示已经发生的差错，应用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
