INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91561, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到点是说好的那个时间到了。", "primary_collocate": null, "pronunciation": "dào diǎn", "ipa": "taʊ̯˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "到点了，我们开始开会吧。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "约好六点见面，现在已经到点了。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看看表，说：“到点了，该走了。”", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还没到点，客人都没来呢。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和朋友约好三点见面，一到点就跑出了门。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说好八点出发，到点了你怎么还在睡？", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到点了，老师还没来，大家有点着急。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说好到点就打电话，你别忘了。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影快到点了，我们快进去吧。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到点了，他们俩还没出现。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到点了", "label": "体标"}], "register": "口语", "sense_fingerprint": "人们事先约好或说好的那个时间到了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91561, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到点", "is_correct": true, "explanation": "正确：“到点了”说约好的时间已到，与“我们开始开会”相合。"}, {"text": "散会", "is_correct": false, "explanation": "语义：“散会”指会议结束，与“开始开会”矛盾。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”表示不用上班上课，与开会的语境矛盾。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”指结束工作，不与“开始开会”搭配。"}], "explanations": {"到点": "正确：“到点了”说约好的时间已到，与“我们开始开会”相合。", "散会": "语义：“散会”指会议结束，与“开始开会”矛盾。", "放假": "语义：“放假”表示不用上班上课，与开会的语境矛盾。", "下班": "搭配：“下班”指结束工作，不与“开始开会”搭配。"}, "sentence_index": 0, "correct_answer": "到点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的热情到点就熄灭了。", "explanation": "这里应该用〈减退〉。到点只指约定的时刻，热情逐渐消退要说减退。"}, {"text": "他的指甲到点就长了一厘米。", "explanation": "这里应该用〈生长〉。到点只指约定的时刻，指甲的增长要说生长。"}, {"text": "我的体重到点了六十公斤。", "explanation": "这里应该用〈达到〉。到点只用于钟点，体重这类数量要说达到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到点", "is_correct": true, "explanation": "正确：“到点了”说约好的时间已到，老师仍没来，大家着急，语境相符。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课了”说明课已经上完，与“老师还没来”矛盾。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”说明不用上课，与“大家着急”的语境矛盾。"}, {"text": "早退", "is_correct": false, "explanation": "搭配：“早退”指人提前离开，不能用来说老师还没来。"}], "explanations": {"到点": "正确：“到点了”说约好的时间已到，老师仍没来，大家着急，语境相符。", "下课": "语义：“下课了”说明课已经上完，与“老师还没来”矛盾。", "放假": "语义：“放假”说明不用上课，与“大家着急”的语境矛盾。", "早退": "搭配：“早退”指人提前离开，不能用来说老师还没来。"}, "sentence_index": 6, "correct_answer": "到点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的酒量到点就大了。", "explanation": "这里应该用〈提高〉。到点只指约定的时刻，酒量的逐渐提升要说提高。"}, {"text": "这件衣服穿了几年，到点就旧了。", "explanation": "这里应该用〈变旧〉。到点只指约定的时刻，衣服慢慢变旧要说变旧。"}, {"text": "他的成绩到点了九十分。", "explanation": "这里应该用〈达到〉。到点只用于钟点，成绩这类数量要说达到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们到点到点就出发去机场。", "corrected_sentence": "我们到点就出发去机场。", "error_description": "“到点”重复。“到点”只需说一次，应删去多余的“到点”，改为“我们到点就出发去机场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "到点过，我们就去吃饭吧。", "corrected_sentence": "到点了，我们就去吃饭吧。", "error_description": "“到点”表示约定的时间已经到了，后面要用“了”表示完成，不能用“过”。错误的写法是“到点过”，应改为“到点了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
