INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91562, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到了规定的时刻。", "primary_collocate": null, "pronunciation": "dào diǎn", "ipa": "taʊ̯˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "工厂到点就关门。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天到点下班，从不加班。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的铃声一到点就响。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院规定到点才能探视病人。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食堂到点开饭，去晚了就没菜了。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班车到点就发车，不会等人。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到点了，商店该关门了。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆到点闭馆，请大家离开。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工到点打卡，迟到要扣钱。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁到点就停运，别坐过站。", "target_word": "到点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到点了", "label": "体标"}], "register": "口语", "sense_fingerprint": "到了制度或规定所要求的时刻，如上下班、开关门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到点", "is_correct": true, "explanation": "正确：“到点就关门”说规定的时刻一到就关门，符合语境。"}, {"text": "回家", "is_correct": false, "explanation": "语义：工厂不能回家，“回家”的主语只能是人。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只和学校搭配，不说工厂开学。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：工厂不会睡觉，睡觉的主语只能是人或动物。"}], "explanations": {"到点": "正确：“到点就关门”说规定的时刻一到就关门，符合语境。", "回家": "语义：工厂不能回家，“回家”的主语只能是人。", "开学": "搭配：“开学”只和学校搭配，不说工厂开学。", "睡觉": "语义：工厂不会睡觉，睡觉的主语只能是人或动物。"}, "sentence_index": 0, "correct_answer": "到点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔押金三个月后到点退还，请保管好收据。", "explanation": "这里应该用〈到期〉。到点只指一天之内的某个钟点，三个月后的期限要说到期。"}, {"text": "这条路到点了，前面没法走了。", "explanation": "这里应该用〈到头〉。到点只指规定的时刻，路的尽头要说到头。"}, {"text": "我的身高到点了一米八。", "explanation": "这里应该用〈达到〉。到点只用于钟点，身高这类数量要说达到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到点", "is_correct": true, "explanation": "正确：“到点了”说规定的时刻已到，与商店该关门的语境相符。"}, {"text": "开业", "is_correct": false, "explanation": "语义：“开业”指开始营业，与“该关门了”的语境相反。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只和学校搭配，不能说商店开学。"}, {"text": "早退", "is_correct": false, "explanation": "搭配：“早退”指人提前离开，不用于说商店。"}], "explanations": {"到点": "正确：“到点了”说规定的时刻已到，与商店该关门的语境相符。", "开业": "语义：“开业”指开始营业，与“该关门了”的语境相反。", "开学": "搭配：“开学”只和学校搭配，不能说商店开学。", "早退": "搭配：“早退”指人提前离开，不用于说商店。"}, "sentence_index": 6, "correct_answer": "到点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河到点了，前面就是大海。", "explanation": "这里应该用〈到头〉。到点只指规定的钟点，河流的尽头要说到头。"}, {"text": "我的数学成绩到点了九十分。", "explanation": "这里应该用〈达到〉。到点只指规定的钟点，成绩这类数量要说达到。"}, {"text": "他的头发到点就白了一半。", "explanation": "这里应该用〈变白〉。到点只指规定的钟点，头发逐渐变白要说变白。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食堂到点过开饭，大家都去排队。", "corrected_sentence": "食堂到点开饭，大家都去排队。", "error_description": "“过”表示经历，不能直接接在动词“到点”后面。“到点”只说明规定的时刻已到，应删去“过”，改为“食堂到点开饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "超市到点到点关门，别再进去买东西了。", "corrected_sentence": "超市到点关门，别再进去买东西了。", "error_description": "“到点”重复。“到点”只需说一次，应删去多余的“到点”，改为“超市到点关门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
