INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家设立的、组织科学家从事科学研究的最高学术机构。", "primary_collocate": null, "pronunciation": "kē xué yuàn", "ipa": "kʰɤ˥ ɕɥe˧˥ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "他在中国科学院工作。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所研究所隶属于中国科学院。", "target_word": "科学院", "complexity_tier": "T3", "furigana": "zhè suǒ yánjiūsuǒ lìshǔ yú Zhōngguó kēxuéyuàn", "sentence_source": "generated"}, {"text": "这位老人是科学院的院士。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学院每年发表很多研究报告。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去科学院做研究。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家给科学院很多钱做研究。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学院的专家来学校开会。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爸爸是科学院的研究员。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学院是国家最高的学术机构。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的科学院在首都。", "target_word": "科学院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科學院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "科学院：国家最高学术研究机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68bebce-125a-410b-b066-2e5bc672fe83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学家", "is_correct": false, "explanation": "语义：“科学家”指人，不能作工作的处所。"}, {"text": "科学课", "is_correct": false, "explanation": "语义：“科学课”指一门课程，不能作工作的单位。"}, {"text": "科学书", "is_correct": false, "explanation": "搭配：“在……工作”要求处所名词，“科学书”不是处所。"}, {"text": "科学院", "is_correct": true, "explanation": "科学院：国家设立的最高学术研究机构，可作“在……工作”的处所。"}], "explanations": {"科学家": "语义：“科学家”指人，不能作工作的处所。", "科学课": "语义：“科学课”指一门课程，不能作工作的单位。", "科学书": "搭配：“在……工作”要求处所名词，“科学书”不是处所。", "科学院": "科学院：国家设立的最高学术研究机构，可作“在……工作”的处所。"}, "sentence_index": 0, "correct_answer": "科学院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我参观了一只科学院。", "explanation": "这里应该用〈所〉。科学院是机构，量词用“所”，“只”只用于动物或成对事物中的一个。"}, {"text": "这位科学院很有名，大家都很尊敬他。", "explanation": "这里应该用〈院士〉。“科学院”指机构，不能指一个人，也不能用“这位”。"}, {"text": "他的科学院很好，考试都得满分。", "explanation": "这里应该用〈数学〉之类的学科名。“科学院”是机构名，不能拿来指学科或成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”指餐厅，不能指来学校开会的专家所属的机构。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”是设备，不能作专家的所属单位。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“草地”指场地，不能与“的专家”搭配作所属单位。"}, {"text": "科学院", "is_correct": true, "explanation": "科学院：国家最高学术研究机构，其专家来学校开会，句意通顺。"}], "explanations": {"食堂": "语义：“食堂”指餐厅，不能指来学校开会的专家所属的机构。", "电梯": "语义：“电梯”是设备，不能作专家的所属单位。", "草地": "搭配：“草地”指场地，不能与“的专家”搭配作所属单位。", "科学院": "科学院：国家最高学术研究机构，其专家来学校开会，句意通顺。"}, "sentence_index": 6, "correct_answer": "科学院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天去科学院买菜。", "explanation": "这里应该用〈菜市场〉。“科学院”是国家的学术机构，不能用来指买菜的地方。"}, {"text": "这本科学院很有名，我想去看看。", "explanation": "这里应该用〈所〉。“科学院”是机构，不能用“本”来计量。"}, {"text": "我们班的科学院考了第一名。", "explanation": "这里应该用〈班级〉。“科学院”是机构名，不能指班级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只科学院有很多研究员。", "corrected_sentence": "这所科学院有很多研究员。", "error_description": "错误：量词“只”用错。“科学院”是机构，应用“所”，“只”用于动物或成对事物中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的父亲科学院工作。", "corrected_sentence": "他的父亲在科学院工作。", "error_description": "错误：处所介词“在”漏掉。“科学院”作工作地点，前面要加“在”，应说“在科学院工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
