INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "称赞是说别人做得好，夸夸他。", "primary_collocate": null, "pronunciation": "chēng zàn", "ipa": "ʈʂʰəŋ˥ tsan˥˩", "syllable_count": 2, "sentences": [{"text": "老师称赞他今天做得很好。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常常称赞我做的饭。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都称赞她帮助了那位老人。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考了第一名，同学们都称赞他。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理称赞过小王，因为他工作很努力。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做得真好，我要好好称赞你一下。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱得很好听，客人们不停地称赞她。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看了我的画，称赞了我几句。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢别人称赞自己。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当着大家的面称赞了小明。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "称赞了", "label": "完成体"}, {"form": "称赞过", "label": "经历体"}, {"form": "称赞着", "label": "持续体"}, {"form": "稱讚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "称赞｜动词｜对人说好话，夸奖对方做得好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称赞", "is_correct": true, "explanation": "正确：称赞是说别人做得好，与“做得很好”相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是指出缺点，与“做得很好”矛盾。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：惩罚是处罚，不能用来回应“做得很好”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝是不接受，与老师对他“做得很好”的评价矛盾。"}], "explanations": {"称赞": "正确：称赞是说别人做得好，与“做得很好”相符。", "批评": "语义：批评是指出缺点，与“做得很好”矛盾。", "惩罚": "语义：惩罚是处罚，不能用来回应“做得很好”。", "拒绝": "语义：拒绝是不接受，与老师对他“做得很好”的评价矛盾。"}, "sentence_index": 0, "correct_answer": "称赞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司称赞了这次比赛的经费。", "explanation": "这里应该用〈赞助〉。称赞是夸人做得好，出钱支持要用赞助。"}, {"text": "他写错了三道题，老师还是称赞了他的错误。", "explanation": "这里应该用〈指出〉。称赞用于值得肯定的表现，指出他的错误要用“指出”。"}, {"text": "老师称赞了我们明天要考试。", "explanation": "这里应该用〈通知〉。称赞是夸人做得好，告诉大家一件事要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称赞", "is_correct": true, "explanation": "正确：称赞表示夸奖，与“唱得很好听”相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑人，与“唱得很好听”的语境矛盾。"}, {"text": "讽刺", "is_correct": false, "explanation": "语义：讽刺含挖苦之意，与“唱得很好听”不合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是指出缺点，与“唱得很好听”矛盾。"}], "explanations": {"称赞": "正确：称赞表示夸奖，与“唱得很好听”相符。", "嘲笑": "语义：嘲笑是取笑人，与“唱得很好听”的语境矛盾。", "讽刺": "语义：讽刺含挖苦之意，与“唱得很好听”不合。", "批评": "语义：批评是指出缺点，与“唱得很好听”矛盾。"}, "sentence_index": 6, "correct_answer": "称赞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校友会称赞了小明的学费。", "explanation": "这里应该用〈赞助〉。称赞是夸人做得好，出钱资助要用赞助。"}, {"text": "老师当着大家的面称赞了小明的懒惰。", "explanation": "这里应该用〈批评〉。称赞用于值得肯定的表现，指出缺点要用批评。"}, {"text": "老师当着大家的面称赞了小明的请假。", "explanation": "这里应该用〈批准〉。称赞是夸人做得好，同意请假要用批准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前称赞他过。", "corrected_sentence": "我以前称赞过他。", "error_description": "“过”位置错误：体标“过”应紧跟动词，应为“称赞过他”，不能说“称赞他过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "观众称赞了着她的歌声。", "corrected_sentence": "观众称赞着她的歌声。", "error_description": "体标错误：“了”和“着”不能同时用在“称赞”后，应为“观众称赞着她的歌声。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91566, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "批评", "is_correct": true, "explanation": "反义：批评是指出作品或做法的缺点，与“称赞”相对。"}, {"text": "放弃", "is_correct": false, "explanation": "无关：放弃是不再坚持，与“称赞”的任何义项都没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：旅行是出门游览，与“称赞”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：散步是慢走，与“称赞”没有反义关系。"}], "correct_answer": "批评", "explanations": {"批评": "反义：批评是指出作品或做法的缺点，与“称赞”相对。", "放弃": "无关：放弃是不再坚持，与“称赞”的任何义项都没有反义关系。", "旅行": "无关：旅行是出门游览，与“称赞”没有反义关系。", "散步": "无关：散步是慢走，与“称赞”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
