INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用话语表示对人或事的好评。", "primary_collocate": null, "pronunciation": "chēng zàn", "ipa": "ʈʂʰəŋ˥ tsan˥˩", "syllable_count": 2, "sentences": [{"text": "很多人称赞这个电影拍得好。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们都称赞这家饭馆的菜。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师称赞他的作文写得不错。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起称赞这个办法很好。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们称赞我的新家很漂亮。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上称赞这位医生的工作。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的中文说得好，连中国人都称赞。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在会上称赞了学校的新老师。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都称赞过这本书写得好。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人称赞着这里的风景，舍不得走。", "target_word": "称赞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "称赞了", "label": "完成体"}, {"form": "称赞过", "label": "经历体"}, {"form": "称赞着", "label": "持续体"}, {"form": "稱讚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "称赞｜动词｜用话语对人或事物（作品、做法、地方）表示好评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称赞", "is_correct": true, "explanation": "正确：称赞表示对事物的好评，与“拍得好”相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是指出缺点，与“拍得好”矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "语义：参观是去看地方，不能带“这个电影拍得好”这样的评价。"}, {"text": "讽刺", "is_correct": false, "explanation": "语义：讽刺含挖苦之意，与“拍得好”的评价相反。"}], "explanations": {"称赞": "正确：称赞表示对事物的好评，与“拍得好”相符。", "批评": "语义：批评是指出缺点，与“拍得好”矛盾。", "参观": "语义：参观是去看地方，不能带“这个电影拍得好”这样的评价。", "讽刺": "语义：讽刺含挖苦之意，与“拍得好”的评价相反。"}, "sentence_index": 0, "correct_answer": "称赞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都称赞这个电影拍得很烂。", "explanation": "这里应该用〈批评〉。称赞只用于好评，说电影拍得很烂要用批评。"}, {"text": "这家公司称赞了这个办法的预算。", "explanation": "这里应该用〈批准〉。称赞是夸人或事做得好，同意预算要用批准。"}, {"text": "这家饭馆称赞了我们一顿饭。", "explanation": "这里应该用〈请〉。称赞是表示好评，出钱让人吃饭要用请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称赞", "is_correct": true, "explanation": "正确：称赞表示好评，与“中文说得好”相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑，与“中文说得好”的语境不合。"}, {"text": "反对", "is_correct": false, "explanation": "语义：反对是不同意，与“中文说得好”的语境不合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是指出缺点，与“中文说得好”矛盾。"}], "explanations": {"称赞": "正确：称赞表示好评，与“中文说得好”相符。", "嘲笑": "语义：嘲笑是取笑，与“中文说得好”的语境不合。", "反对": "语义：反对是不同意，与“中文说得好”的语境不合。", "批评": "语义：批评是指出缺点，与“中文说得好”矛盾。"}, "sentence_index": 6, "correct_answer": "称赞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客人称赞着这里的脏乱，舍不得走。", "explanation": "这里应该用〈批评〉。称赞用于好的评价，说这里脏乱要用批评。"}, {"text": "客人称赞着这里的垃圾太多。", "explanation": "这里应该用〈抱怨〉。称赞只表示好评，说不满意的事要用抱怨。"}, {"text": "这家公司称赞了这次演出的经费。", "explanation": "这里应该用〈赞助〉。称赞是夸人做得好，出钱支持要用赞助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们称赞了过这部电影。", "corrected_sentence": "我们称赞过这部电影。", "error_description": "体标错误：“了”和“过”不能同时用在“称赞”后，应为“我们称赞过这部电影。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客一直称赞了着这座城市的干净。", "corrected_sentence": "游客一直称赞着这座城市的干净。", "error_description": "体标错误：“了”和“着”不能同时用在“称赞”后，应为“游客一直称赞着这座城市的干净。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
