INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91567, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创业是自己开始做一个新的生意或事情。", "primary_collocate": null, "pronunciation": "chuàng yè", "ipa": "ʈʂʰwɑŋ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他想创业，开一家小饭馆。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸五十岁了还想创业。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创业前，你要先了解市场。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学打算毕业后一起创业。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次创业就赚了钱。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他创业失败了，但没有放弃。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人在网上创业。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创业需要钱，也需要好伙伴。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没钱创业，只好先去打工。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想自己创业，不想给别人打工。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创业者", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己动手开始做新的生意或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创业", "is_correct": true, "explanation": "正确：“想创业，开一家小饭馆”说自己动手做新的生意，语境相符。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”与开一家小饭馆的语境矛盾，不是自己做生意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与开饭馆没有关系，语境不通。"}, {"text": "失业", "is_correct": false, "explanation": "搭配：“失业”指失去工作，不能用“想失业”表示想做生意。"}], "explanations": {"创业": "正确：“想创业，开一家小饭馆”说自己动手做新的生意，语境相符。", "上学": "语义：“上学”与开一家小饭馆的语境矛盾，不是自己做生意。", "睡觉": "语义：“睡觉”与开饭馆没有关系，语境不通。", "失业": "搭配：“失业”指失去工作，不能用“想失业”表示想做生意。"}, "sentence_index": 0, "correct_answer": "创业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里创业，做了一桌好菜。", "explanation": "这里应该用〈做饭〉。创业指自己开始做新的生意，在厨房做饭要说做饭。"}, {"text": "爸爸在客厅里创业，看了两小时电视。", "explanation": "这里应该用〈休息〉。创业指自己开始做新的生意，闲坐看电视要说休息。"}, {"text": "小猫在院子里创业，睡了一下午。", "explanation": "这里应该用〈睡觉〉。创业指自己开始做新的生意，躺着睡一下午要说睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创业", "is_correct": true, "explanation": "正确：“网上创业”指在网络上自己开始做生意，与“现在很多人”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“在网上睡觉”语境不通，与做生意无关。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“在网上洗澡”语境不通，洗澡不在网络上进行。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体状况，不能在网上进行，语境不通。"}], "explanations": {"创业": "正确：“网上创业”指在网络上自己开始做生意，与“现在很多人”的语境相符。", "睡觉": "语义：“在网上睡觉”语境不通，与做生意无关。", "洗澡": "语义：“在网上洗澡”语境不通，洗澡不在网络上进行。", "生病": "语义：“生病”是身体状况，不能在网上进行，语境不通。"}, "sentence_index": 6, "correct_answer": "创业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在医院里创业，等了一上午。", "explanation": "这里应该用〈看病〉。创业指自己开始做新的生意，在医院等了一上午要说看病。"}, {"text": "她在台上创业，唱了三首歌。", "explanation": "这里应该用〈表演〉。创业指自己开始做新的生意，在台上唱歌要说表演。"}, {"text": "孩子在教室里创业，一直在笑。", "explanation": "这里应该用〈玩耍〉。创业指自己开始做新的生意，孩子嬉闹玩耍要说玩耍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想自己创业一家小饭馆。", "corrected_sentence": "他想自己创业，开一家小饭馆。", "error_description": "“创业”本身是动宾结构，不能再带宾语“一家小饭馆”。应分开说成“他想自己创业，开一家小饭馆。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想很创业，不想给别人打工。", "corrected_sentence": "她很想创业，不想给别人打工。", "error_description": "“创业”是动作动词，不能受“很”修饰。“很”应放在“想”前面，改为“她很想创业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
