INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开创事业。", "primary_collocate": null, "pronunciation": "chuàng yè", "ipa": "ʈʂʰwɑŋ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他大学毕业后就决定创业。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人想创业，需要有好想法。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她辞了工作，回家乡创业。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创业的第一年，他们过得很辛苦。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多大学生选择自己创业。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠着一万块钱开始创业。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "创业不容易，要有足够的钱。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北京创业已经五年了。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和朋友一起创业，开一家公司。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她创业成功后，帮助了很多人。", "target_word": "创业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创业者", "label": "复合"}], "register": "中性", "sense_fingerprint": "开创新的事业，多指自己办公司、做生意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创业", "is_correct": true, "explanation": "正确：“决定创业”表示毕业后决定自己开创事业，符合语境。"}, {"text": "留级", "is_correct": false, "explanation": "语义：大学毕业后不会再留级，与“毕业后”的语境矛盾。"}, {"text": "逃课", "is_correct": false, "explanation": "搭配：“逃课”针对正在上课的学生，与毕业后的情境不搭配。"}, {"text": "退学", "is_correct": false, "explanation": "语义：大学毕业后已经不在学校，不能再退学。"}], "explanations": {"创业": "正确：“决定创业”表示毕业后决定自己开创事业，符合语境。", "留级": "语义：大学毕业后不会再留级，与“毕业后”的语境矛盾。", "逃课": "搭配：“逃课”针对正在上课的学生，与毕业后的情境不搭配。", "退学": "语义：大学毕业后已经不在学校，不能再退学。"}, "sentence_index": 0, "correct_answer": "创业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学毕业后创业，进了一家大公司上班。", "explanation": "这里应该用〈就业〉。创业指开创自己的事业，进公司上班要说就业。"}, {"text": "孩子们在操场上创业，玩得很开心。", "explanation": "这里应该用〈玩耍〉。创业指开创事业，孩子在操场上玩耍要说玩耍。"}, {"text": "他在会上创业，讲了半天话。", "explanation": "这里应该用〈发言〉。创业指开创事业，在会上讲话要说发言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创业", "is_correct": true, "explanation": "正确：“创业不容易”说开创事业的困难，与“要有足够的钱”相合。"}, {"text": "失恋", "is_correct": false, "explanation": "语义：“失恋”与钱的多少没有关系，语境不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳不需要“足够的钱”作为前提，语境不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试不容易”与“要有足够的钱”不搭配，考试不需要钱。"}], "explanations": {"创业": "正确：“创业不容易”说开创事业的困难，与“要有足够的钱”相合。", "失恋": "语义：“失恋”与钱的多少没有关系，语境不通。", "游泳": "语义：游泳不需要“足够的钱”作为前提，语境不通。", "考试": "搭配：“考试不容易”与“要有足够的钱”不搭配，考试不需要钱。"}, "sentence_index": 6, "correct_answer": "创业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师站在台上创业，讲了一小时。", "explanation": "这里应该用〈授课〉。创业指开创事业，在台上讲课要说授课。"}, {"text": "这个孩子创业了一晚上，吵得大家都没睡觉。", "explanation": "这里应该用〈哭闹〉。创业指开创事业，孩子哭闹不止要说哭闹。"}, {"text": "她的创业很高，超过了我。", "explanation": "这里应该用〈身高〉。创业指开创事业，身高这类数量不能用创业描写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她大学毕业后就创业了了。", "corrected_sentence": "她大学毕业后就创业了。", "error_description": "“了”重复。“创业”后只需一个“了”表示完成，应改为“创业了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想自己很创业，不想给别人打工。", "corrected_sentence": "她想自己创业，不想给别人打工。", "error_description": "“创业”是动词，不能受程度副词“很”修饰。应删去“很”，改为“她想自己创业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91569, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坐下", "is_correct": true, "explanation": "正确：“坐下”与“站起”是一对反义词，一个是由站到坐，一个是由坐到站。"}, {"text": "走进", "is_correct": false, "explanation": "无关：“走进”描述移动方向，与“站起”的姿势变化没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”与站立、坐下的姿势变化没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”与“站起”不构成反义关系。"}], "correct_answer": "坐下", "explanations": {"坐下": "正确：“坐下”与“站起”是一对反义词，一个是由站到坐，一个是由坐到站。", "走进": "无关：“走进”描述移动方向，与“站起”的姿势变化没有反义关系。", "唱歌": "无关：“唱歌”与站立、坐下的姿势变化没有反义关系。", "吃饭": "无关：“吃饭”与“站起”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
