INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由坐、蹲、卧的姿势变为直立。", "primary_collocate": null, "pronunciation": "zhàn qǐ", "ipa": "ʈʂan˥˩ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他蹲了很久，站起来时腿很麻。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺在地上，听到声音就站起来。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我蹲在花园里，站起来看了看。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "她从地上站起，拍了拍裤子。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人躺了三天，今天终于站起来了。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子蹲着玩，妈妈让他站起来吃饭。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "他从床上站起来，打开了灯。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "蹲着看书的女孩站起来了。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫趴着睡觉，听到门响就站起来跑开了。", "target_word": "站起", "complexity_tier": "T3", "furigana": "zhàn qǐ", "sentence_source": "generated"}, {"text": "老人躺在床上，想自己站起来。", "target_word": "站起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "站起来", "label": "复合"}, {"form": "站起身", "label": "复合"}], "register": "中性", "sense_fingerprint": "站起：由坐、蹲、卧变为直立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68bebce-125a-410b-b066-2e5bc672fe83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站起", "is_correct": true, "explanation": "正确：“站起来”指由蹲变为直立，与“蹲了很久”前后相承。"}, {"text": "挂起", "is_correct": false, "explanation": "搭配：“挂起”指悬挂，人的身体不说“挂起来”。"}, {"text": "飞起", "is_correct": false, "explanation": "语义：人不会“飞起来”，与“蹲了很久”后的起身动作不符。"}, {"text": "翻起", "is_correct": false, "explanation": "配价：“翻起”需带宾语（如“土”“书页”），不能只用于人自身的动作。"}], "explanations": {"站起": "正确：“站起来”指由蹲变为直立，与“蹲了很久”前后相承。", "挂起": "搭配：“挂起”指悬挂，人的身体不说“挂起来”。", "飞起": "语义：人不会“飞起来”，与“蹲了很久”后的起身动作不符。", "翻起": "配价：“翻起”需带宾语（如“土”“书页”），不能只用于人自身的动作。"}, "sentence_index": 0, "correct_answer": "站起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们让那根歪了的电线杆站起来。", "explanation": "这里应该用〈竖起〉。“站起来”只用于人或动物自己从坐、蹲、卧变为直立，竖直的物体要说“竖起”。"}, {"text": "这张桌子突然站起来了。", "explanation": "误用：“站起来”只用于能自主动作的人或动物，桌子不能站起来。"}, {"text": "这块石头突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，石头不能自己站起来，这里应该用〈竖起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站起", "is_correct": true, "explanation": "正确：“站起来”指从床上变为直立，与“从床上”相合。"}, {"text": "脱下", "is_correct": false, "explanation": "配价：“脱下”需带宾语（如“衣服”），不能只说“从床上脱下来”。"}, {"text": "升起", "is_correct": false, "explanation": "语义：“升起”多指太阳、旗子等，人不说“升起来”。"}, {"text": "挂起", "is_correct": false, "explanation": "搭配：“挂起来”指把东西悬挂，人自己不能说“从床上挂起来”。"}], "explanations": {"站起": "正确：“站起来”指从床上变为直立，与“从床上”相合。", "脱下": "配价：“脱下”需带宾语（如“衣服”），不能只说“从床上脱下来”。", "升起": "语义：“升起”多指太阳、旗子等，人不说“升起来”。", "挂起": "搭配：“挂起来”指把东西悬挂，人自己不能说“从床上挂起来”。"}, "sentence_index": 6, "correct_answer": "站起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这扇门突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，门不能自己站起来，这里应该用〈竖起〉。"}, {"text": "这盏灯突然站起来了。", "explanation": "误用：“站起来”只用于能自主动作的人或动物，灯不能站起来。"}, {"text": "这只箱子突然站起来了。", "explanation": "误用：“站起来”的主语须是能自主动作的人或动物，箱子不能自己站起来，这里应该用〈竖起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在桌边坐了很久，终于站起起来。", "corrected_sentence": "她在桌边坐了很久，终于站起来。", "error_description": "重复错误：“站起来”中的“起”不能重复，应说“终于站起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人慢慢从床边站起去，走向窗口。", "corrected_sentence": "老人慢慢从床边站起来，走向窗口。", "error_description": "趋向补语错误：“站起”后应接“来”，不能接“去”，应说“站起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降", "is_correct": true, "explanation": "降：向下移动，与“升”意义相反，二者是反义词。"}, {"text": "走", "is_correct": false, "explanation": "走：指用脚或车辆移动，与“升”的上升义没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：指发出歌声，与“升”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "读：指看着文字发出声音，与“升”没有反义关系。"}], "correct_answer": "降", "explanations": {"降": "降：向下移动，与“升”意义相反，二者是反义词。", "走": "走：指用脚或车辆移动，与“升”的上升义没有反义关系。", "唱": "唱：指发出歌声，与“升”没有反义关系。", "读": "读：指看着文字发出声音，与“升”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降", "is_correct": true, "explanation": "降：向下移动，与“升”意义相反，二者是反义词。"}, {"text": "看", "is_correct": false, "explanation": "看：指用眼睛注视，与“升”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：指把食物咽进肚子，与“升”没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗：指用水去除污垢，与“升”没有反义关系。"}], "correct_answer": "降", "explanations": {"降": "降：向下移动，与“升”意义相反，二者是反义词。", "看": "看：指用眼睛注视，与“升”没有反义关系。", "吃": "吃：指把食物咽进肚子，与“升”没有反义关系。", "洗": "洗：指用水去除污垢，与“升”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "升是慢慢地往上走。", "primary_collocate": null, "pronunciation": "shēng", "ipa": "ʂɤŋ˥", "syllable_count": 1, "sentences": [{"text": "太阳慢慢升上了山顶。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球慢慢升到了空中。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国旗在歌声中升起。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "月亮从海面升上来。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟从屋顶慢慢往上升。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电梯升到了十楼。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机升得很高，我们看不见了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着太阳慢慢升上天空。", "target_word": "升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭从地面升向天空。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看，月亮已经升起来了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升了", "label": "完成体"}, {"form": "升起", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体缓缓向上移动，如太阳、气球、国旗上升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78a3ef50-e145-4c82-a7e3-e5ad63c2ba2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：慢慢地往上走，如太阳、气球上升。"}, {"text": "省", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约、省去，不是往上走。"}, {"text": "胜", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是胜利、超过。"}, {"text": "深", "is_correct": false, "explanation": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是深浅的深。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}], "explanations": {"升": "升（shēng）：慢慢地往上走，如太阳、气球上升。", "省": "shěng（第三声）与 shēng（第一声）声调不同，意思是节约、省去，不是往上走。", "胜": "shèng（第四声）与 shēng（第一声）声调不同，意思是胜利、超过。", "深": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是深浅的深。", "绳": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "降", "is_correct": false, "explanation": "语义：“降”是向下，与“慢慢……上了山顶”的方向相反。"}, {"text": "升", "is_correct": true, "explanation": "升：向上移动，与“慢慢……上了山顶”相合。"}, {"text": "沉", "is_correct": false, "explanation": "语义：“沉”指向下落，不能说太阳“沉上了山顶”。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象通常是可以拿起的物品，不能说太阳被“搬”上山顶。"}], "explanations": {"降": "语义：“降”是向下，与“慢慢……上了山顶”的方向相反。", "升": "升：向上移动，与“慢慢……上了山顶”相合。", "沉": "语义：“沉”指向下落，不能说太阳“沉上了山顶”。", "搬": "搭配：“搬”的对象通常是可以拿起的物品，不能说太阳被“搬”上山顶。"}, "sentence_index": 0, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳从海面升下去了。", "explanation": "这里应该用〈落〉。升指向上移动，太阳向下落到海面以下要用落。"}, {"text": "他慢慢升上了楼梯。", "explanation": "这里应该用〈走〉。升指太阳、气球等物体自己向上移动，人沿楼梯上去要用走。"}, {"text": "苹果从树上升下来了。", "explanation": "这里应该用〈掉〉。升指向上移动，苹果往下落要用掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：慢慢地往上走，如太阳、气球上升。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。"}, {"text": "身", "is_correct": false, "explanation": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。"}, {"text": "剩", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}], "explanations": {"升": "升（shēng）：慢慢地往上走，如太阳、气球上升。", "伤": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。", "身": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。", "争": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。", "剩": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "搭配：“跑”指用腿或车辆在地面快速移动，不能说飞机“跑得很高”。"}, {"text": "升", "is_correct": true, "explanation": "升：向上飞，与“很高”和“看不见了”相合。"}, {"text": "降", "is_correct": false, "explanation": "语义：“降”是向下，与“很高”的方向相反。"}, {"text": "跌", "is_correct": false, "explanation": "语义：“跌”指失足或下落，与飞机飞得很高矛盾。"}], "explanations": {"跑": "搭配：“跑”指用腿或车辆在地面快速移动，不能说飞机“跑得很高”。", "升": "升：向上飞，与“很高”和“看不见了”相合。", "降": "语义：“降”是向下，与“很高”的方向相反。", "跌": "语义：“跌”指失足或下落，与飞机飞得很高矛盾。"}, "sentence_index": 6, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把信升上了楼。", "explanation": "这里应该用〈送〉。升指物体自己往上移动，把信送上楼要用送，不能用升。"}, {"text": "蜗牛慢慢升上了墙。", "explanation": "这里应该用〈爬〉。升不指靠身体一点点攀登，蜗牛自己爬行要用爬。"}, {"text": "石头升进了水里。", "explanation": "这里应该用〈沉〉。升是往上，石头往水底下去要用沉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "热气球慢慢升下了天空。", "corrected_sentence": "热气球慢慢升上了天空。", "error_description": "补语错误：“升”表示向上，应说“升上了天空”；“升下”的方向与“升”相反，不能这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月亮正慢慢升了着，天渐渐黑了。", "corrected_sentence": "月亮正慢慢升着，天渐渐黑了。", "error_description": "体标错误：“了”与“着”不能同时用在“升”后（“升了着”不成立）；表示动作持续只用“着”，应说“正慢慢升着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降", "is_correct": true, "explanation": "降：数量或等级向下变化，与“升”意义相反，二者是反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑：指快速移动，与“升”没有反义关系。"}, {"text": "说", "is_correct": false, "explanation": "说：指用话语表达，与“升”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "读：指看着文字发出声音，与“升”没有反义关系。"}], "correct_answer": "降", "explanations": {"降": "降：数量或等级向下变化，与“升”意义相反，二者是反义词。", "跑": "跑：指快速移动，与“升”没有反义关系。", "说": "说：指用话语表达，与“升”没有反义关系。", "读": "读：指看着文字发出声音，与“升”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降", "is_correct": true, "explanation": "降：等级向下变化，与“升”意义相反，二者是反义词。"}, {"text": "看", "is_correct": false, "explanation": "看：指用眼睛注视，与“升”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：指把食物咽进肚子，与“升”没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗：指用水去除污垢，与“升”没有反义关系。"}], "correct_answer": "降", "explanations": {"降": "降：等级向下变化，与“升”意义相反，二者是反义词。", "看": "看：指用眼睛注视，与“升”没有反义关系。", "吃": "吃：指把食物咽进肚子，与“升”没有反义关系。", "洗": "洗：指用水去除污垢，与“升”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由低往高移动；提高。", "primary_collocate": null, "pronunciation": "shēng", "ipa": "ʂɤŋ˥", "syllable_count": 1, "sentences": [{"text": "今天气温升到了三十五度。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月房价又升了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今年升了一级。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水位升得很快。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油价升了，坐车也贵了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小职员升为经理。", "target_word": "升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "病人的体温升到了三十九度。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水已经升到了桥边。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工资升了不少。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们明年就升三年级了。", "target_word": "升", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升了", "label": "完成体"}, {"form": "升高", "label": "复合"}, {"form": "升级", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量、等级、位置等由低变高，如气温、价格、级别上升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78a3ef50-e145-4c82-a7e3-e5ad63c2ba2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：数量、等级由低变高，如气温、价格上升。"}, {"text": "省", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是节省。"}, {"text": "盛", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是盛大、茂盛。"}, {"text": "圣", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是神圣。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}], "explanations": {"升": "升（shēng）：数量、等级由低变高，如气温、价格上升。", "省": "shěng（第三声）与 shēng（第一声）声调不同，意思是节省。", "盛": "shèng（第四声）与 shēng（第一声）声调不同，意思是盛大、茂盛。", "圣": "shèng（第四声）与 shēng（第一声）声调不同，意思是神圣。", "绳": "shéng（第二声）与 shēng（第一声）声调不同，意思是绳子。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”是发出歌声，不能说气温“唱到”三十五度。"}, {"text": "升", "is_correct": true, "explanation": "升：数量向上变化，气温升到三十五度，表示温度上升。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”是用笔记录文字，与气温变化无关。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于气温。"}], "explanations": {"唱": "搭配：“唱”是发出歌声，不能说气温“唱到”三十五度。", "升": "升：数量向上变化，气温升到三十五度，表示温度上升。", "写": "语义：“写”是用笔记录文字，与气温变化无关。", "吃": "搭配：“吃”的对象是食物，不能用于气温。"}, "sentence_index": 0, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把纸箱升上了二楼，累得不行。", "explanation": "这里应该用〈搬〉。升指事物自己由低往高移动，人把纸箱搬上楼要用搬。"}, {"text": "他往杯子里升了很多水。", "explanation": "这里应该用〈倒〉。升指事物自己由低往高移动或数量增加，往杯子里注入水要用倒。"}, {"text": "我吃得太多，肚子升得难受。", "explanation": "这里应该用〈胀〉。升不能描述肚子因充满而变大，胀才表示膨胀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升", "is_correct": true, "explanation": "升（shēng）：数量、等级由低变高，如气温、价格上升。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。"}, {"text": "身", "is_correct": false, "explanation": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。"}, {"text": "剩", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}], "explanations": {"升": "升（shēng）：数量、等级由低变高，如气温、价格上升。", "伤": "shāng 与 shēng 韵母不同（-ang 与 -eng），意思是受伤。", "争": "zhēng 与 shēng 声母不同（zh 与 sh），意思是争夺。", "身": "shēn 与 shēng 韵母不同（-en 与 -eng），意思是身体。", "剩": "shèng（第四声）与 shēng（第一声）声调不同，意思是剩下。"}, "sentence_index": null, "correct_answer": "升"}, "level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "搭配：“睡”是人的动作，不能说体温“睡到”三十九度。"}, {"text": "升", "is_correct": true, "explanation": "升：数量向上变化，体温升到三十九度，表示发烧。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中移动，与体温变化无关。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能用于体温。"}], "explanations": {"睡": "搭配：“睡”是人的动作，不能说体温“睡到”三十九度。", "升": "升：数量向上变化，体温升到三十九度，表示发烧。", "游": "语义：“游”指在水中移动，与体温变化无关。", "喝": "搭配：“喝”的对象是液体，不能用于体温。"}, "sentence_index": 6, "correct_answer": "升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把货物升上了车。", "explanation": "这里应该用〈装〉。升指事物自己由低往高移动，人把货物放上车要用装。"}, {"text": "他把钱升进了口袋。", "explanation": "这里应该用〈放〉。升指事物自己由低往高移动或数量增加，把钱放进口袋要用放。"}, {"text": "书从桌上升下来了。", "explanation": "这里应该用〈掉〉。升是向上，书往下落要用掉，与等级无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水位升在了三米。", "corrected_sentence": "水位升到了三米。", "error_description": "补语错误：表示水位升高到某个数值要用“到”，不能用“在”，应说“水位升到了三米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
