INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不好的地方。", "primary_collocate": null, "pronunciation": "quē diǎn", "ipa": "tɕʰɥe˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "每个人都有自己的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最大的缺点是不爱说话。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多看别人的优点，少看缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的缺点是电池太小。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道自己的缺点，所以每天努力改。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服样子好看，就是有一个缺点：太贵。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说说这个方法的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的缺点是离地铁太远。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很懒，这是他的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我，我有什么缺点？", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个缺点", "label": "量词"}, {"form": "优缺点", "label": "复合"}, {"form": "缺點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或事物不好的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“缺点”指不好的地方，可以说“自己的缺点”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能说“每个人都有自己的天气”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是公共的自然事物，不能说“每个人都有自己的河流”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“自己的”不能修饰“空气”，这一搭配不成立。"}], "explanations": {"缺点": "正确：“缺点”指不好的地方，可以说“自己的缺点”。", "天气": "语义：天气是自然现象，不能说“每个人都有自己的天气”。", "河流": "语义：河流是公共的自然事物，不能说“每个人都有自己的河流”。", "空气": "搭配：“自己的”不能修饰“空气”，这一搭配不成立。"}, "sentence_index": 0, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车前几天出了缺点，只好送去修理。", "explanation": "这里应该用〈毛病〉。“缺点”指事物的不足之处，车或机器发生故障要说“出了毛病”，不说“出了缺点”。"}, {"text": "我在他身上发现了一只缺点。", "explanation": "这里应该用〈个〉。“缺点”前用量词“个”，“只”多用于动物或成对物中的一个，不能修饰“缺点”。"}, {"text": "他很擅长发挥自己的缺点。", "explanation": "这里应该用〈长处〉。“发挥”搭配“长处、优点、作用”等积极的东西，不能说“发挥缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“缺点”指不好的地方，可以说“这个方法的缺点”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：方法没有颜色，“这个方法的颜色”不成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于人的体型，不能说“方法的身材”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”指人的情绪，不能说“这个方法的心情”。"}], "explanations": {"缺点": "正确：“缺点”指不好的地方，可以说“这个方法的缺点”。", "颜色": "语义：方法没有颜色，“这个方法的颜色”不成立。", "身材": "体貌：“身材”只用于人的体型，不能说“方法的身材”。", "心情": "语义：“心情”指人的情绪，不能说“这个方法的心情”。"}, "sentence_index": 6, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该扩大自己的缺点。", "explanation": "这里应该用〈优势〉。“扩大”搭配“优势、范围、影响”等，“缺点”是要改正的，不能被扩大。"}, {"text": "大家要互相发扬对方的缺点。", "explanation": "这里应该用〈优点〉。“发扬”搭配“优点、传统”等值得推广的东西，“缺点”应该改正，不能发扬。"}, {"text": "他这次比赛又吃了一个缺点。", "explanation": "这里应该用〈暴露〉。“吃”不能与“缺点”搭配，常说“暴露缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人的一只缺点很明显。", "corrected_sentence": "这个人的一个缺点很明显。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“一只缺点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把这只缺点改掉。", "corrected_sentence": "我们要把这个缺点改掉。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“这只缺点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
