INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "欠缺或不完美之处；与“优点”相对。", "primary_collocate": null, "pronunciation": "quē diǎn", "ipa": "tɕʰɥe˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这篇文章有优点，也有缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友指出了我的缺点，我很感谢。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在努力改正自己的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划的优点很多，缺点只有一个。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骄傲是很多年轻人的缺点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看人不能只看缺点，也要看优点。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我写字的缺点是太慢。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个设计的缺点，大家都看出来了。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的缺点和优点一样明显。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对自己的缺点，我们不要害怕。", "target_word": "缺点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个缺点", "label": "量词"}, {"form": "优缺点", "label": "复合"}, {"form": "缺點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "欠缺、不完美之处，与优点相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“有……，也有……”后接与“优点”相对的“缺点”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“这篇文章有……”后不能接“桌子”，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：文章不能“有天气”，这一搭配没有意义。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“这篇文章有……”后不接“空气”，这一搭配不成立。"}], "explanations": {"缺点": "正确：“有……，也有……”后接与“优点”相对的“缺点”。", "桌子": "搭配：“这篇文章有……”后不能接“桌子”，句子不成立。", "天气": "语义：文章不能“有天气”，这一搭配没有意义。", "空气": "搭配：“这篇文章有……”后不接“空气”，这一搭配不成立。"}, "sentence_index": 0, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱出了缺点，要找人来修。", "explanation": "这里应该用〈毛病〉。“缺点”指事物的不足之处，机器发生故障要说“出了毛病”。"}, {"text": "我觉得他最大的一只缺点是爱迟到。", "explanation": "这里应该用〈个〉。“缺点”前用量词“个”，“只”多用于动物或成对物中的一个，不能修饰“缺点”。"}, {"text": "比赛中他充分发挥了自己的缺点。", "explanation": "这里应该用〈长处〉。“发挥”搭配“长处、优点、作用”等积极的东西，不能说“发挥缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺点", "is_correct": true, "explanation": "正确：“缺点”指不好的方面，可以说“写字的缺点”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“写字的桌子”不能作“太慢”的主语，句子无法成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于人的体型，不能说“写字的身材”。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”是时间概念，不能说“写字的季节是太慢”。"}], "explanations": {"缺点": "正确：“缺点”指不好的方面，可以说“写字的缺点”。", "桌子": "语义：“写字的桌子”不能作“太慢”的主语，句子无法成立。", "身材": "体貌：“身材”只用于人的体型，不能说“写字的身材”。", "季节": "语义：“季节”是时间概念，不能说“写字的季节是太慢”。"}, "sentence_index": 6, "correct_answer": "缺点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司一直在扩大产品的缺点。", "explanation": "这里应该用〈优势〉。“扩大”搭配“优势、范围、影响”等，“缺点”不能被扩大。"}, {"text": "我们要把团队的缺点发扬光大。", "explanation": "这里应该用〈优点〉。“发扬光大”用于优点、传统等值得推广的东西，“缺点”不能发扬光大。"}, {"text": "他这次考试又喝了一个缺点。", "explanation": "这里应该用〈暴露〉。“喝”不能与“缺点”搭配，常说“暴露缺点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次作业的一只缺点是字写得太小。", "corrected_sentence": "这次作业的一个缺点是字写得太小。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“一只缺点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把这只缺点讲清楚了。", "corrected_sentence": "他终于把这个缺点讲清楚了。", "error_description": "量词错误：“缺点”前应用量词“个”，“只”多用于动物，不能说“这只缺点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
