INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网版是印东西时用的有小孔的网板。", "primary_collocate": null, "pronunciation": "wǎng bǎn", "ipa": "uaŋ˨˩˦ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "工人把油墨倒在网版上，再用刮板刮平。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张网版的小孔太细，油墨过不去。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "印衣服以前，要先做好一张网版。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用完网版以后，要马上用水洗干净。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅在网版上涂了一层感光胶。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块网版用了很多次，已经有点旧了。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油墨穿过网版上的小孔，印在布上。", "target_word": "网版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了印花用的网版。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网版要放平，别压坏了上面的小孔。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店里有三张不同图案的网版。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "网版印刷", "label": "复合"}, {"form": "網版", "label": "繁体"}], "register": "中性", "sense_fingerprint": "印刷时用的带小孔的网板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91577, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "网版", "is_correct": true, "explanation": "网版是印东西时用的有小孔的网板，是本词的正确读音与意思。"}, {"text": "往返", "is_correct": false, "explanation": "bǎn 与 fǎn 声母不同（b 与 f），意思是来回往返，不是网版。"}, {"text": "网办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是在网上办理，不是网版。"}, {"text": "望板", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，望板是屋顶椽子上铺的木板，不是网版。"}], "explanations": {"网版": "网版是印东西时用的有小孔的网板，是本词的正确读音与意思。", "往返": "bǎn 与 fǎn 声母不同（b 与 f），意思是来回往返，不是网版。", "网办": "bàn（第四声）与 bǎn（第三声）声调不同，意思是在网上办理，不是网版。", "望板": "wàng（第四声）与 wǎng（第三声）声调不同，望板是屋顶椽子上铺的木板，不是网版。"}, "sentence_index": null, "correct_answer": "网版"}, "level_3": {"options": [{"text": "网版", "is_correct": true, "explanation": "网版是印刷用的网板，油墨倒在上面再用刮板刮平，符合句意。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗是盛饭的器皿，油墨不会倒在上面再用刮板刮平。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“倒在……上”和“刮平”说的是印版，不说倒在眼镜上。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能作为刮平油墨的承印面。"}], "explanations": {"网版": "网版是印刷用的网板，油墨倒在上面再用刮板刮平，符合句意。", "饭碗": "语义：饭碗是盛饭的器皿，油墨不会倒在上面再用刮板刮平。", "眼镜": "搭配：“倒在……上”和“刮平”说的是印版，不说倒在眼镜上。", "饼干": "语义：饼干是食物，不能作为刮平油墨的承印面。"}, "sentence_index": 0, "correct_answer": "网版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都去网版跑步。", "explanation": "这里把网版当成了〈场所〉。网版是印刷用的器具，不是可以去跑步的地方，应说〈公园〉这类场所。"}, {"text": "他把网版穿在身上出门了。", "explanation": "这里把网版当成了〈衣服〉。网版是印刷用的网板，不能穿在身上。"}, {"text": "他把网版喝了下去。", "explanation": "这里把网版当成了〈饮料〉，可以喝下去。网版是印刷用的器具，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网版", "is_correct": true, "explanation": "网版上有小孔，油墨穿过小孔印在布上，符合句意。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯不是印刷用的网板，油墨不会穿过茶杯上的小孔印布。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，与油墨穿过小孔印布的过程无关。"}, {"text": "耳朵", "is_correct": false, "explanation": "体貌：耳朵是身体部位，油墨不能穿过它印字。"}], "explanations": {"网版": "网版上有小孔，油墨穿过小孔印在布上，符合句意。", "茶杯": "语义：茶杯不是印刷用的网板，油墨不会穿过茶杯上的小孔印布。", "书桌": "语义：书桌是家具，与油墨穿过小孔印布的过程无关。", "耳朵": "体貌：耳朵是身体部位，油墨不能穿过它印字。"}, "sentence_index": 6, "correct_answer": "网版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张网版是用来做饭的。", "explanation": "这里把网版当成了〈炊具〉。网版是印刷用的网板，不能用来做饭，做饭应使用〈锅〉之类的炊具。"}, {"text": "他是网版。", "explanation": "这里把网版当成了〈职员〉这类指人的词。网版是印刷器具，不能用来指人。"}, {"text": "工人用网版把油墨刮平。", "explanation": "工具错误。刮平油墨要用刮板，网版是承载图案的网板，不能用来刮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "师傅把一根网版放平了。", "corrected_sentence": "师傅把一张网版放平了。", "error_description": "量词错误：网版是平板状，量词应为“张”，不能用“根”。“根”多用于细长的东西。应说“师傅把一张网版放平了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌子上放着两本刚做好的网版。", "corrected_sentence": "桌子上放着两张刚做好的网版。", "error_description": "量词错误：网版是平板状，量词应为“张”，不能用“本”。“本”用于书本。应说“桌子上放着两张刚做好的网版”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
