INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "丝网印刷中带有图案孔洞的网状版。", "primary_collocate": null, "pronunciation": "wǎng bǎn", "ipa": "uaŋ˨˩˦ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "丝网印刷前，要先把图案做在网版上。", "target_word": "网版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网版上有图案的地方，油墨才能漏下去。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用网版在帆布包上印了一只小猫。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个工厂用网版印茶杯上的花纹。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网版的网眼越细，印出来的线条越清楚。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图案做好以后，要把它晒到网版上。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了一张新网版，印出来的字更清楚。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有网版，就没办法大量印同样的图案。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅正在检查网版有没有堵住的孔。", "target_word": "网版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种网版是用尼龙网做成的，很结实。", "target_word": "网版", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "网版印刷", "label": "复合"}, {"form": "網版", "label": "繁体"}], "register": "中性", "sense_fingerprint": "丝网印刷中带图案孔洞的网状版", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91578, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "网版", "is_correct": true, "explanation": "网版是丝网印刷中带图案孔洞的网状版，是本词的正确读音与意思。"}, {"text": "往返", "is_correct": false, "explanation": "bǎn 与 fǎn 声母不同（b 与 f），意思是来回往返，不是网版。"}, {"text": "网办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是在网上办理，不是网版。"}, {"text": "望板", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，望板是屋顶椽子上铺的木板，不是网版。"}], "explanations": {"网版": "网版是丝网印刷中带图案孔洞的网状版，是本词的正确读音与意思。", "往返": "bǎn 与 fǎn 声母不同（b 与 f），意思是来回往返，不是网版。", "网办": "bàn（第四声）与 bǎn（第三声）声调不同，意思是在网上办理，不是网版。", "望板": "wàng（第四声）与 wǎng（第三声）声调不同，望板是屋顶椽子上铺的木板，不是网版。"}, "sentence_index": null, "correct_answer": "网版"}, "level_3": {"options": [{"text": "网版", "is_correct": true, "explanation": "网版是丝网印刷用的承印版，图案要先做在上面，符合句意。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价是买票的钱，图案不能做在票价上。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“做在……上”说的是承印物，不说做在体重上。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗不是丝网印刷的承印面，图案不会做在饭碗上。"}], "explanations": {"网版": "网版是丝网印刷用的承印版，图案要先做在上面，符合句意。", "票价": "语义：票价是买票的钱，图案不能做在票价上。", "体重": "搭配：“做在……上”说的是承印物，不说做在体重上。", "饭碗": "语义：饭碗不是丝网印刷的承印面，图案不会做在饭碗上。"}, "sentence_index": 0, "correct_answer": "网版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这网版是甜的。", "explanation": "这里把网版说成了〈糖〉一类的甜食。网版是印刷用的网板，没有甜味，不能说是甜的。"}, {"text": "他每天晚上都去网版散步。", "explanation": "这里把网版当成了〈场所〉。网版是印刷用的网板，不是可以去散步的地方，应说〈公园〉这类场所。"}, {"text": "这网版在夏天会开花。", "explanation": "这里把网版当成了〈植物〉。网版是印刷器具，不会开花，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网版", "is_correct": true, "explanation": "网版可以换新，换了新网版，印出来的字才会更清楚，符合句意。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发与印刷字迹是否清楚无关，换沙发不会让印字更清楚。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是印刷器材，与印出来的字是否清楚没有关系。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：脸是人的面部，“换一张新脸”与印字清楚无关，不合句意。"}], "explanations": {"网版": "网版可以换新，换了新网版，印出来的字才会更清楚，符合句意。", "沙发": "语义：沙发与印刷字迹是否清楚无关，换沙发不会让印字更清楚。", "窗帘": "语义：窗帘不是印刷器材，与印出来的字是否清楚没有关系。", "脸": "体貌：脸是人的面部，“换一张新脸”与印字清楚无关，不合句意。"}, "sentence_index": 6, "correct_answer": "网版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用网版做饭。", "explanation": "这里把网版当成了〈炊具〉。网版是印刷用的网板，不能用来做饭，做饭应使用〈锅〉之类的炊具。"}, {"text": "他喝了一口网版。", "explanation": "这里把网版当成了〈饮料〉来喝。网版是印刷用的网板，不能喝，应说〈饮料〉之类可以喝的东西。"}, {"text": "工人用网版把油墨抹平。", "explanation": "工具错误。抹平油墨要用刮板，网版是承载图案的网板，不能用来抹平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一根新网版放在了桌子上。", "corrected_sentence": "他把一张新网版放在了桌子上。", "error_description": "量词错误：网版是平板状，量词应为“张”，不能用“根”。“根”多用于细长的东西。应说“他把一张新网版放在了桌子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本网版是用尼龙网做成的，很结实。", "corrected_sentence": "这张网版是用尼龙网做成的，很结实。", "error_description": "量词错误：网版是平板状，量词应为“张”，不能用“本”。“本”用于书本。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
