INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91579, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南方是太阳中午时在的那个方向。", "primary_collocate": null, "pronunciation": "nán fāng", "ipa": "nan˧˥ faŋ˥", "syllable_count": 2, "sentences": [{"text": "中午我面朝南方，太阳就在那边的天空。", "target_word": "南方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿朝着南方飞去。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房子的窗户朝向南方。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "指南针的一头指向南方。", "target_word": "南方", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天黑了，他往南方走去。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你面对北方，南方在你的后面。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳从东边升起，中午走到南方。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看着南方，那里有一座山。", "target_word": "南方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雁从北边朝南方飞去。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在门口，我看见南方有一片云。", "target_word": "南方", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "南方人", "label": "复合"}, {"form": "南方菜", "label": "复合"}], "register": "中性", "sense_fingerprint": "太阳中午所在的方向，用于指明方位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78a3ef50-e145-4c82-a7e3-e5ad63c2ba2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "北方", "is_correct": false, "explanation": "语义：中午太阳在南方，面朝北方时太阳不在那边，与“中午”不符。"}, {"text": "南方", "is_correct": true, "explanation": "南方：太阳中午所在的方向，与“太阳就在那边的天空”相合。"}, {"text": "东方", "is_correct": false, "explanation": "语义：东方是太阳早晨升起的方向，与“中午”不符。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“面朝”后面要接方向，“房间”不是方向，不能说面朝房间。"}], "explanations": {"北方": "语义：中午太阳在南方，面朝北方时太阳不在那边，与“中午”不符。", "南方": "南方：太阳中午所在的方向，与“太阳就在那边的天空”相合。", "东方": "语义：东方是太阳早晨升起的方向，与“中午”不符。", "房间": "搭配：“面朝”后面要接方向，“房间”不是方向，不能说面朝房间。"}, "sentence_index": 0, "correct_answer": "南方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很多珍稀动物生活在南方非洲。", "explanation": "这里应该用〈南部〉。“南部非洲”是固定的地区名称，不能用南方代替。"}, {"text": "这条山脉是南方走向的。", "explanation": "这里应该用〈南北〉。“南北走向”是固定说法，南方不能用来指走向。"}, {"text": "我的书包放在桌子的南方。", "explanation": "这里应该用〈南边〉。南方指较大的方向或地区，桌子上的具体位置要说南边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西方", "is_correct": false, "explanation": "语义：西方是太阳傍晚落下的方向，中午不会走到那里。"}, {"text": "南方", "is_correct": true, "explanation": "南方：中午太阳所在的方向，与“走到”相合。"}, {"text": "北边", "is_correct": false, "explanation": "语义：中午太阳在南方，不会走到北边。"}, {"text": "屋里", "is_correct": false, "explanation": "搭配：太阳不能“走到屋里”，“走到”后接的地点要与太阳的运行相合。"}], "explanations": {"西方": "语义：西方是太阳傍晚落下的方向，中午不会走到那里。", "南方": "南方：中午太阳所在的方向，与“走到”相合。", "北边": "语义：中午太阳在南方，不会走到北边。", "屋里": "搭配：太阳不能“走到屋里”，“走到”后接的地点要与太阳的运行相合。"}, "sentence_index": 6, "correct_answer": "南方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在我的南方。", "explanation": "这里应该用〈南边〉。南方指较大的方向或地区，人站在身边的位置要说南边。"}, {"text": "我把钥匙放在抽屉的南方。", "explanation": "这里应该用〈南边〉。南方指较大的方向或地区，抽屉旁的具体位置要说南边。"}, {"text": "这颗纽扣的南方有一个洞。", "explanation": "这里应该用〈南边〉。南方指较大的方向或地区，纽扣这样的小东西要说南边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐车南方走。", "corrected_sentence": "我们坐车往南方走。", "error_description": "介词缺失：表示方向要用“往”（或“向”）引出“南方”，不能直接说“坐车南方走”，应说“往南方走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们南方望去。", "corrected_sentence": "孩子们朝南方望去。", "error_description": "介词缺失：表示方向要用“朝”（或“向”）引出“南方”，不能直接说“南方望去”，应说“朝南方望去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
