INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91581, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老太太是年纪很大的女人。", "primary_collocate": null, "pronunciation": "lǎo tài tai", "ipa": "lau˨˩ tʰai˥˩ tʰai", "syllable_count": 3, "sentences": [{"text": "那位老太太每天早上都去公园走路。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位老太太坐在门口晒太阳。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老太太头发白了，可是身体很好。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家楼下住着一位老太太。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老太太手里提着一个大包。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车上，一个年轻人给老太太让座。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老太太已经八十岁了。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老太太笑着给孩子们讲故事。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我帮老太太把菜拿回了家。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老太太戴着一副眼镜在看报纸。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老太太们", "label": "复数"}], "register": "口语", "sense_fingerprint": "指年纪很大的女人，描述人物时使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“那位汽车”，汽车也不会去公园走路。"}, {"text": "老太太", "is_correct": true, "explanation": "“老太太”指年纪很大的女人，与“那位”和“去公园走路”的语境相符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，不是人，不能自己去公园走路。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会去公园走路。"}], "explanations": {"汽车": "搭配：量词“位”只用于人，不能说“那位汽车”，汽车也不会去公园走路。", "老太太": "“老太太”指年纪很大的女人，与“那位”和“去公园走路”的语境相符。", "玩具": "语义：玩具是物品，不是人，不能自己去公园走路。", "桌子": "语义：桌子是家具，不会去公园走路。"}, "sentence_index": 0, "correct_answer": "老太太"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "广场上跳舞的老太太大多只有三十多岁。", "explanation": "这里应该用〈阿姨〉。“老太太”指年纪很大的女人，三十多岁的女性要说“阿姨”。"}, {"text": "我妹妹是一位老太太，今年才十岁。", "explanation": "这里应该用〈小姑娘〉。“老太太”指年纪很大的女人，不能用来指十岁的孩子。"}, {"text": "这个老太太刚上小学一年级，今年七岁。", "explanation": "这里应该用〈小女孩〉。“老太太”指年纪很大的女人，七岁的小学生要说“小女孩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“这位树”。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿刚出生，不可能已经八十岁了。"}, {"text": "老太太", "is_correct": true, "explanation": "“老太太”指年老的女性，与“已经八十岁了”相符。"}, {"text": "小姑娘", "is_correct": false, "explanation": "语义：小姑娘指年幼的女孩，与“已经八十岁了”矛盾。"}], "explanations": {"树": "搭配：量词“位”只用于人，不能说“这位树”。", "婴儿": "语义：婴儿刚出生，不可能已经八十岁了。", "老太太": "“老太太”指年老的女性，与“已经八十岁了”相符。", "小姑娘": "语义：小姑娘指年幼的女孩，与“已经八十岁了”矛盾。"}, "sentence_index": 6, "correct_answer": "老太太"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爷爷是一位老太太，每天早上都去公园打太极。", "explanation": "这里应该用〈老先生〉。“老太太”指年纪很大的女人，爷爷是男性，要说“老先生”。"}, {"text": "这辆旧自行车是老太太，骑起来嘎吱响。", "explanation": "这里应该用〈旧货〉。“老太太”指年纪很大的女人，不能用来指自行车这类物品。"}, {"text": "这台旧电脑是老太太，已经用了十年。", "explanation": "这里应该用〈老古董〉。“老太太”指年纪很大的女人，不能用来比喻旧机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家对面住着一只老太太，每天都给我们送菜。", "corrected_sentence": "我家对面住着一位老太太，每天都给我们送菜。", "error_description": "量词错误：指人的“老太太”应该用“位”计量，“只”用于动物或物品，应改为“一位老太太”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街角的长椅上坐着一位的老太太，正在看书。", "corrected_sentence": "街角的长椅上坐着一位老太太，正在看书。", "error_description": "结构错误：数量短语“一位”修饰名词时不加“的”，应说“一位老太太”，不能说“一位的老太太”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
