INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对年老妇女的称呼。", "primary_collocate": null, "pronunciation": "lǎo tài tai", "ipa": "lau˨˩ tʰai˥˩ tʰai", "syllable_count": 3, "sentences": [{"text": "老太太，您慢点儿走。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老太太，您要去哪儿？", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都叫她张老太太。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王对老太太说：“请坐这儿。”", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老太太，这个包是您的吗？", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都很尊敬王老太太。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老太太，您今天身体好吗？", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们叫她李老太太，她很高兴。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "售货员对老太太说：“您拿好。”", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老太太，天黑了，我送您回家吧。", "target_word": "老太太", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老太太们", "label": "复数"}], "register": "口语", "sense_fingerprint": "当面或背后尊敬地称呼年老的妇女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a85b2443-ac17-43fe-8739-349acbe3fea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能被称呼为“您”，也不会走路。"}, {"text": "老太太", "is_correct": true, "explanation": "“老太太”是对年老妇女的称呼，与“您慢点儿走”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不会走路，也不能被称呼为“您”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能被称呼为“您”。"}], "explanations": {"桌子": "语义：桌子不是人，不能被称呼为“您”，也不会走路。", "老太太": "“老太太”是对年老妇女的称呼，与“您慢点儿走”的语境相符。", "石头": "语义：石头是无生命的东西，不会走路，也不能被称呼为“您”。", "汽车": "语义：汽车是交通工具，不能被称呼为“您”。"}, "sentence_index": 0, "correct_answer": "老太太"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小王对老大爷说：“老太太，请坐这儿。”", "explanation": "这里应该用〈老先生〉。“老太太”只用于称呼年老的妇女，对老年男子应称“老先生”。"}, {"text": "小王对一位年轻姑娘说：“老太太，请坐这儿。”", "explanation": "这里应该用〈小姐〉。“老太太”只用于称呼年纪大的妇女，不能称呼年轻姑娘。"}, {"text": "小王对刚进门的女大学生说：“老太太，您先坐。”", "explanation": "这里应该用〈同学〉。“老太太”只称呼年老的妇女，不能用来称呼年轻的大学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，没有身体，不能问“身体好吗”。"}, {"text": "老太太", "is_correct": true, "explanation": "“老太太”是对年老妇女的称呼，可以用“您”来问候。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，没有身体，不能这样问候。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，没有身体，不能这样问候。"}], "explanations": {"书包": "语义：书包是物品，没有身体，不能问“身体好吗”。", "老太太": "“老太太”是对年老妇女的称呼，可以用“您”来问候。", "玩具": "语义：玩具是物品，没有身体，不能这样问候。", "花瓶": "语义：花瓶是器物，没有身体，不能这样问候。"}, "sentence_index": 6, "correct_answer": "老太太"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈对一个小朋友说：“老太太，你慢点儿跑。”", "explanation": "这里应该用〈小孩〉。“老太太”只用于称呼年老的妇女，不能称呼小孩子。"}, {"text": "售货员对一位穿校服的女生说：“老太太，您拿好。”", "explanation": "这里应该用〈小姑娘〉。“老太太”只称呼年老的妇女，不能称呼穿校服的年轻女生。"}, {"text": "服务员对一位先生说：“老太太，请慢走。”", "explanation": "这里应该用〈大叔〉。“老太太”只称呼年老的妇女，不能用来称呼男士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "张的老太太，您慢点儿走。", "corrected_sentence": "张老太太，您慢点儿走。", "error_description": "助词错误：姓氏加“老太太”作称呼时不用“的”，应说“张老太太”，不能说“张的老太太”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只老太太，您慢点儿走。", "corrected_sentence": "那位老太太，您慢点儿走。", "error_description": "量词错误：指人的“老太太”要用“位”计量，“只”不用于人，应改为“那位老太太”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '519c775e-75a4-4c9a-a0e7-68ff8ffe583e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
