INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91583, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做这个工作的人可以管的事。", "primary_collocate": null, "pronunciation": "zhí quán", "ipa": "ʈʂʐ̩˧˥ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这项决定不在我的职权之内，应由经理作出。", "target_word": "职权", "complexity_tier": "T3", "furigana": "zhè xiàng juédìng bú zài wǒ de zhí quán zhī nèi, yīng yóu jīnglǐ zuòchū.", "sentence_source": "generated"}, {"text": "停车场的事在保安的职权之内。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个岗位的职权都不一样。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是校长的职权，我们不能管。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理问清了每个部门的职权。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚来公司，还不清楚自己的职权。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，大家先说明各自的职权。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题超出了小王的职权。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生和护士的职权不一样。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事在老师的职权之内，老师可以决定。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "职权范围", "label": "复合"}, {"form": "職權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "某个岗位的人可以管的事情范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfa04d34-6d12-4e16-bb64-7be55add196d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91583, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职权", "is_correct": true, "explanation": "zhí quán 指职务范围内拥有的权力，正确答案。"}, {"text": "实权", "is_correct": false, "explanation": "shí quán 与 zhí quán 声母不同（sh 与 zh），意思是实际掌握的权力。"}, {"text": "值钱", "is_correct": false, "explanation": "zhí qián 与 zhí quán 第二音节介音不同（i 与 u），意思是有价值。"}, {"text": "职员", "is_correct": false, "explanation": "zhí yuán 与 zhí quán 第二音节声母不同（y 与 q），意思是在机构里工作的人。"}], "explanations": {"职权": "zhí quán 指职务范围内拥有的权力，正确答案。", "实权": "shí quán 与 zhí quán 声母不同（sh 与 zh），意思是实际掌握的权力。", "值钱": "zhí qián 与 zhí quán 第二音节介音不同（i 与 u），意思是有价值。", "职员": "zhí yuán 与 zhí quán 第二音节声母不同（y 与 q），意思是在机构里工作的人。"}, "sentence_index": null, "correct_answer": "职权"}, "level_3": {"options": [{"text": "职权", "is_correct": true, "explanation": "职权指职务范围内拥有的权力，这里指经理能决定的范围，与“应由经理作出”相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资不是决定归属的范围，与句中“这项决定”不合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外貌特征，不能用于“在……之内”的范围说法。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是决定归属的范围，句中的关键是由经理作出的决定。"}], "explanations": {"职权": "职权指职务范围内拥有的权力，这里指经理能决定的范围，与“应由经理作出”相符。", "工资": "语义：工资不是决定归属的范围，与句中“这项决定”不合。", "身材": "体貌：身材是外貌特征，不能用于“在……之内”的范围说法。", "年龄": "语义：年龄不是决定归属的范围，句中的关键是由经理作出的决定。"}, "sentence_index": 0, "correct_answer": "职权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人有要求保密的职权。", "explanation": "这里应该用〈权利〉。要求保密是病人的权利；职权指职务范围内的权力，病人没有职务，不能这样用。"}, {"text": "每个公民都有言论的职权。", "explanation": "这里应该用〈权利〉。言论自由是公民的权利，不是职务范围内的权力，职权不能这样用。"}, {"text": "司机对乘客的安全负有职权。", "explanation": "这里应该用〈责任〉。“负有”后面接责任，职权要说“行使职权”，不说“负有职权”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职权", "is_correct": true, "explanation": "职权指各人职务范围内的权力，会前说明正是为了划清各自的权限。"}, {"text": "体重", "is_correct": false, "explanation": "语义：开会前说明各自的体重，与会议事务无关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不属于职务范围，开会前不需要说明。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：长相属于外貌，不是会前需要说明的职务范围。"}], "explanations": {"职权": "职权指各人职务范围内的权力，会前说明正是为了划清各自的权限。", "体重": "语义：开会前说明各自的体重，与会议事务无关。", "身高": "语义：身高不属于职务范围，开会前不需要说明。", "长相": "体貌：长相属于外貌，不是会前需要说明的职务范围。"}, "sentence_index": 6, "correct_answer": "职权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "纳税是每个人的职权。", "explanation": "这里应该用〈义务〉。纳税是每个人应尽的义务；职权是职务范围内可以行使的权力，不能用来说纳税。"}, {"text": "他的英语职权很高。", "explanation": "这里应该用〈水平〉。职权指权力，不用来描述语言能力；表示高低要说“水平”。"}, {"text": "他迟到的职权很充分。", "explanation": "这里应该用〈理由〉。迟到的原因是理由，职权是权力，不能用来解释迟到的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只职权属于经理，不属于我。", "corrected_sentence": "这项职权属于经理，不属于我。", "error_description": "量词错误：“职权”是抽象的权力，应与量词“项”搭配，说“这项职权”；用“只”是错误的，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修车的事他的职权之内，你找他就行。", "corrected_sentence": "修车的事在他的职权之内，你找他就行。", "error_description": "错误在漏掉了介词“在”。“在……之内”表示范围，应说“在他的职权之内”，少了“在”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
