INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "职务范围内所拥有的权力。", "primary_collocate": null, "pronunciation": "zhí quán", "ipa": "ʈʂʐ̩˧˥ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "经理用职权让大家加班。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他利用职权给朋友找了工作。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长不能滥用职权。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察有职权检查可疑的车。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新主任的职权比以前大了。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有职权决定这笔钱怎么用。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用职权帮自己的儿子。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给了她很大的职权。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定官员不能乱用职权。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他滥用职权，所以丢了工作。", "target_word": "职权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "职权范围", "label": "复合"}, {"form": "職權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "因职务而拥有、可以使用的权力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfa04d34-6d12-4e16-bb64-7be55add196d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91584, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职权", "is_correct": true, "explanation": "zhí quán 指职务范围内拥有的权力，正确答案。"}, {"text": "实权", "is_correct": false, "explanation": "shí quán 与 zhí quán 声母不同（sh 与 zh），意思是实际掌握的权力。"}, {"text": "值钱", "is_correct": false, "explanation": "zhí qián 与 zhí quán 第二音节介音不同（i 与 u），意思是有价值。"}, {"text": "职员", "is_correct": false, "explanation": "zhí yuán 与 zhí quán 第二音节声母不同（y 与 q），意思是在机构里工作的人。"}], "explanations": {"职权": "zhí quán 指职务范围内拥有的权力，正确答案。", "实权": "shí quán 与 zhí quán 声母不同（sh 与 zh），意思是实际掌握的权力。", "值钱": "zhí qián 与 zhí quán 第二音节介音不同（i 与 u），意思是有价值。", "职员": "zhí yuán 与 zhí quán 第二音节声母不同（y 与 q），意思是在机构里工作的人。"}, "sentence_index": null, "correct_answer": "职权"}, "level_3": {"options": [{"text": "职权", "is_correct": true, "explanation": "职权指职务范围内拥有的权力，这里指经理可以用来指挥员工的权力。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能用来让别人加班，与句意不合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是外貌特征，不能作为让人加班的手段。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能用来让别人加班，与“经理用……让大家加班”的句意不合。"}], "explanations": {"职权": "职权指职务范围内拥有的权力，这里指经理可以用来指挥员工的权力。", "体重": "语义：体重不能用来让别人加班，与句意不合。", "身材": "体貌：身材是外貌特征，不能作为让人加班的手段。", "年龄": "语义：年龄不能用来让别人加班，与“经理用……让大家加班”的句意不合。"}, "sentence_index": 0, "correct_answer": "职权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乘客有要求退票的职权。", "explanation": "这里应该用〈权利〉。要求退票是乘客的权利；职权指职务范围内的权力，乘客没有职务，不能这样用。"}, {"text": "孩子有受教育的职权。", "explanation": "这里应该用〈权利〉。受教育是孩子的权利，不是职务范围内的权力，职权不能这样用。"}, {"text": "他对这件事负有职权。", "explanation": "这里应该用〈责任〉。“负有”后面接责任，职权要说“行使职权”，不说“负有职权”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职权", "is_correct": true, "explanation": "职权指职务范围内的权力，这里指利用权力帮助别人，与句意相符。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不能用来帮助别人，与句意不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用来帮助别人，与“用……帮自己的儿子”的句意不合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来帮助别人，与句中的意思不合。"}], "explanations": {"职权": "职权指职务范围内的权力，这里指利用权力帮助别人，与句意相符。", "雨水": "语义：雨水不能用来帮助别人，与句意不合。", "天气": "语义：天气不能用来帮助别人，与“用……帮自己的儿子”的句意不合。", "颜色": "语义：颜色不能用来帮助别人，与句中的意思不合。"}, "sentence_index": 6, "correct_answer": "职权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学职权很好。", "explanation": "这里应该用〈成绩〉。成绩表示学习的结果好坏；职权指权力，不用来说学科表现。"}, {"text": "他有十年的工作职权。", "explanation": "这里应该用〈经验〉。十年的工作积累是经验，职权是权力，不能这样说。"}, {"text": "这件衣服的职权很漂亮。", "explanation": "这里应该用〈颜色〉。描述衣服的好看要说颜色，职权不能用来形容衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拥有一只很大的职权，可以决定这件事。", "corrected_sentence": "他拥有一项很大的职权，可以决定这件事。", "error_description": "量词错误：“职权”是抽象的权力，应用量词“项”计量，说“一项很大的职权”；“只”多用于动物，不能用于权力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有滥用了职权。", "corrected_sentence": "他从来没有滥用过职权。", "error_description": "错误在“过”写成了“了”。“没有”否定的是经历，要与“过”搭配，应说“没有滥用过职权”；“没有……了”不能说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
