INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91585, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "博客是在网上写日记或文章，给别人看的地方。", "primary_collocate": null, "pronunciation": "bó kè", "ipa": "pwo˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我想开一个博客，写写每天的生活。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在博客里写日记，给朋友看。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每晚都在博客上写日记。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈也想学写博客。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们常来我的博客留言。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了博客，大家都能写文章给别人看。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博客里写过很多小故事。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的博客没有人看，但我还是坚持写。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有自己的博客吗？", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天下班后都要更新博客。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "博客文章", "label": "复合"}], "register": "中性", "sense_fingerprint": "在网上写日记或文章供别人阅读的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91585, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "博客", "is_correct": true, "explanation": "“开一个博客”指开设网上写日记的地方，“写写每天的生活”与之相符。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆不是用来写字的，“写写每天的生活”说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是用来写日记的，“写写每天的生活”说不通。"}, {"text": "商店", "is_correct": false, "explanation": "语义：商店不是用来写日记的，与“写写每天的生活”不相符。"}], "explanations": {"博客": "“开一个博客”指开设网上写日记的地方，“写写每天的生活”与之相符。", "饭馆": "语义：饭馆不是用来写字的，“写写每天的生活”说不通。", "花园": "语义：花园不是用来写日记的，“写写每天的生活”说不通。", "商店": "语义：商店不是用来写日记的，与“写写每天的生活”不相符。"}, "sentence_index": 0, "correct_answer": "博客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都去博客取信。", "explanation": "这里应该用〈信箱〉。博客是网上写文章的地方，不能用来收信。"}, {"text": "她有一个博客，常常冷冻东西。", "explanation": "这里应该用〈冰箱〉。博客是网上写文章的地方，不能用来冷冻东西。"}, {"text": "我们在博客吃饭。", "explanation": "这里应该用〈饭馆〉。博客不是可以吃饭的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91585, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "博客", "is_correct": true, "explanation": "“在博客里写过很多小故事”指在网上写作的空间，搭配自然。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能用来写小故事。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是刷牙用的东西，不能在里面写小故事。"}, {"text": "鞋盒", "is_correct": false, "explanation": "语义：鞋盒是装鞋的盒子，不是写小故事的地方。"}], "explanations": {"博客": "“在博客里写过很多小故事”指在网上写作的空间，搭配自然。", "冰箱": "语义：冰箱不能用来写小故事。", "牙刷": "语义：牙刷是刷牙用的东西，不能在里面写小故事。", "鞋盒": "语义：鞋盒是装鞋的盒子，不是写小故事的地方。"}, "sentence_index": 6, "correct_answer": "博客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天下班后都要去博客买菜。", "explanation": "这里应该用〈超市〉。博客是网上的写作空间，不能去买菜。"}, {"text": "他有一个博客，每天一起去公园散步。", "explanation": "这里应该用〈朋友〉。博客是网上的写作空间，不能和人一起去公园散步。"}, {"text": "他去博客看病。", "explanation": "这里应该用〈医院〉。博客不是看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在网上开了一本博客，写旅行故事。", "corrected_sentence": "她在网上开了一个博客，写旅行故事。", "error_description": "量词错误：“一本博客”应为“一个博客”。开设的博客用“个”计量，“本”用于书本。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一本博客，常常记录生活。", "corrected_sentence": "她有一个博客，常常记录生活。", "error_description": "量词错误：“一本博客”应为“一个博客”。博客用“个”计量，“本”用于书本。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
