INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在网络上发布个人文章的网页。", "primary_collocate": null, "pronunciation": "bó kè", "ipa": "pwo˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他在博客上发了一篇新文章。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的博客每个星期更新一次。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的博客有很多人关注。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博客是用来写旅行故事的。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给自己的博客换了新名字。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在博客上看到一篇好文章。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的博客地址发给我。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博客的设计很简单。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的博客里有很多照片。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开了一个博客，写自己的看法。", "target_word": "博客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "博客文章", "label": "复合"}], "register": "中性", "sense_fingerprint": "网络上发布个人文章的网页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "博客", "is_correct": true, "explanation": "博客是网上发文章的网页，“在博客上发文章”自然。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是网页，不能在上面发文章。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“在……上”不接“厨房”，不能说“在厨房上发文章”。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯不能用来发布文章。"}], "explanations": {"博客": "博客是网上发文章的网页，“在博客上发文章”自然。", "冰箱": "语义：冰箱不是网页，不能在上面发文章。", "厨房": "搭配：“在……上”不接“厨房”，不能说“在厨房上发文章”。", "水杯": "语义：水杯不能用来发布文章。"}, "sentence_index": 0, "correct_answer": "博客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在博客上吃了一顿饭。", "explanation": "这里应该用〈饭馆〉。博客是发布个人文章的网页，不能在上面吃饭。"}, {"text": "门口有一个博客。", "explanation": "这里应该用〈咖啡馆〉。博客是网上的网页，不能放在门口。"}, {"text": "他对着博客整理头发。", "explanation": "这里应该用〈镜子〉。博客是网页，不能用来整理头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "博客", "is_correct": true, "explanation": "“博客地址”指网页的地址，“把你的博客地址发给我”通顺。"}, {"text": "银行卡", "is_correct": false, "explanation": "语义：银行卡没有网页地址，这句话不成立。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：发给别人的是“手机号码”，不说“手机地址”。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是家用电器，没有可以发送的地址。"}], "explanations": {"博客": "“博客地址”指网页的地址，“把你的博客地址发给我”通顺。", "银行卡": "语义：银行卡没有网页地址，这句话不成立。", "手机": "搭配：发给别人的是“手机号码”，不说“手机地址”。", "台灯": "语义：台灯是家用电器，没有可以发送的地址。"}, "sentence_index": 6, "correct_answer": "博客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用博客拍了很多照片。", "explanation": "这里应该用〈照相机〉。博客是网页，不能用来拍照。"}, {"text": "他用博客开门。", "explanation": "这里应该用〈钥匙〉。博客不是门锁，不能用来开门。"}, {"text": "她用博客打印文件。", "explanation": "这里应该用〈打印机〉。博客是网页，不能用来打印文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他申请了一本博客，每天写东西。", "corrected_sentence": "他申请了一个博客，每天写东西。", "error_description": "量词错误：“一本博客”应为“一个博客”。博客用“个”计量，“本”用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有一本博客，常常更新。", "corrected_sentence": "我有一个博客，常常更新。", "error_description": "量词错误：“一本博客”应为“一个博客”。博客用“个”计量，“本”用于书本。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
