INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听别人念出字词或文章，并把它写在纸上。", "primary_collocate": null, "pronunciation": "tīng xiě", "ipa": "tʰiŋ˥ ɕje˨˩˦", "syllable_count": 2, "sentences": [{"text": "请你把我念的句子听写下来。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在听写一篇短文。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上听写十个新词。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以听写这段话吗？", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听写得很快，一个字也没错。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈念了一遍，我就开始听写。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听写这首歌的歌词。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听写了一篇新闻。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听写电话号码并不容易。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们听写过很多长句子。", "target_word": "听写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听写了", "label": "体标"}, {"form": "听写过", "label": "体标"}, {"form": "听写本", "label": "复合"}, {"form": "聽寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "听人念出字词或文章并写在纸上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听写", "is_correct": true, "explanation": "正确：“听写”指听别人念出字词或句子并写下来，符合句意。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：“朗读”是出声念出来，不能写下来，“朗读下来”不成立。"}, {"text": "讲解", "is_correct": false, "explanation": "语义：“讲解”是解释说明，不能用来把句子写下来。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指用歌声表达，不能把念出的句子用“唱”记在纸上。"}], "explanations": {"听写": "正确：“听写”指听别人念出字词或句子并写下来，符合句意。", "朗读": "语义：“朗读”是出声念出来，不能写下来，“朗读下来”不成立。", "讲解": "语义：“讲解”是解释说明，不能用来把句子写下来。", "唱": "语义：“唱”指用歌声表达，不能把念出的句子用“唱”记在纸上。"}, "sentence_index": 0, "correct_answer": "听写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把窗外的风景听写下来。", "explanation": "这里应该用〈描写〉。“听写”针对念出来的字词和文字，窗外的景色要用眼睛看、用语言描写，不能说“听写”。"}, {"text": "他把这个故事听写给秘书。", "explanation": "这里应该用〈口述〉。“听写”是听别人念出来再写下，讲故事给别人的一方是“口述”，不能说“听写给秘书”。"}, {"text": "他一边看书，一边把书里的句子听写到本子上。", "explanation": "这里应该用〈抄写〉。“听写”要有人把句子念出来，自己看着书写下来是“抄写”，不能说“听写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听写", "is_correct": true, "explanation": "正确：“听写”指听别人念出字词或文字内容并写下来，可以用于歌词。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，不能用于“这首歌的歌词”。"}, {"text": "扮演", "is_correct": false, "explanation": "搭配：“扮演”接角色，不接“歌词”，这一搭配不成立。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”指用油加热食物，与“歌词”无关，不成立。"}], "explanations": {"听写": "正确：“听写”指听别人念出字词或文字内容并写下来，可以用于歌词。", "烹饪": "语义：“烹饪”指做饭，不能用于“这首歌的歌词”。", "扮演": "搭配：“扮演”接角色，不接“歌词”，这一搭配不成立。", "煎": "语义：“煎”指用油加热食物，与“歌词”无关，不成立。"}, "sentence_index": 6, "correct_answer": "听写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把心里的感受听写下来。", "explanation": "这里应该用〈记录〉。“听写”针对字词、文章等文字内容，感受不能听写，要说“记录”。"}, {"text": "他在纸上听写了一幅画。", "explanation": "这里应该用〈画〉。“听写”只用于字词、句子等文字内容，画画不能说“听写”。"}, {"text": "我们用手机听写了一段视频。", "explanation": "这里应该用〈拍摄〉。“听写”针对可以念出的字词和文字，视频要说“拍摄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他听写着了三篇短文。", "corrected_sentence": "他听写了三篇短文。", "error_description": "体标错误：表示完成应说“听写了”，“听写”不宜带“着”，不能说“听写着了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把老师念的单词听写下起来。", "corrected_sentence": "请你把老师念的单词听写下来。", "error_description": "补语错误：趋向补语“下来”是固定组合，中间不能插入“起”，应为“听写下来”，不能说“听写下起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
