INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91589, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出钱请人来做某项工作。", "primary_collocate": null, "pronunciation": "pìn qǐng", "ipa": "pʰin˥˩ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们想聘请一位老师教孩子画画。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司聘请了一位经验丰富的医生。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校聘请他来给学生上课。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们聘请过一位外国朋友做翻译。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲聘请了一名工人来修缮房屋。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算聘请她来照看孩子。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店聘请了很有名的厨师。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板聘请他来管理这家商店。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用很多钱聘请了一位律师。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院正在聘请新的护士。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聘请了", "label": "完成体"}, {"form": "聘请过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "出钱请人来做某项工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91589, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聘请", "is_correct": true, "explanation": "正确：聘请指请人来担任工作，与“教孩子画画”的语境相符。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是物品，不能说买“一位老师”。"}, {"text": "请假", "is_correct": false, "explanation": "搭配：“请假”不以人作宾语，与“一位老师”搭配不当。"}, {"text": "开除", "is_correct": false, "explanation": "语义：“开除”是解除职务，与“教孩子画画”的目的正相反。"}], "explanations": {"聘请": "正确：聘请指请人来担任工作，与“教孩子画画”的语境相符。", "买": "搭配：“买”的对象是物品，不能说买“一位老师”。", "请假": "搭配：“请假”不以人作宾语，与“一位老师”搭配不当。", "开除": "语义：“开除”是解除职务，与“教孩子画画”的目的正相反。"}, "sentence_index": 0, "correct_answer": "聘请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们聘请了一位朋友参加婚礼。", "explanation": "这里应该用〈邀请〉。聘请指请人担任工作，请朋友参加婚礼要用邀请。"}, {"text": "他聘请了一本书。", "explanation": "这里应该用〈借〉。聘请只用于请人做事，借书要用借。"}, {"text": "他聘请了一个孩子去公园。", "explanation": "这里应该用〈带〉。聘请只用于请人担任工作，带孩子去公园要用带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聘请", "is_correct": true, "explanation": "正确：聘请指请人担任工作，饭店请有名的厨师即为此义。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能煮“很有名的厨师”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能吃“厨师”。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是切割食材，与“很有名的厨师”不相关。"}], "explanations": {"聘请": "正确：聘请指请人担任工作，饭店请有名的厨师即为此义。", "煮": "搭配：“煮”的对象是食物，不能煮“很有名的厨师”。", "吃": "搭配：“吃”的对象是食物，不能吃“厨师”。", "切": "语义：“切”是切割食材，与“很有名的厨师”不相关。"}, "sentence_index": 6, "correct_answer": "聘请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他聘请大家吃饭。", "explanation": "这里应该用〈请客〉。聘请用于请人担任工作，请大家吃饭要用请客。"}, {"text": "他聘请了三天假。", "explanation": "这里应该用〈请〉。聘请指请人担任工作，请假要用请，不能说聘请假。"}, {"text": "医生聘请了一位病人。", "explanation": "这里应该用〈检查〉。聘请不能用于病人，医生检查病人要用检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们想聘请了一位司机送孩子上学。", "corrected_sentence": "我们想聘请一位司机送孩子上学。", "error_description": "体标错误：“想”表示尚未发生的意愿，“聘请”后不能加“了”，应说“想聘请一位司机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在聘请了一个会计。", "corrected_sentence": "他们正在聘请一个会计。", "error_description": "体标错误：“正在”表示动作进行中，不能与“了”同用，应说“正在聘请一个会计”，不能说“正在聘请了一个会计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91590, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解聘", "is_correct": true, "explanation": "反义：解聘指解除聘用，与“聘请”的意思相反。"}, {"text": "驾驶", "is_correct": false, "explanation": "无关：驾驶指操纵车辆，与“聘请”并非反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "无关：收拾指整理物品，与“聘请”并非反义关系。"}, {"text": "游览", "is_correct": false, "explanation": "无关：游览指参观风景，与“聘请”并非反义关系。"}], "correct_answer": "解聘", "explanations": {"解聘": "反义：解聘指解除聘用，与“聘请”的意思相反。", "驾驶": "无关：驾驶指操纵车辆，与“聘请”并非反义关系。", "收拾": "无关：收拾指整理物品，与“聘请”并非反义关系。", "游览": "无关：游览指参观风景，与“聘请”并非反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
