INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91590, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "郑重地邀请人担任某项工作。", "primary_collocate": null, "pronunciation": "pìn qǐng", "ipa": "pʰin˥˩ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大学聘请他担任校长。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司聘请她为经理。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校聘请这位老人当名誉校长。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院聘请他做客座教授。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队聘请了一位新教练。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里聘请他担任文化顾问。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会聘请过她担任会长。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聘请张先生担任法律顾问。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校已经聘请她当音乐老师了。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆聘请他负责管理工作。", "target_word": "聘请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聘请了", "label": "完成体"}, {"form": "聘请过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "郑重邀请人担任某项职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聘请", "is_correct": true, "explanation": "正确：聘请指郑重请人担任职务，与“担任校长”相符。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：“解雇”是辞退，与“担任校长”的任职意思相反。"}, {"text": "请假", "is_correct": false, "explanation": "搭配：“请假”不以人作宾语，与“他担任校长”搭配不当。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是唱歌，与任命职务毫无关联。"}], "explanations": {"聘请": "正确：聘请指郑重请人担任职务，与“担任校长”相符。", "解雇": "语义：“解雇”是辞退，与“担任校长”的任职意思相反。", "请假": "搭配：“请假”不以人作宾语，与“他担任校长”搭配不当。", "唱": "语义：“唱”是唱歌，与任命职务毫无关联。"}, "sentence_index": 0, "correct_answer": "聘请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他聘请了一个星期的假。", "explanation": "这里应该用〈请〉。聘请指郑重请人担任职务，请假要用请，不能说聘请假。"}, {"text": "学院聘请了一台电脑。", "explanation": "这里应该用〈买〉。聘请只用于请人担任职务，买电脑要用买。"}, {"text": "他聘请朋友吃了一顿饭。", "explanation": "这里应该用〈请客〉。聘请指请人担任职务，请朋友吃饭要用请客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聘请", "is_correct": true, "explanation": "正确：聘请指郑重请人担任职务，与“担任会长”相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是出售，与“担任会长”的任职意思不相关。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是动物或婴儿，不能喂“她”去担任职务。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是流泪，与任命职务毫无关联。"}], "explanations": {"聘请": "正确：聘请指郑重请人担任职务，与“担任会长”相符。", "卖": "语义：“卖”是出售，与“担任会长”的任职意思不相关。", "喂": "搭配：“喂”的对象是动物或婴儿，不能喂“她”去担任职务。", "哭": "语义：“哭”是流泪，与任命职务毫无关联。"}, "sentence_index": 6, "correct_answer": "聘请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生聘请了一位病人。", "explanation": "这里应该用〈检查〉。聘请指请人担任工作，检查病人要用检查，不能说聘请病人。"}, {"text": "他们聘请了一场球。", "explanation": "这里应该用〈打〉。聘请不能用于比赛，打一场球要用打。"}, {"text": "她聘请了一支笔。", "explanation": "这里应该用〈借〉。聘请用于请人担任工作，借一支笔要用借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校聘请她是名誉校长。", "corrected_sentence": "学校聘请她担任名誉校长。", "error_description": "结构错误：聘请他人担任职务时，职务前不能用“是”，应用“担任”“为”或“当”，应说“聘请她担任名誉校长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司正在聘请了他担任顾问。", "corrected_sentence": "这家公司正在聘请他担任顾问。", "error_description": "体标错误：“正在”表示动作进行中，不能与“了”同用，应说“正在聘请他担任顾问”，不能说“正在聘请了他担任顾问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
