INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上。", "primary_collocate": null, "pronunciation": "dì shang", "ipa": "ti˥˩ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "苹果从树上掉到了地上。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上太滑，小心点儿。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在地上系鞋带。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上铺着一块红地毯。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的地上都是水。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我把地上擦干净。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在地上找吃的。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的玩具请收好。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不小心摔倒在地上。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见地上有一只小虫。", "target_word": "地上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "地面上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05e66eed-24af-4555-9219-89fc197dcac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天上", "is_correct": false, "explanation": "语义：苹果是从树上掉下来的，落点不能是天上，“掉到了天上”说不通。"}, {"text": "地上", "is_correct": true, "explanation": "正确：苹果落到地面，可以说“掉到了地上”。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“掉到”需要一个能承接实物的落点，空气不能承接苹果。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：苹果掉不到云朵上，这句话不成立。"}], "explanations": {"天上": "语义：苹果是从树上掉下来的，落点不能是天上，“掉到了天上”说不通。", "地上": "正确：苹果落到地面，可以说“掉到了地上”。", "空气": "配价：“掉到”需要一个能承接实物的落点，空气不能承接苹果。", "云朵": "语义：苹果掉不到云朵上，这句话不成立。"}, "sentence_index": 0, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子把积木埋在地上，过了几天就找不到了。", "explanation": "这里应该用“地下”。埋进土里要说地下，“地上”指地面以上，不能说埋在地上。"}, {"text": "我把书挂在了地上。", "explanation": "语义：这里误把“地上”当成〈高处〉来用。挂书要挂在高处，应说“挂在墙上”，“地上”只指地面。"}, {"text": "地上结着很多红苹果。", "explanation": "这里应该用〈树上〉。苹果长在树枝上，“地上”指地面，不能说苹果结在地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：小狗不能在天空里找吃的，这句话不成立。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，小狗不能在星星里找吃的。"}, {"text": "地上", "is_correct": true, "explanation": "正确：小狗可以在地上找吃的。"}, {"text": "风", "is_correct": false, "explanation": "配价：“在……找吃的”需要一个具体的场所，风不能提供吃的东西。"}], "explanations": {"天空": "语义：小狗不能在天空里找吃的，这句话不成立。", "星星": "语义：星星在天上，小狗不能在星星里找吃的。", "地上": "正确：小狗可以在地上找吃的。", "风": "配价：“在……找吃的”需要一个具体的场所，风不能提供吃的东西。"}, "sentence_index": 6, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看见地上的天空有一只小虫。", "explanation": "“地上”指地面，“天空”在高处，“地上的天空”自相矛盾，这里应说“天上”。"}, {"text": "我看见地上的墙上有一只小虫。", "explanation": "语义：这里误把“地上”当成〈高处〉来用。墙面在高处，不在地面，应去掉“地上”，直接说“墙上”。"}, {"text": "我看见屋顶的地上有一只小虫。", "explanation": "语义：这里误把“地上”当成〈上方〉的意思来用。“地上”只指地面，屋顶在屋子上方，不能用“地上”来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只小狗躺了地上。", "corrected_sentence": "一只小狗躺在地上。", "error_description": "错误：“躺”后要用“在”引出处所，应说“躺在地上”，“躺了地上”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "苹果掉了地上。", "corrected_sentence": "苹果掉在地上。", "error_description": "错误：“掉”后要用“在”引出处所，应说“掉在地上”，“掉了地上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
