INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91593, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体前面，脖子下面，肚子上面的地方。", "primary_collocate": null, "pronunciation": "xiōng", "ipa": "ɕjʊŋ˥", "syllable_count": 1, "sentences": [{"text": "我的胸有点疼，想去看医生。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挺起胸，大步走了进去。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子靠在妈妈的胸上睡着了。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手拍了拍自己的胸。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把手放在胸上，深深地吸了口气。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的胸很宽，肩膀也很大。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天风很大，冷风直往胸里钻。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低着头，下巴碰到了胸。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳时，水到我的胸那么高。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球打在他的胸上，他疼得叫了一声。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身体前面脖子下面、肚子上面的部位，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胸", "is_correct": true, "explanation": "胸（xiōng，第一声）指身体前面颈部以下的部位。"}, {"text": "熊", "is_correct": false, "explanation": "熊（xióng，第二声）与胸（xiōng，第一声）声调不同，意思是熊。"}, {"text": "香", "is_correct": false, "explanation": "香（xiāng）与胸（xiōng）的韵母元音不同，a与o对立，意思是香气。"}, {"text": "星", "is_correct": false, "explanation": "星（xīng）与胸（xiōng）的韵母元音不同，i与o对立，意思是星星。"}], "explanations": {"胸": "胸（xiōng，第一声）指身体前面颈部以下的部位。", "熊": "熊（xióng，第二声）与胸（xiōng，第一声）声调不同，意思是熊。", "香": "香（xiāng）与胸（xiōng）的韵母元音不同，a与o对立，意思是香气。", "星": "星（xīng）与胸（xiōng）的韵母元音不同，i与o对立，意思是星星。"}, "sentence_index": null, "correct_answer": "胸"}, "level_3": {"options": [{"text": "胸", "is_correct": true, "explanation": "胸：身体部位，可以感到疼痛，符合“我的……有点疼”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”没有身体，不会感到疼。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“疼”一般用于身体部位，不说“心情有点疼”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是无生命的家具，不会感到疼。"}], "explanations": {"胸": "胸：身体部位，可以感到疼痛，符合“我的……有点疼”。", "椅子": "语义：“椅子”没有身体，不会感到疼。", "心情": "搭配：“疼”一般用于身体部位，不说“心情有点疼”。", "桌子": "语义：“桌子”是无生命的家具，不会感到疼。"}, "sentence_index": 0, "correct_answer": "胸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用胸看书。", "explanation": "这里应该用〈眼睛〉。“看”要用眼睛，胸不能用来看书。"}, {"text": "她用胸闻花香。", "explanation": "这里应该用〈鼻子〉。“闻”要用鼻子，胸没有嗅觉。"}, {"text": "他张开胸说话。", "explanation": "这里应该用〈嘴巴〉。“说话”要靠嘴巴，胸不能用来说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91593, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "胸", "is_correct": true, "explanation": "胸（xiōng，第一声）指身体前面颈部以下的部位。"}, {"text": "雄", "is_correct": false, "explanation": "雄（xióng，第二声）与胸（xiōng，第一声）声调不同，意思是雄性。"}, {"text": "相", "is_correct": false, "explanation": "相（xiāng）与胸（xiōng）的韵母元音不同，a与o对立，意思是互相。"}, {"text": "兴", "is_correct": false, "explanation": "兴（xīng）与胸（xiōng）的韵母元音不同，i与o对立，意思是兴起。"}], "explanations": {"胸": "胸（xiōng，第一声）指身体前面颈部以下的部位。", "雄": "雄（xióng，第二声）与胸（xiōng，第一声）声调不同，意思是雄性。", "相": "相（xiāng）与胸（xiōng）的韵母元音不同，a与o对立，意思是互相。", "兴": "兴（xīng）与胸（xiōng）的韵母元音不同，i与o对立，意思是兴起。"}, "sentence_index": null, "correct_answer": "胸"}, "level_3": {"options": [{"text": "胸", "is_correct": true, "explanation": "胸：身体部位，冷风可以钻入，符合“往……里钻”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，没有可供冷风钻入的内部空间。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能让冷风钻入其中，语义不通。"}, {"text": "话", "is_correct": false, "explanation": "搭配：“往……里钻”要接能容纳风的空间，“话”不能与“钻”搭配。"}], "explanations": {"胸": "胸：身体部位，冷风可以钻入，符合“往……里钻”。", "桌子": "语义：“桌子”是家具，没有可供冷风钻入的内部空间。", "手机": "语义：手机不能让冷风钻入其中，语义不通。", "话": "搭配：“往……里钻”要接能容纳风的空间，“话”不能与“钻”搭配。"}, "sentence_index": 6, "correct_answer": "胸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用胸写字。", "explanation": "这里应该用〈手〉。“写字”要用手，胸不能用来写字。"}, {"text": "她用胸听音乐。", "explanation": "这里应该用〈耳朵〉。“听”要用耳朵，胸没有听觉。"}, {"text": "他用胸尝味道。", "explanation": "这里应该用〈舌头〉。“尝”要用舌头，胸不能用来品尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的胸里贴着一块膏药。", "corrected_sentence": "他的胸上贴着一块膏药。", "error_description": "“贴”的结果处所要用“上”表示表面，应说“胸上”。“胸里”指胸腔内部，不能说“胸里贴着膏药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
