INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "躯干前面颈部以下、腹部以上的部分。", "primary_collocate": null, "pronunciation": "xiōng", "ipa": "ɕjʊŋ˥", "syllable_count": 1, "sentences": [{"text": "医生说我的胸没有问题。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步以后，他的胸一直很闷。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吸气时，胸会慢慢变大。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说胸不舒服，要马上休息。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手轻轻按了按他的胸。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动作可以让胸更有力量。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的胸上有一块红印。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站直时，要挺胸。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃得太快，我的胸也会痛。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深呼吸时，胸和肚子都会动。", "target_word": "胸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "躯干前面颈部以下、腹部以上的部分，常用于身体不适或锻炼的场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
