INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "胸", "is_correct": true, "explanation": "胸（xiōng，第一声）指躯干前面颈部以下、腹部以上的部分。"}, {"text": "雄", "is_correct": false, "explanation": "雄（xióng，第二声）与胸（xiōng，第一声）声调不同，意思是雄性。"}, {"text": "相", "is_correct": false, "explanation": "相（xiāng）与胸（xiōng）的韵母元音不同，a与o对立，意思是互相。"}, {"text": "星", "is_correct": false, "explanation": "星（xīng）与胸（xiōng）的韵母元音不同，i与o对立，意思是星星。"}], "explanations": {"胸": "胸（xiōng，第一声）指躯干前面颈部以下、腹部以上的部分。", "雄": "雄（xióng，第二声）与胸（xiōng，第一声）声调不同，意思是雄性。", "相": "相（xiāng）与胸（xiōng）的韵母元音不同，a与o对立，意思是互相。", "星": "星（xīng）与胸（xiōng）的韵母元音不同，i与o对立，意思是星星。"}, "sentence_index": null, "correct_answer": "胸"}, "level_3": {"options": [{"text": "胸", "is_correct": true, "explanation": "胸：身体部位，可以在上面有红印，符合“他的……上有一块红印”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以留下红印的表面，语义不通。"}, {"text": "消息", "is_correct": false, "explanation": "搭配：“消息”是抽象信息，不是能留下红印的表面，语义不通。"}, {"text": "道理", "is_correct": false, "explanation": "搭配：“道理”是抽象概念，不能在上面留下红印。"}], "explanations": {"胸": "胸：身体部位，可以在上面有红印，符合“他的……上有一块红印”。", "声音": "语义：“声音”不是可以留下红印的表面，语义不通。", "消息": "搭配：“消息”是抽象信息，不是能留下红印的表面，语义不通。", "道理": "搭配：“道理”是抽象概念，不能在上面留下红印。"}, "sentence_index": 6, "correct_answer": "胸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用胸咬苹果。", "explanation": "这里应该用〈牙齿〉。“咬”要用牙齿，胸不能用来咬东西。"}, {"text": "她用胸舔冰淇淋。", "explanation": "这里应该用〈舌头〉。“舔”要用舌头，胸不能用来舔东西。"}, {"text": "他皱起胸，好像不高兴。", "explanation": "这里应该用〈眉头〉。“皱”用于眉头，胸不能被皱起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他挺胸着，慢慢走进了教室。", "corrected_sentence": "他挺着胸，慢慢走进了教室。", "error_description": "持续态助词“着”应紧跟动词“挺”，说“挺着胸”。错句把“着”放到宾语“胸”后面，不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人胸的很宽，身体很好。", "corrected_sentence": "这位老人的胸很宽，身体很好。", "error_description": "结构助词“的”应放在修饰语“老人”和中心语“胸”之间，说“老人的胸”。错句把“的”放到“胸”后面，不合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
