INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物进化理论中，适应环境的个体存活并繁衍、不适应者被淘汰的过程。", "primary_collocate": null, "pronunciation": "zì rán xuǎn zé", "ipa": "tsɻ̩˥˩ ɻan˧˥ ɕɥɛn˨˩˦ tsɤ˧˥", "syllable_count": 4, "sentences": [{"text": "达尔文在《物种起源》中提出了自然选择的观点。", "target_word": "自然选择", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自然选择让适应环境的生物活下来。", "target_word": "自然选择", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长颈鹿的长脖子是自然选择的结果。", "target_word": "自然选择", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在自然选择中，弱小的动物容易死去。", "target_word": "自然选择", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物课上，老师讲了自然选择。", "target_word": "自然选择", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "细菌产生抗药性，也和自然选择有关。", "target_word": "自然选择", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然选择需要很长很长的时间。", "target_word": "自然选择", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "通过自然选择，适应环境的个体留下了更多后代。", "target_word": "自然选择", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境变冷后，自然选择会留下毛更厚的动物。", "target_word": "自然选择", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达尔文认为，自然选择是进化的重要原因。", "target_word": "自然选择", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然選擇", "label": "繁体"}, {"form": "自然选择学说", "label": "复合"}], "register": "书面", "sense_fingerprint": "自然选择：进化论中适者生存、不适者被淘汰的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然选择", "is_correct": true, "explanation": "正确：这里指进化论中适者生存的过程，是达尔文提出的观点，与句意相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不是可以被提出的观点。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不是可以被提出的观点。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“观点”前应是理论或现象的名称，“花园”不能与之搭配。"}], "explanations": {"自然选择": "正确：这里指进化论中适者生存的过程，是达尔文提出的观点，与句意相符。", "电脑": "语义：电脑是机器，不是可以被提出的观点。", "书桌": "语义：书桌是家具，不是可以被提出的观点。", "花园": "搭配：“观点”前应是理论或现象的名称，“花园”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "自然选择"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市里自然选择了一双最便宜的鞋。", "explanation": "这里应该用〈挑选〉。自然选择是生物在环境中被淘汰的过程，人在超市挑东西要说挑选。"}, {"text": "我们班经过自然选择，产生了新的班长。", "explanation": "这里应该用〈选举〉。自然选择指生物在环境中被淘汰的过程，全班投票选出班长要说选举。"}, {"text": "他经过自然选择，拿到了全班第一名。", "explanation": "这里应该用〈比赛〉。自然选择指生物在环境中被淘汰的过程，人在竞赛中争取名次要说比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然选择", "is_correct": true, "explanation": "正确：这里指需要很长时间才能完成的生物演化过程，与句意相符。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯不是需要时间才能完成的过程。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌没有需要长时间才能完成的过程。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“需要…时间”常接过程类主语，窗户不能作为这类主语。"}], "explanations": {"自然选择": "正确：这里指需要很长时间才能完成的生物演化过程，与句意相符。", "茶杯": "语义：茶杯不是需要时间才能完成的过程。", "书桌": "语义：书桌没有需要长时间才能完成的过程。", "窗户": "搭配：“需要…时间”常接过程类主语，窗户不能作为这类主语。"}, "sentence_index": 6, "correct_answer": "自然选择"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们经过自然选择，选出了全班最喜欢的电影。", "explanation": "这里应该用〈投票〉。自然选择指生物在环境中被淘汰的过程，人们一起表决选电影要说投票。"}, {"text": "我们经过自然选择，决定了今天的值日生。", "explanation": "这里应该用〈抽签〉。自然选择指生物在环境中被淘汰的过程，随机抽人决定值日生要说抽签。"}, {"text": "学校经过自然选择，挑出了优秀的学生。", "explanation": "这里应该用〈选拔〉。选拔是人为挑出合适的人，自然选择是生物在环境中的淘汰过程，不用于学校的挑选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只自然选择的过程很漫长。", "corrected_sentence": "这种自然选择的过程很漫长。", "error_description": "量词错误：“自然选择”是抽象的过程，应用量词“种”。“只”多用于动物等具体事物，所以“这只自然选择”错误，应改为“这种自然选择”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自然选择进行了很慢。", "corrected_sentence": "自然选择进行得很慢。", "error_description": "补语错误：“进行”后接程度补语应用“得”，不能用“了”，应为“进行得很慢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬天", "is_correct": true, "explanation": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。"}, {"text": "书", "is_correct": false, "explanation": "“书”与“夏天”没有反义关系，二者语义无关。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”与“夏天”没有反义关系，二者语义无关。"}, {"text": "电脑", "is_correct": false, "explanation": "“电脑”与“夏天”没有反义关系，二者语义无关。"}], "correct_answer": "冬天", "explanations": {"冬天": "“夏天”与“冬天”是一对反义词，分别指一年中相对的两个季节。", "书": "“书”与“夏天”没有反义关系，二者语义无关。", "河流": "“河流”与“夏天”没有反义关系，二者语义无关。", "电脑": "“电脑”与“夏天”没有反义关系，二者语义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
