INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "夏天是一年里最热的时候，我们爱吃冰淇淋，爱游泳。", "primary_collocate": null, "pronunciation": "xià tiān", "ipa": "ɕi̯a˥˩ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "夏天很热，我爱吃冰淇淋。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的时候，我们常去游泳。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天我想去海边玩。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天黑得晚，晚上八点还很亮。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热了，我一直开着空调。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈夏天喜欢穿白色的裙子。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天到了，街上卖西瓜的人多了。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天我们去过北京。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我每天喝很多水。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的晚上，大家都坐在外面聊天。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个夏天", "label": "量词搭配"}, {"form": "整个夏天", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "一年里最热的时候，人们吃冰淇淋、游泳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天”指一年中最热的季节，与“很热”相符，句子通顺。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与“很热”相反，“冬天很热，我爱吃冰淇淋”说不通。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：“冰块”是寒冷的固体，不能用“很热”来描述，句子说不通。"}, {"text": "寒冬", "is_correct": false, "explanation": "语义：“寒冬”指最冷的冬季，与“很热”矛盾。"}], "explanations": {"夏天": "“夏天”指一年中最热的季节，与“很热”相符，句子通顺。", "冬天": "语义：“冬天”与“很热”相反，“冬天很热，我爱吃冰淇淋”说不通。", "冰块": "语义：“冰块”是寒冷的固体，不能用“很热”来描述，句子说不通。", "寒冬": "语义：“寒冬”指最冷的冬季，与“很热”矛盾。"}, "sentence_index": 0, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在海边度过了一只夏天。", "explanation": "这里应该用〈个〉。“夏天”指一段时间，量词用“个”；“只”多用于动物或成对的物品。"}, {"text": "我们去夏天学三门课。", "explanation": "这里应该用〈学校〉。“去”后应接处所，“夏天”是时间，不能作处所。"}, {"text": "去年我们一家人参加了夏天。", "explanation": "这里应该用〈夏令营〉。“参加”的对象是活动，“夏天”是时段，不能作为活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天到了”说明季节转换，与“街上卖西瓜的人多了”相符。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：“寒假”是冬季的假期，与卖西瓜的夏季景象不符。"}, {"text": "元旦", "is_correct": false, "explanation": "搭配：“元旦”是节日名称，不能与“街上卖西瓜的人多了”这样的季节景象搭配。"}, {"text": "春节", "is_correct": false, "explanation": "搭配：“春节”是节日名称，春节前后不会出现街上卖西瓜的景象，句子说不通。"}], "explanations": {"夏天": "“夏天到了”说明季节转换，与“街上卖西瓜的人多了”相符。", "寒假": "语义：“寒假”是冬季的假期，与卖西瓜的夏季景象不符。", "元旦": "搭配：“元旦”是节日名称，不能与“街上卖西瓜的人多了”这样的季节景象搭配。", "春节": "搭配：“春节”是节日名称，春节前后不会出现街上卖西瓜的景象，句子说不通。"}, "sentence_index": 6, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我报名了夏天，每天上午上课。", "explanation": "这里应该用〈夏令营〉。“报名”的对象是活动，“夏天”是时段，不能作报名的对象。"}, {"text": "我们要把钟表拨到夏天。", "explanation": "这里应该用〈夏令时〉。拨动钟表调整的是“夏令时”这一时制，“夏天”是季节，不能作为时制名称。"}, {"text": "老师让我们回家做夏天。", "explanation": "这里应该用〈作业〉。“做”的对象是作业、事情等，“夏天”是时段，不能作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只夏天我过得很开心。", "corrected_sentence": "这个夏天我过得很开心。", "error_description": "“夏天”作为一段时间，量词应用“个”，不能用“只”（“只”多用于动物或成对的物品）。应把“这只夏天”改为“这个夏天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们今年夏天的去海边玩。", "corrected_sentence": "我们今年夏天去海边玩。", "error_description": "助词错误：“夏天”作时间状语时后面不加“的”，应说“今年夏天去海边玩”，多出的“的”使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
