INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "四季之一，一年中最热的季节。", "primary_collocate": null, "pronunciation": "xià tiān", "ipa": "ɕi̯a˥˩ tʰi̯ɛn˥", "syllable_count": 2, "sentences": [{"text": "夏天是一年中最热的季节。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六月到八月是北方的夏天。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天过去以后，秋天就来了。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天又长又热。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天雨水多，常常下大雨。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天、夏天、秋天、冬天是四个季节。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方的夏天比北方更热。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到夏天，河里的水就多起来。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天白天长，夜里短。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢夏天的雷雨。", "target_word": "夏天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个夏天", "label": "量词搭配"}, {"form": "整个夏天", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "四季中排在春天之后、秋天之前的最热季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天”指四季之一，是一年中最热的季节，与句中的描述相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”是一年中最冷的季节，不是最热的季节，句子与事实相反。"}, {"text": "暑假", "is_correct": false, "explanation": "搭配：“暑假”是假期，不是季节，不能与“季节”构成同指关系。"}, {"text": "秋天", "is_correct": false, "explanation": "语义：“秋天”在夏天之后，并不是一年中最热的季节。"}], "explanations": {"夏天": "“夏天”指四季之一，是一年中最热的季节，与句中的描述相符。", "冬天": "语义：“冬天”是一年中最冷的季节，不是最热的季节，句子与事实相反。", "暑假": "搭配：“暑假”是假期，不是季节，不能与“季节”构成同指关系。", "秋天": "语义：“秋天”在夏天之后，并不是一年中最热的季节。"}, "sentence_index": 0, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还没写完夏天。", "explanation": "这里应该用〈作业〉。“写完”的对象是作业、文章等，“夏天”是时段，不能作宾语。"}, {"text": "这里的一只夏天又长又热。", "explanation": "这里应该用〈个〉。“夏天”指一段时间，量词用“个”；“只”多用于动物或成对的物品。"}, {"text": "我们要把手表调到夏天。", "explanation": "这里应该用〈夏令时〉。手表调整的是“夏令时”这一时制，“夏天”是季节，不能作为时制名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夏天", "is_correct": true, "explanation": "“夏天”指夏季，“南方的夏天比北方更热”符合常识，句子通顺。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“雪”是寒冷天气的降水，与“比北方更热”的比较不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是制冷电器，不能用来比较南北方的气温高低。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，不是季节，“南方的铅笔比北方更热”说不通。"}], "explanations": {"夏天": "“夏天”指夏季，“南方的夏天比北方更热”符合常识，句子通顺。", "雪": "语义：“雪”是寒冷天气的降水，与“比北方更热”的比较不成立。", "冰箱": "语义：“冰箱”是制冷电器，不能用来比较南北方的气温高低。", "铅笔": "语义：“铅笔”是文具，不是季节，“南方的铅笔比北方更热”说不通。"}, "sentence_index": 6, "correct_answer": "夏天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年参加了夏天。", "explanation": "这里应该用〈夏令营〉。“参加”的对象是活动，“夏天”是季节，不能作为活动。"}, {"text": "我们每天去夏天上学。", "explanation": "这里应该用〈学校〉。“去”后应接处所，“夏天”是时间，不能作处所。"}, {"text": "她穿着一身夏天去上班。", "explanation": "这里应该用〈夏装〉。“夏装”指夏天穿的衣服，“夏天”是季节，不能作为衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只夏天很长，又很热。", "corrected_sentence": "这个夏天很长，又很热。", "error_description": "“夏天”作为季节，量词应用“个”，不能用“只”（“只”多用于动物或成对的物品）。应把“一只夏天”改为“这个夏天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年夏天的都去海边。", "corrected_sentence": "我们每年夏天都去海边。", "error_description": "“夏天”作时间状语，后面不加“的”，应说“每年夏天都去海边”；这里在“夏天”后多加了“的”，是多余的结构助词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91599, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91599, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91599, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头里面，能让我们想事情的东西。", "primary_collocate": null, "pronunciation": "nǎo zi", "ipa": "naʊ̯²¹⁴ tsɨ", "syllable_count": 2, "sentences": [{"text": "脑子在头里面，我们用它想事情。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔了一跤，脑子受了伤。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的脑子没有问题。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的脑子很重要，要保护好。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头疼得厉害，我怕他的脑子出了毛病。", "target_word": "脑子", "complexity_tier": "T3", "furigana": "tā tóu téng de lìhai, wǒ pà tā de nǎozi chūle máobìng", "sentence_source": "generated"}, {"text": "孩子的脑子长得很快。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病会伤害人的脑子。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃鱼对脑子很好。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脑子里有一个小肿块。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次体检，医生说我的脑子很健康。", "target_word": "脑子", "complexity_tier": "T3", "furigana": "zhè cì tǐjiǎn, yīshēng shuō wǒ de nǎozi hěn jiànkāng", "sentence_source": "generated"}], "morphological_forms": [{"form": "腦子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "脑子：头里面的器官，人用它想事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91599, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脑子", "is_correct": true, "explanation": "脑子（nǎo zi）：头里面能想事情的器官，正确答案。"}, {"text": "男子", "is_correct": false, "explanation": "男子（nánzǐ）的 nán 与脑子的 nǎo 韵母不同（an 与 ao），意思是男人，不是器官。"}, {"text": "脑汁", "is_correct": false, "explanation": "脑汁（nǎo zhī）与脑子第二音节的 zhī 与 zi 声母不同（zh 与 z），意思是脑髓或费心思的心力。"}, {"text": "老子", "is_correct": false, "explanation": "老子（lǎo zi）的 lǎo 与脑子的 nǎo 声母不同（l 与 n），口语中指父亲，较粗俗。"}], "explanations": {"脑子": "脑子（nǎo zi）：头里面能想事情的器官，正确答案。", "男子": "男子（nánzǐ）的 nán 与脑子的 nǎo 韵母不同（an 与 ao），意思是男人，不是器官。", "脑汁": "脑汁（nǎo zhī）与脑子第二音节的 zhī 与 zi 声母不同（zh 与 z），意思是脑髓或费心思的心力。", "老子": "老子（lǎo zi）的 lǎo 与脑子的 nǎo 声母不同（l 与 n），口语中指父亲，较粗俗。"}, "sentence_index": null, "correct_answer": "脑子"}, "level_3": {"options": [{"text": "脑子", "is_correct": true, "explanation": "脑子：头里面能想事情的器官，“在头里面”“用它想事情”都指向它。"}, {"text": "胃", "is_correct": false, "explanation": "搭配：“用胃想事情”不成立，想事情的器官只能说脑子或头脑，胃是消化器官。"}, {"text": "肚子", "is_correct": false, "explanation": "语义：肚子在腹部，不在头里面，与句首“在头里面”的说明矛盾。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：膝盖在腿上，不在头里面，也不能用来想事情。"}], "explanations": {"脑子": "脑子：头里面能想事情的器官，“在头里面”“用它想事情”都指向它。", "胃": "搭配：“用胃想事情”不成立，想事情的器官只能说脑子或头脑，胃是消化器官。", "肚子": "语义：肚子在腹部，不在头里面，与句首“在头里面”的说明矛盾。", "膝盖": "语义：膝盖在腿上，不在头里面，也不能用来想事情。"}, "sentence_index": 0, "correct_answer": "脑子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脑子长了很多头发，要去理发。", "explanation": "这里应该用〈头〉。长头发、理发说的是头的外部，脑子在头里面，不会长头发。"}, {"text": "他的脑子戴上了一顶新帽子。", "explanation": "这里应该用〈头〉。戴帽子的是头的外部，脑子在头里面，不能戴帽子。"}, {"text": "他在海边玩了一天，脑子晒伤了，很疼。", "explanation": "这里应该用〈皮肤〉。晒伤的是皮肤，脑子在头里面，晒不到，也不会晒伤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脑子", "is_correct": true, "explanation": "脑子：人身上的器官，这个病伤害的正是它。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物件，不是人的身体部位，不会被病伤害。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“伤害”不搭配“时间”，“伤害人的时间”不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是物件，不是人的身体器官，句子不通。"}], "explanations": {"脑子": "脑子：人身上的器官，这个病伤害的正是它。", "眼镜": "语义：眼镜是物件，不是人的身体部位，不会被病伤害。", "时间": "搭配：“伤害”不搭配“时间”，“伤害人的时间”不通。", "鞋子": "语义：鞋子是物件，不是人的身体器官，句子不通。"}, "sentence_index": 6, "correct_answer": "脑子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他撞得脑子发青，我赶紧去拿冰块。", "explanation": "这里应该用〈额头〉。撞得发青的是头的外部，脑子指头里面的器官，不能指额头。"}, {"text": "他的脑子骨折了，要在医院躺一个月。", "explanation": "这里应该用〈腿〉。骨折的是骨头，脑子是器官，不会骨折。"}, {"text": "他跑步时扭伤了脑子，要休息几天。", "explanation": "这里应该用〈脚踝〉。扭伤的是关节和韧带，脑子在头里面，不会扭伤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检查结果显示，他有一只健康的脑子。", "corrected_sentence": "检查结果显示，他有一个健康的脑子。", "error_description": "量词错误：“只”用于动物或成对器官中的一个，脑子是单个器官，应说“一个健康的脑子”，不能说“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张片子上能看到一只完整的脑子。", "corrected_sentence": "这张片子上能看到一个完整的脑子。", "error_description": "量词错误：脑子是单个器官，量词用“个”，不能用“只”。应说“一个完整的脑子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
