INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脑；也指记忆、思考的能力。", "primary_collocate": null, "pronunciation": "nǎo zi", "ipa": "naʊ̯²¹⁴ tsɨ", "syllable_count": 2, "sentences": [{"text": "他脑子很好，一看就记住了。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天脑子不太清楚，想不出办法。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脑子真快，马上就明白了。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习要动脑子。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脑子笨，学得慢。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我脑子一片空白，忘了答案。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脑子灵活，什么问题都难不倒她。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了很多酒，我的脑子不清楚了。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，我的脑子不如以前了。", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用脑子想一想，这样做对吗？", "target_word": "脑子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "腦子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "脑子：记忆、思考的能力，常说脑子好、脑子快、动脑子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'baee0e88-f68e-4a39-b1f8-d15a57ebea04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91600, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脑子", "is_correct": true, "explanation": "脑子（nǎo zi）：记忆、思考的能力，正确答案。"}, {"text": "男子", "is_correct": false, "explanation": "男子（nánzǐ）的 nán 与脑子的 nǎo 韵母不同（an 与 ao），意思是男人。"}, {"text": "脑汁", "is_correct": false, "explanation": "脑汁（nǎo zhī）与脑子第二音节的 zhī 与 zi 声母不同（zh 与 z），意思是脑髓，常说绞尽脑汁。"}, {"text": "老子", "is_correct": false, "explanation": "老子（lǎo zi）的 lǎo 与脑子的 nǎo 声母不同（l 与 n），口语中指父亲，较粗俗。"}], "explanations": {"脑子": "脑子（nǎo zi）：记忆、思考的能力，正确答案。", "男子": "男子（nánzǐ）的 nán 与脑子的 nǎo 韵母不同（an 与 ao），意思是男人。", "脑汁": "脑汁（nǎo zhī）与脑子第二音节的 zhī 与 zi 声母不同（zh 与 z），意思是脑髓，常说绞尽脑汁。", "老子": "老子（lǎo zi）的 lǎo 与脑子的 nǎo 声母不同（l 与 n），口语中指父亲，较粗俗。"}, "sentence_index": null, "correct_answer": "脑子"}, "level_3": {"options": [{"text": "脑子", "is_correct": true, "explanation": "脑子：记忆、思考的能力，“很好”“一看就记住了”都指向它。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不能作“他……很好”的主语，“他天空很好”不通，句子不成立。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：“很好”不能修饰“鱼”，人的“很好”只用于能力或身体，句子不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能“一看就记住了”，句子不通。"}], "explanations": {"脑子": "脑子：记忆、思考的能力，“很好”“一看就记住了”都指向它。", "天空": "语义：“天空”不能作“他……很好”的主语，“他天空很好”不通，句子不成立。", "鱼": "搭配：“很好”不能修饰“鱼”，人的“很好”只用于能力或身体，句子不通。", "手机": "语义：手机是物品，不能“一看就记住了”，句子不通。"}, "sentence_index": 0, "correct_answer": "脑子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脑子很大，帽子都戴不下。", "explanation": "这里应该用〈脑袋〉。戴不下帽子说的是头的大小，脑子指记忆、思考的能力，不能说大小。"}, {"text": "他的脑子哑了，说不出话来。", "explanation": "这里应该用〈嗓子〉。“哑”和“说不出话”说的是嗓子，脑子指记忆、思考的能力，不会哑。"}, {"text": "这个孩子的脑子很高，老师很喜欢他。", "explanation": "这里应该用〈智商〉。“高”可以形容智商、智力，但不说“脑子很高”；说脑子时多用“好”“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脑子", "is_correct": true, "explanation": "脑子：思考和反应的能力，“灵活”“难不倒她”都指向它。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“灵活”不用于形容天气，“她天气灵活”不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能说“灵活”指能力，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物件，与“她……灵活”以及后半句“难不倒她”不合。"}], "explanations": {"脑子": "脑子：思考和反应的能力，“灵活”“难不倒她”都指向它。", "天气": "搭配：“灵活”不用于形容天气，“她天气灵活”不通。", "桌子": "语义：桌子是家具，不能说“灵活”指能力，句子不通。", "书包": "语义：书包是物件，与“她……灵活”以及后半句“难不倒她”不合。"}, "sentence_index": 6, "correct_answer": "脑子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脑子很软，一按就陷下去。", "explanation": "这里应该用〈肚子〉。“软”和“一按就陷下去”说的是身体部位的质地，脑子指记忆、思考的能力，不能描述质地。"}, {"text": "他脑子很远，走了三里路才到学校。", "explanation": "这里应该用〈家〉。“远”和“走了三里路才到学校”说的是距离，脑子指记忆、思考的能力，不能说远近。"}, {"text": "他的脑子测验成绩很高，老师很惊讶。", "explanation": "这里应该用〈智力〉。“智力测验”是固定说法，不能说“脑子测验”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他脑子上一直想着那件事。", "corrected_sentence": "他脑子里一直想着那件事。", "error_description": "方位词错误：想着、记着事情时说“脑子里”，不能说“脑子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做题要多脑子。", "corrected_sentence": "做题要多动脑子。", "error_description": "动词漏用：“动脑子”是固定说法，缺少“动”就不能说“多脑子”，应说“多动脑子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '839ec040-9681-4b33-ac95-039efddaefa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
