INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花时间是用很多时间做一件事。", "primary_collocate": null, "pronunciation": "huā shí jiān", "ipa": "xua˥ ʂʐ̩˧˥ tɕiɛn˥", "syllable_count": 3, "sentences": [{"text": "做这个蛋糕很花时间。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷花时间做了一把小椅子。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花时间找那本旧书。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找工作需要花时间。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她花时间画了一幅画。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们花时间走完了这条山路。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好英语要花时间，别着急。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花时间准备考试。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸总是花时间修自行车。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗这么多衣服真花时间。", "target_word": "花时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花時間", "label": "繁体"}, {"form": "花了时间", "label": "体标（了）"}, {"form": "花过时间", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "花时间：用很多时间做一件事，事情费时、不能很快完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花时间", "is_correct": true, "explanation": "正确：做蛋糕要耗费很多时间，这里说的是费时。"}, {"text": "很需要", "is_correct": false, "explanation": "配价：“需要”后要接宾语，“做这个蛋糕很需要”句子不完整。"}, {"text": "很会", "is_correct": false, "explanation": "配价：“会”后要接动词，“做这个蛋糕很会”句子不完整。"}, {"text": "很高兴", "is_correct": false, "explanation": "语义：蛋糕制作过程不会“高兴”，句子说的是费时。"}], "explanations": {"花时间": "正确：做蛋糕要耗费很多时间，这里说的是费时。", "很需要": "配价：“需要”后要接宾语，“做这个蛋糕很需要”句子不完整。", "很会": "配价：“会”后要接动词，“做这个蛋糕很会”句子不完整。", "很高兴": "语义：蛋糕制作过程不会“高兴”，句子说的是费时。"}, "sentence_index": 0, "correct_answer": "花时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我花时间交了三百块的罚款。", "explanation": "这里应该用〈花钱〉。花时间表示耗费时间，罚款是支付金钱，应该说花钱交罚款。"}, {"text": "他很快就花时间还清了欠款。", "explanation": "这里应该用〈花钱〉，或删去〈花时间〉。“很快就”与花时间的费时义矛盾；还清欠款是偿还金钱，不能说花时间。"}, {"text": "买这台电脑花时间了五千块。", "explanation": "这里应该用〈花了〉。五千块是钱，应说“花了五千块”；花时间表示耗费时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花时间", "is_correct": true, "explanation": "正确：学好英语需要耗费时间，这里说的是要花时间。"}, {"text": "赶时间", "is_correct": false, "explanation": "语义：“赶时间”指匆忙，与“别着急”矛盾。"}, {"text": "等时间", "is_correct": false, "explanation": "搭配：“等”的对象是人或事情，不说等时间。"}, {"text": "催时间", "is_correct": false, "explanation": "搭配：“催”的对象是人或事情，不说催时间。"}], "explanations": {"花时间": "正确：学好英语需要耗费时间，这里说的是要花时间。", "赶时间": "语义：“赶时间”指匆忙，与“别着急”矛盾。", "等时间": "搭配：“等”的对象是人或事情，不说等时间。", "催时间": "搭配：“催”的对象是人或事情，不说催时间。"}, "sentence_index": 6, "correct_answer": "花时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服花时间卖了十块钱。", "explanation": "这里应该去掉〈花时间〉，直接说“这件衣服卖了十块钱”。卖得的金额不能用花时间来表示。"}, {"text": "这本书花时间二十块钱。", "explanation": "这里应该用〈花了〉。二十块是钱，应说“花了二十块钱”；花时间表示耗费时间。"}, {"text": "这顿饭我们花时间三百块。", "explanation": "这里应该用〈花了〉。三百块是钱，应说“花了三百块”；花时间表示耗费时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶花时间了织毛衣。", "corrected_sentence": "奶奶花时间织毛衣。", "error_description": "体标错误：“了”不能插在“花时间”和动词“织”之间，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈花时间了整理房间。", "corrected_sentence": "妈妈花时间整理房间。", "error_description": "“了”位置错误：“了”不能插在“花时间”与动词“整理”之间，应删去，得“妈妈花时间整理房间”；若要表示完成，可说“妈妈花了时间整理房间”，“了”紧跟“花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91603, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小一些", "is_correct": true, "explanation": "反义：“小一些”与“大一些”在同一属性上方向相反，表示比现在再小一点。"}, {"text": "宽一些", "is_correct": false, "explanation": "“宽”指横向距离大，与“大”不构成反义关系。"}, {"text": "深一些", "is_correct": false, "explanation": "“深”指从表面到底部的距离大，与“大小”不构成反义关系。"}, {"text": "轻一些", "is_correct": false, "explanation": "“轻”指重量小，与“大小”不构成反义关系。"}], "correct_answer": "小一些", "explanations": {"小一些": "反义：“小一些”与“大一些”在同一属性上方向相反，表示比现在再小一点。", "宽一些": "“宽”指横向距离大，与“大”不构成反义关系。", "深一些": "“深”指从表面到底部的距离大，与“大小”不构成反义关系。", "轻一些": "“轻”指重量小，与“大小”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91603, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小一些", "is_correct": true, "explanation": "反义：“小一些”与“大一些”在大小上方向相反，表示比现在再小一点。"}, {"text": "窄一些", "is_correct": false, "explanation": "“窄”是“宽”的反义词，与“大”不构成反义关系。"}, {"text": "浅一些", "is_correct": false, "explanation": "“浅”指从表面到底部的距离小，与“大小”不构成反义关系。"}, {"text": "薄一些", "is_correct": false, "explanation": "“薄”指厚度小，与“大小”不构成反义关系。"}], "correct_answer": "小一些", "explanations": {"小一些": "反义：“小一些”与“大一些”在大小上方向相反，表示比现在再小一点。", "窄一些": "“窄”是“宽”的反义词，与“大”不构成反义关系。", "浅一些": "“浅”指从表面到底部的距离小，与“大小”不构成反义关系。", "薄一些": "“薄”指厚度小，与“大小”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91603, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大一些是比现在再大一点点。", "primary_collocate": null, "pronunciation": "dà yì xiē", "ipa": "ta˥˩ i˥˩ ɕje˥", "syllable_count": 3, "sentences": [{"text": "后面的人听不清，请你声音大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画太小，能不能画得大一些？", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视的声音有点小，开大一些吧。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "字太小，我看不见，写大一些吧。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个洞太小，再挖得大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球再吹大一些就好了。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的衣服有点紧，想要大一些的。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火太小了，再把火开大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜还不够大，再等几天，让它大一些再摘。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房间太小了，换一个大一些的吧。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "在现有大小上再稍微加大一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大一些", "is_correct": true, "explanation": "大一些修饰“声音”，表示音量比现在再大一点，后面的人才能听清。"}, {"text": "小一些", "is_correct": false, "explanation": "语义：“小”表示音量更弱，会让后面的人更听不清，与句意相反。"}, {"text": "低一些", "is_correct": false, "explanation": "语义：“低”指音量变小，与“听不清”需要大声说的语境相反。"}, {"text": "矮一些", "is_correct": false, "explanation": "搭配：“矮”只用于高度或个子，不能修饰“声音”。"}], "explanations": {"大一些": "大一些修饰“声音”，表示音量比现在再大一点，后面的人才能听清。", "小一些": "语义：“小”表示音量更弱，会让后面的人更听不清，与句意相反。", "低一些": "语义：“低”指音量变小，与“听不清”需要大声说的语境相反。", "矮一些": "搭配：“矮”只用于高度或个子，不能修饰“声音”。"}, "sentence_index": 0, "correct_answer": "大一些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个冬天比去年大一些。", "explanation": "这里应该用〈冷一些〉。大一些说大小，冬天的冷暖要用“冷一些”，不能说“大一些”。"}, {"text": "今天的天气比昨天大一些。", "explanation": "这里应该用〈热一些〉。大一些说大小，天气的冷热要用“热一些”。"}, {"text": "这个理由比那个大一些。", "explanation": "这里应该用〈充分一些〉。大一些说大小，理由的充分程度要用“充分一些”，不能说“大一些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大一些", "is_correct": true, "explanation": "大一些修饰“的”前的名词，表示比现在的衣服再大一点。"}, {"text": "窄一些", "is_correct": false, "explanation": "语义：“窄”指宽度小，与“衣服有点紧”的需求相反，想要的应该更宽松。"}, {"text": "响一些", "is_correct": false, "explanation": "搭配：“响”描述声音，不能修饰衣服。"}, {"text": "快一些", "is_correct": false, "explanation": "搭配：“快”描述速度，不能修饰衣服。"}], "explanations": {"大一些": "大一些修饰“的”前的名词，表示比现在的衣服再大一点。", "窄一些": "语义：“窄”指宽度小，与“衣服有点紧”的需求相反，想要的应该更宽松。", "响一些": "搭配：“响”描述声音，不能修饰衣服。", "快一些": "搭配：“快”描述速度，不能修饰衣服。"}, "sentence_index": 6, "correct_answer": "大一些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段时间比那段大一些。", "explanation": "这里应该用〈长一些〉。大一些说大小，时间的长短要用“长一些”。"}, {"text": "这盆花的颜色比那盆大一些。", "explanation": "这里应该用〈深一些〉。大一些说大小，颜色的深浅要用“深一些”。"}, {"text": "他的汉语比我的大一些。", "explanation": "这里应该用〈好一些〉。大一些说大小，汉语水平要用“好一些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盒子最大一些，就能放下三本书。", "corrected_sentence": "这个盒子再大一些，就能放下三本书。", "error_description": "“最”表示最高程度，与“大一些”表示比现在稍大的比较义不能同用，应说“再大一些”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书包有点小，买个大一些地吧。", "corrected_sentence": "这个书包有点小，买个大一些的吧。", "error_description": "“大一些”作名词性修饰，后面要用“的”，不能用状语标记“地”，应说“买个大一些的吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小一些", "is_correct": true, "explanation": "反义：“小一些”表示比对方稍小，与“大一些”方向相反。"}, {"text": "深一些", "is_correct": false, "explanation": "“深”指从表面到底部的距离大，与“大小”不构成反义关系。"}, {"text": "轻一些", "is_correct": false, "explanation": "“轻”指重量小，与“大小”不构成反义关系。"}, {"text": "矮一些", "is_correct": false, "explanation": "“矮”指高度小，与“大小”不构成反义关系。"}], "correct_answer": "小一些", "explanations": {"小一些": "反义：“小一些”表示比对方稍小，与“大一些”方向相反。", "深一些": "“深”指从表面到底部的距离大，与“大小”不构成反义关系。", "轻一些": "“轻”指重量小，与“大小”不构成反义关系。", "矮一些": "“矮”指高度小，与“大小”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91604, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小一些", "is_correct": true, "explanation": "反义：“小一些”与“大一些”在大小上方向相反，表示比对方稍小。"}, {"text": "窄一些", "is_correct": false, "explanation": "“窄”是“宽”的反义词，与“大”不构成反义关系。"}, {"text": "浅一些", "is_correct": false, "explanation": "“浅”指从表面到底部的距离小，与“大小”不构成反义关系。"}, {"text": "薄一些", "is_correct": false, "explanation": "“薄”指厚度小，与“大小”不构成反义关系。"}], "correct_answer": "小一些", "explanations": {"小一些": "反义：“小一些”与“大一些”在大小上方向相反，表示比对方稍小。", "窄一些": "“窄”是“宽”的反义词，与“大”不构成反义关系。", "浅一些": "“浅”指从表面到底部的距离小，与“大小”不构成反义关系。", "薄一些": "“薄”指厚度小，与“大小”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比原来或比较对象稍微大。", "primary_collocate": null, "pronunciation": "dà yì xiē", "ipa": "ta˥˩ i˥˩ ɕje˥", "syllable_count": 3, "sentences": [{"text": "哥哥的房间比我的大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服比那件大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的苹果比去年的大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市比那个城市大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟比我小，可是他的脚比我的大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的狗比邻居家的大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子比那个大一些，可以放下三本书。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的杯子比我的大一些，给我用你的吧。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋比我的脚大一些，走路不舒服。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的月亮看起来比昨天大一些。", "target_word": "大一些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "与原来或比较对象相比稍微大一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大一些", "is_correct": true, "explanation": "大一些表示哥哥的房间比我的稍大，符合“比我的”的比较语境。"}, {"text": "快一些", "is_correct": false, "explanation": "搭配：“快”描述速度，不能修饰“房间”。"}, {"text": "响一些", "is_correct": false, "explanation": "搭配：“响”描述声音，不能修饰“房间”。"}, {"text": "轻一些", "is_correct": false, "explanation": "语义：“轻”指重量小，房间不能按轻重来比较。"}], "explanations": {"大一些": "大一些表示哥哥的房间比我的稍大，符合“比我的”的比较语境。", "快一些": "搭配：“快”描述速度，不能修饰“房间”。", "响一些": "搭配：“响”描述声音，不能修饰“房间”。", "轻一些": "语义：“轻”指重量小，房间不能按轻重来比较。"}, "sentence_index": 0, "correct_answer": "大一些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这节课的水平比那节课大一些。", "explanation": "这里应该用〈高一些〉。大一些说大小，水平的高低要用“高一些”。"}, {"text": "这只鸟飞得比那只大一些。", "explanation": "这里应该用〈快一些〉。大一些只能说大小，飞行的速度要用“快一些”。"}, {"text": "这次的作业的颜色比上次大一些。", "explanation": "这里应该用〈深一些〉。大一些说大小，颜色的深浅要用“深一些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大一些", "is_correct": true, "explanation": "大一些表示这个盒子比那个稍大，才能放下三本书。"}, {"text": "轻一些", "is_correct": false, "explanation": "语义：“轻”指重量小，与盒子能否放下三本书的容量无关，句意不通。"}, {"text": "慢一些", "is_correct": false, "explanation": "搭配：“慢”描述速度，不能修饰“盒子”。"}, {"text": "吵一些", "is_correct": false, "explanation": "搭配：“吵”描述声音，不能修饰“盒子”。"}], "explanations": {"大一些": "大一些表示这个盒子比那个稍大，才能放下三本书。", "轻一些": "语义：“轻”指重量小，与盒子能否放下三本书的容量无关，句意不通。", "慢一些": "搭配：“慢”描述速度，不能修饰“盒子”。", "吵一些": "搭配：“吵”描述声音，不能修饰“盒子”。"}, "sentence_index": 6, "correct_answer": "大一些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天比昨天大一些。", "explanation": "这里应该用〈热一些〉。大一些说大小，天气的冷热要用“热一些”。"}, {"text": "这首歌比那首歌大一些。", "explanation": "这里应该用〈好听一些〉。大一些说大小，歌好不好听要用“好听一些”。"}, {"text": "这台电脑的颜色比那台大一些。", "explanation": "这里应该用〈亮一些〉。大一些说大小，颜色的明暗要用“亮一些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的书包比弟弟的最大一些。", "corrected_sentence": "我的书包比弟弟的大一些。", "error_description": "“大一些”表示比较，不能与表示最高程度的“最”同用，应说“比弟弟的大一些”，去掉“最”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的房间比你的大一些地。", "corrected_sentence": "我的房间比你的大一些。", "error_description": "“地”是状语标记，用在动词前，“大一些”在句末作谓语，不能加“地”，应说“我的房间比你的大一些”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "表扬：真诚地赞扬人，与讽刺的言不由衷相反，是这一义项的反义词。"}, {"text": "煮", "is_correct": false, "explanation": "煮：指用水加热食物，与讽刺没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指出外游览，与讽刺没有反义关系。"}, {"text": "收拾", "is_correct": false, "explanation": "收拾：指整理物品，与讽刺没有反义关系。"}], "correct_answer": "表扬", "explanations": {"表扬": "表扬：真诚地赞扬人，与讽刺的言不由衷相反，是这一义项的反义词。", "煮": "煮：指用水加热食物，与讽刺没有反义关系。", "旅行": "旅行：指出外游览，与讽刺没有反义关系。", "收拾": "收拾：指整理物品，与讽刺没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "称赞", "is_correct": true, "explanation": "称赞：真心夸奖，与“用客气的话说坏话”的表里不一相反，是这一义项的反义词。"}, {"text": "洗", "is_correct": false, "explanation": "洗：指用水去除污垢，与讽刺没有反义关系。"}, {"text": "搬", "is_correct": false, "explanation": "搬：指移动物体，与讽刺没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指慢慢走动，与讽刺没有反义关系。"}], "correct_answer": "称赞", "explanations": {"称赞": "称赞：真心夸奖，与“用客气的话说坏话”的表里不一相反，是这一义项的反义词。", "洗": "洗：指用水去除污垢，与讽刺没有反义关系。", "搬": "搬：指移动物体，与讽刺没有反义关系。", "散步": "散步：指慢慢走动，与讽刺没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用好听的话说坏话，让人难为情。", "primary_collocate": null, "pronunciation": "fěng cì", "ipa": "fɤŋ˨˩ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他笑着说“你真聪明”，其实是在讽刺我。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我考得不好，同学却说我“真厉害”，这是讽刺我。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说“你来得真早”，是在讽刺我迟到。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别讽刺我了，我知道自己做得不好。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥夸我“跑得真快”，我听出来他在讽刺我。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理对迟到的小王说：“你来得真早啊！”这是在讽刺他。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话听起来很好听，其实是讽刺人。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说“你真爱干净啊”，是讽刺我房间太乱。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人夸你的时候，也要想想他是不是在讽刺你。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用很客气的话讽刺了我，我脸都红了。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讽刺了", "label": "完成体"}, {"form": "讽刺过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "说反话、用表面夸奖的话挖苦人，让对方难为情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：说反话、用表面夸奖挖苦人，与“笑着说你真聪明”及“其实”的转折相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说吃我。"}, {"text": "喂", "is_correct": false, "explanation": "语义：喂是给人或动物送食物，与“你真聪明”的夸奖语境不符。"}, {"text": "认识", "is_correct": false, "explanation": "配价：“认识”不能用“在”表示进行，不能说“是在认识我”。"}], "explanations": {"讽刺": "讽刺：说反话、用表面夸奖挖苦人，与“笑着说你真聪明”及“其实”的转折相符。", "吃": "搭配：“吃”的宾语是食物，不能说吃我。", "喂": "语义：喂是给人或动物送食物，与“你真聪明”的夸奖语境不符。", "认识": "配价：“认识”不能用“在”表示进行，不能说“是在认识我”。"}, "sentence_index": 0, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他满怀感激地讽刺了我的努力。", "explanation": "讽刺是用好听的话说坏话，暗含反面意思，与“满怀感激”的心情相矛盾，不能用来表达谢意。"}, {"text": "老师真诚地讽刺了我的进步。", "explanation": "这里应该用〈赞美〉。讽刺是用好听的话说坏话，“真诚地”与它的暗讽不符。"}, {"text": "老师为了鼓励我，讽刺了我的错误。", "explanation": "讽刺是说坏话，与“鼓励”的意图相反，不能用来激励别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：表面说好听的话，实际挖苦人，与“听起来很好听，其实是”的转折相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的宾语是物品，不能说搬人。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是衣物、身体等，不能说洗人。"}, {"text": "绑", "is_correct": false, "explanation": "语义：绑是捆住，与“听起来很好听”的话语无关，不能说绑人。"}], "explanations": {"讽刺": "讽刺：表面说好听的话，实际挖苦人，与“听起来很好听，其实是”的转折相符。", "搬": "搭配：“搬”的宾语是物品，不能说搬人。", "洗": "搭配：“洗”的宾语是衣物、身体等，不能说洗人。", "绑": "语义：绑是捆住，与“听起来很好听”的话语无关，不能说绑人。"}, "sentence_index": 6, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很认真地讽刺我，因为他真的觉得我画得好。", "explanation": "讽刺是表面说好话、实际说坏话；“真的觉得我画得好”是真心夸奖，不是讽刺。"}, {"text": "他真心实意地讽刺了我，说我的回答非常准确。", "explanation": "讽刺是言不由衷地说反话，“真心实意”与之相矛盾，句子表达的是真诚的夸奖。"}, {"text": "大家一起讽刺新同学，还送给他一束花。", "explanation": "讽刺是挖苦，与“送花”表示欢迎的举动相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学用夸奖的口气正在讽刺了我的懒惰。", "corrected_sentence": "同学用夸奖的口气讽刺了我的懒惰。", "error_description": "错误：“讽刺”前多出了“正在”，与表示完成的“了”不能同用。正确：去掉“正在”，写作“讽刺了我的懒惰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用客气的话讽刺了了我的穿着，我很尴尬。", "corrected_sentence": "他用客气的话讽刺了我的穿着，我很尴尬。", "error_description": "错误：“了”重复出现（“了了”）。正确：“讽刺”后只用一个“了”，写作“讽刺了我的穿着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赞美", "is_correct": true, "explanation": "赞美：真诚地称赞人，与讽刺的挖苦相反，是这一义项的反义词。"}, {"text": "观察", "is_correct": false, "explanation": "观察：指仔细看，与讽刺没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指修补器物，与讽刺没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集：指聚拢物品或资料，与讽刺没有反义关系。"}], "correct_answer": "赞美", "explanations": {"赞美": "赞美：真诚地称赞人，与讽刺的挖苦相反，是这一义项的反义词。", "观察": "观察：指仔细看，与讽刺没有反义关系。", "修理": "修理：指修补器物，与讽刺没有反义关系。", "收集": "收集：指聚拢物品或资料，与讽刺没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "称赞", "is_correct": true, "explanation": "称赞：真心夸奖，与讽刺的挖苦相反，是这一义项的反义词。"}, {"text": "修补", "is_correct": false, "explanation": "修补：指修复破损之处，与讽刺没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理：指使事物有条理，与讽刺没有反义关系。"}, {"text": "询问", "is_correct": false, "explanation": "询问：指打听、问，与讽刺没有反义关系。"}], "correct_answer": "称赞", "explanations": {"称赞": "称赞：真心夸奖，与讽刺的挖苦相反，是这一义项的反义词。", "修补": "修补：指修复破损之处，与讽刺没有反义关系。", "整理": "整理：指使事物有条理，与讽刺没有反义关系。", "询问": "询问：指打听、问，与讽刺没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用比喻、夸张等手法对人或事进行嘲笑和批评。", "primary_collocate": null, "pronunciation": "fěng cì", "ipa": "fɤŋ˨˩ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这幅漫画讽刺了乱扔垃圾的人。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家用夸张的方法讽刺社会上的坏事。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说讽刺了那个时代的官员。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的相声常常讽刺爱面子的人。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事用小动物讽刺人的缺点。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这首诗是在讽刺懒人。", "target_word": "讽刺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上的漫画常常讽刺不好的社会现象。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅的文章讽刺过很多社会问题。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影用笑话讽刺了贪钱的老板。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一幅画，讽刺那些浪费粮食的人。", "target_word": "讽刺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讽刺了", "label": "完成体"}, {"form": "讽刺过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "文学、漫画、相声等用比喻、夸张的手法嘲笑并批评坏人坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：用比喻、夸张的手法嘲笑批评乱扔垃圾的人，与漫画的意图相符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美是称赞，乱扔垃圾的人不值得称赞，与漫画的批评意图相反。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：庆祝的对象是节日、胜利等事件，不能说庆祝乱扔垃圾的人。"}, {"text": "保护", "is_correct": false, "explanation": "语义：保护是护卫、爱护，漫画不会去保护乱扔垃圾的人。"}], "explanations": {"讽刺": "讽刺：用比喻、夸张的手法嘲笑批评乱扔垃圾的人，与漫画的意图相符。", "赞美": "语义：赞美是称赞，乱扔垃圾的人不值得称赞，与漫画的批评意图相反。", "庆祝": "搭配：庆祝的对象是节日、胜利等事件，不能说庆祝乱扔垃圾的人。", "保护": "语义：保护是护卫、爱护，漫画不会去保护乱扔垃圾的人。"}, "sentence_index": 0, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗讽刺了妈妈对孩子的爱。", "explanation": "讽刺是用夸张、比喻批评坏人坏事；母爱是美好的，诗歌会赞美而不是讽刺它。"}, {"text": "这幅漫画讽刺了救人的英雄。", "explanation": "讽刺的对象是值得批评的人或事；救人的英雄应当被歌颂。"}, {"text": "作家写这篇文章是为了讽刺好心帮助别人的人。", "explanation": "讽刺用来批评坏现象，帮助别人是好事，与讽刺的对象不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讽刺", "is_correct": true, "explanation": "讽刺：用漫画批评、挖苦不好的社会现象，与“常常”及句意相符。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：歌颂是赞美颂扬，与“不好的社会现象”矛盾。"}, {"text": "赞助", "is_correct": false, "explanation": "搭配：赞助的对象是活动、事业等，不能说赞助不好的社会现象。"}, {"text": "维护", "is_correct": false, "explanation": "语义：维护是保护、坚持，漫画不会去维护不好的社会现象。"}], "explanations": {"讽刺": "讽刺：用漫画批评、挖苦不好的社会现象，与“常常”及句意相符。", "歌颂": "语义：歌颂是赞美颂扬，与“不好的社会现象”矛盾。", "赞助": "搭配：赞助的对象是活动、事业等，不能说赞助不好的社会现象。", "维护": "语义：维护是保护、坚持，漫画不会去维护不好的社会现象。"}, "sentence_index": 6, "correct_answer": "讽刺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影讽刺了努力学习的好学生。", "explanation": "讽刺是批评坏人坏事；努力学习的学生值得表扬，不是讽刺的对象。"}, {"text": "这首歌讽刺了美丽的家乡，大家听了都很感动。", "explanation": "讽刺带有嘲笑批评，不会让人因赞美家乡而感动；这里应该用〈歌颂〉。"}, {"text": "这个相声讽刺了认真工作的医生。", "explanation": "讽刺针对值得批评的现象；认真工作的医生不应被讽刺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
