INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91607, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜘蛛是会吐丝织网的节肢动物，有八条腿。", "primary_collocate": null, "pronunciation": "zhī zhū", "ipa": "ʈʂɨ˥ ʈʂu˥", "syllable_count": 2, "sentences": [{"text": "夜里，一只黑蜘蛛爬到了床边。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上找到了一只蜘蛛。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛的网又细又结实。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只蜘蛛正在等虫子飞过来。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那只蜘蛛多大啊！", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子很久没人住，角落里有很多蜘蛛。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了蜘蛛的故事。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛爬得很快。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家没有蜘蛛，也没有蚊子。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛先吐出长长的丝，然后慢慢织网。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只蜘蛛", "label": "量词搭配"}, {"form": "蜘蛛网", "label": "复合词"}, {"form": "蜘蛛丝", "label": "复合词"}], "register": "中性", "sense_fingerprint": "会吐丝织网、有八条腿的节肢动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91607, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜘蛛", "is_correct": true, "explanation": "正确。蜘蛛（zhī zhū）指会吐丝织网、有八条腿的小虫。"}, {"text": "支柱", "is_correct": false, "explanation": "声调不同：zhù（第四声）与 zhū（第一声）不同，“支柱”指支撑东西的柱子。"}, {"text": "支出", "is_correct": false, "explanation": "声母不同：chū 与 zhū 的声母不同（ch 与 zh），“支出”指花钱、付出。"}, {"text": "植株", "is_correct": false, "explanation": "声调不同：zhí（第二声）与 zhī（第一声）不同，“植株”指一株植物。"}, {"text": "支书", "is_correct": false, "explanation": "声母不同：shū 与 zhū 的声母不同（sh 与 zh），“支书”指支部书记。"}], "explanations": {"蜘蛛": "正确。蜘蛛（zhī zhū）指会吐丝织网、有八条腿的小虫。", "支柱": "声调不同：zhù（第四声）与 zhū（第一声）不同，“支柱”指支撑东西的柱子。", "支出": "声母不同：chū 与 zhū 的声母不同（ch 与 zh），“支出”指花钱、付出。", "植株": "声调不同：zhí（第二声）与 zhī（第一声）不同，“植株”指一株植物。", "支书": "声母不同：shū 与 zhū 的声母不同（sh 与 zh），“支书”指支部书记。"}, "sentence_index": null, "correct_answer": "蜘蛛"}, "level_3": {"options": [{"text": "蜘蛛", "is_correct": true, "explanation": "正确。“夜里，一只黑蜘蛛爬到了床边”符合动物的动作和量词搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是静物，不会自己爬到床边。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”的量词用“扇”，不用“只”。"}, {"text": "枕头", "is_correct": false, "explanation": "语义：枕头是静物，不会爬行，“爬到了床边”说不通。"}], "explanations": {"蜘蛛": "正确。“夜里，一只黑蜘蛛爬到了床边”符合动物的动作和量词搭配。", "石头": "语义：石头是静物，不会自己爬到床边。", "窗户": "搭配：“窗户”的量词用“扇”，不用“只”。", "枕头": "语义：枕头是静物，不会爬行，“爬到了床边”说不通。"}, "sentence_index": 0, "correct_answer": "蜘蛛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜻蜓是一种蜘蛛，夏天常在水边飞。", "explanation": "这里应该用〈昆虫〉。蜻蜓是会飞的昆虫，蜘蛛是八条腿、会结网的节肢动物。"}, {"text": "床底下爬出一张蜘蛛。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等平面的东西，蜘蛛应该用“只”。"}, {"text": "树干上爬着一棵蜘蛛。", "explanation": "这里应该用〈只〉。“棵”用于树木、草等植物，蜘蛛应该用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91607, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜘蛛", "is_correct": true, "explanation": "正确。老师讲的是蜘蛛的故事，动物可以作为故事的主角。"}, {"text": "所以", "is_correct": false, "explanation": "词性：“所以”是连词，不能放在“的故事”前作定语。"}, {"text": "已经", "is_correct": false, "explanation": "词性：“已经”是副词，不能修饰“故事”，“讲了已经的故事”不通。"}, {"text": "非常", "is_correct": false, "explanation": "词性：“非常”是副词，不能修饰名词“故事”。"}], "explanations": {"蜘蛛": "正确。老师讲的是蜘蛛的故事，动物可以作为故事的主角。", "所以": "词性：“所以”是连词，不能放在“的故事”前作定语。", "已经": "词性：“已经”是副词，不能修饰“故事”，“讲了已经的故事”不通。", "非常": "词性：“非常”是副词，不能修饰名词“故事”。"}, "sentence_index": 6, "correct_answer": "蜘蛛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田埂上走过一头小蜘蛛。", "explanation": "这里应该用〈只〉。“头”用于牛、羊等大型牲畜，蜘蛛是小动物，应该用“只”。"}, {"text": "桌面上趴着一张蜘蛛。", "explanation": "这里应该用〈只〉。“张”用于桌面、纸张等平面的东西，蜘蛛应该用“只”。"}, {"text": "夏天的花园里，蜘蛛忙着采蜜。", "explanation": "这里应该用〈蜜蜂〉。采蜜的是蜜蜂，蜘蛛不采蜜，它靠吐丝织网捕虫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗帘上挂着一张小蜘蛛。", "corrected_sentence": "窗帘上挂着一只小蜘蛛。", "error_description": "量词错误：蜘蛛应该用量词“只”，写成“一只小蜘蛛”。“张”用于纸、桌子等平面的东西，不能用来数蜘蛛。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只蜘蛛跑很慢。", "corrected_sentence": "这只蜘蛛跑得很慢。", "error_description": "补语标记错误：程度补语前要用“得”，应说“跑得很慢”，不能漏掉“得”写成“跑很慢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
