INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "节肢动物，有八条腿，会吐丝结网捕食昆虫。", "primary_collocate": null, "pronunciation": "zhī zhū", "ipa": "ʈʂɨ˥ ʈʂu˥", "syllable_count": 2, "sentences": [{"text": "墙角有一只大蜘蛛。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛在窗边织了一张网。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很怕蜘蛛，一看见就叫。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛有八条腿，不是昆虫。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小蜘蛛从天花板上爬下来。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛用丝织网，抓住小虫子。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的蜘蛛每天都在捕虫。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在树叶上看到了一只绿蜘蛛。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛一般不会咬人。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把蜘蛛放进了小盒子里。", "target_word": "蜘蛛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只蜘蛛", "label": "量词搭配"}, {"form": "蜘蛛网", "label": "复合词"}, {"form": "蜘蛛丝", "label": "复合词"}], "register": "中性", "sense_fingerprint": "有八条腿、吐丝结网捕虫的节肢动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜘蛛", "is_correct": true, "explanation": "正确。蜘蛛（zhī zhū）指有八条腿、会吐丝结网的节肢动物。"}, {"text": "支柱", "is_correct": false, "explanation": "声调不同：zhù（第四声）与 zhū（第一声）不同，“支柱”指支撑东西的柱子。"}, {"text": "支出", "is_correct": false, "explanation": "声母不同：chū 与 zhū 的声母不同（ch 与 zh），“支出”指花钱、付出。"}, {"text": "植株", "is_correct": false, "explanation": "声调不同：zhí（第二声）与 zhī（第一声）不同，“植株”指一株植物。"}, {"text": "支书", "is_correct": false, "explanation": "声母不同：shū 与 zhū 的声母不同（sh 与 zh），“支书”指支部书记。"}], "explanations": {"蜘蛛": "正确。蜘蛛（zhī zhū）指有八条腿、会吐丝结网的节肢动物。", "支柱": "声调不同：zhù（第四声）与 zhū（第一声）不同，“支柱”指支撑东西的柱子。", "支出": "声母不同：chū 与 zhū 的声母不同（ch 与 zh），“支出”指花钱、付出。", "植株": "声调不同：zhí（第二声）与 zhī（第一声）不同，“植株”指一株植物。", "支书": "声母不同：shū 与 zhū 的声母不同（sh 与 zh），“支书”指支部书记。"}, "sentence_index": null, "correct_answer": "蜘蛛"}, "level_3": {"options": [{"text": "蜘蛛", "is_correct": true, "explanation": "正确。“一只大蜘蛛”指墙角的节肢动物，量词“只”搭配自然。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”的量词用“把”或“张”，不用“只”。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“沙发”的量词用“张”，不用“只”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”的量词用“张”，不用“只”。"}], "explanations": {"蜘蛛": "正确。“一只大蜘蛛”指墙角的节肢动物，量词“只”搭配自然。", "椅子": "搭配：“椅子”的量词用“把”或“张”，不用“只”。", "沙发": "搭配：“沙发”的量词用“张”，不用“只”。", "桌子": "搭配：“桌子”的量词用“张”，不用“只”。"}, "sentence_index": 0, "correct_answer": "蜘蛛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蝴蝶和蜜蜂都是蜘蛛，它们能在花丛里飞。", "explanation": "这里应该用〈昆虫〉。蝴蝶和蜜蜂是会飞的昆虫，“蜘蛛”指八条腿、会吐丝结网的节肢动物，不能概括它们。"}, {"text": "窗台上趴着一张蜘蛛。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等平面的东西，蜘蛛应该用“只”。"}, {"text": "树干上爬着一棵蜘蛛。", "explanation": "这里应该用〈只〉。“棵”用于树木、草等植物，蜘蛛应该用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜘蛛", "is_correct": true, "explanation": "正确。蜘蛛会在花园里捕食小虫，“每天都在捕虫”说的就是它。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶主要吸食花蜜，不捕食其他昆虫，“每天都在捕虫”说不通。"}, {"text": "蚯蚓", "is_correct": false, "explanation": "语义：蚯蚓以土壤中的有机物为食，不会主动捕捉小虫。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“捕虫”要求能主动行动的主语，石头不能做这个动作。"}], "explanations": {"蜘蛛": "正确。蜘蛛会在花园里捕食小虫，“每天都在捕虫”说的就是它。", "蝴蝶": "语义：蝴蝶主要吸食花蜜，不捕食其他昆虫，“每天都在捕虫”说不通。", "蚯蚓": "语义：蚯蚓以土壤中的有机物为食，不会主动捕捉小虫。", "石头": "配价：“捕虫”要求能主动行动的主语，石头不能做这个动作。"}, "sentence_index": 6, "correct_answer": "蜘蛛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的晚上，蜘蛛总在耳边嗡嗡地飞。", "explanation": "这里应该用〈蚊子〉。“嗡嗡”是蚊子等飞虫振翅的声音，蜘蛛没有翅膀，不会这样飞；它靠八条腿爬行、吐丝结网。"}, {"text": "草地上跑过一头小蜘蛛。", "explanation": "这里应该用〈只〉。“头”用于牛、羊等大型牲畜，蜘蛛是小动物，应该用“只”。"}, {"text": "墙上趴着一张蜘蛛。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等平面的东西，蜘蛛应该用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的墙上有一张小蜘蛛。", "corrected_sentence": "厨房的墙上有一只小蜘蛛。", "error_description": "量词错误：蜘蛛应该用量词“只”，写成“一只小蜘蛛”。“张”用于纸、桌子等平面的东西，不能用来数蜘蛛。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只蜘蛛爬特别快。", "corrected_sentence": "那只蜘蛛爬得特别快。", "error_description": "补语标记错误：程度补语前要用“得”，应说“爬得特别快”，不能漏掉“得”写成“爬特别快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91609, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91609, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91609, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天堂是故事里很美很好的地方，人们说好人死后会去。", "primary_collocate": null, "pronunciation": "tiān táng", "ipa": "tʰjɛn˥ tʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶说，好人死后会去天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问妈妈：天堂里有没有糖？", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人相信爷爷现在在天堂里很快乐。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的天堂有白云和金色的门。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画了一幅天堂的画，里面有很多天使。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天祈祷，希望死后能上天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的天使从天堂飞到了人间。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说妈妈在天堂里看着我们。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说天堂的路是用金子铺的。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩相信小狗也会去天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "故事或信仰中好人死后去的美好地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91609, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：故事或信仰中好人死后去的美好地方。"}, {"text": "甜糖", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，甜糖指甜甜的糖，不是天堂。"}, {"text": "甜汤", "is_correct": false, "explanation": "tián tāng 与 tiān táng 两个音节声调都不同，甜汤指加了糖的汤。"}, {"text": "添汤", "is_correct": false, "explanation": "tiān tāng 只有第二个音节声调不同（táng 与 tāng），添汤指再盛些汤。"}, {"text": "天坛", "is_correct": false, "explanation": "tiān tán 与 tiān táng 的韵尾不同（-n 与 -ng），天坛指祭天的高台，如北京天坛。"}], "explanations": {"天堂": "天堂：故事或信仰中好人死后去的美好地方。", "甜糖": "tián（第二声）与 tiān（第一声）声调不同，甜糖指甜甜的糖，不是天堂。", "甜汤": "tián tāng 与 tiān táng 两个音节声调都不同，甜汤指加了糖的汤。", "添汤": "tiān tāng 只有第二个音节声调不同（táng 与 tāng），添汤指再盛些汤。", "天坛": "tiān tán 与 tiān táng 的韵尾不同（-n 与 -ng），天坛指祭天的高台，如北京天坛。"}, "sentence_index": null, "correct_answer": "天堂"}, "level_3": {"options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：好人死后会去的地方，与句意吻合。"}, {"text": "地狱", "is_correct": false, "explanation": "语义：地狱是惩罚坏人的地方，与“好人死后”相矛盾。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，好人死后不会去医院，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“去”后面要接可以到达的具体地点，不说“去天空”，要说“飞上天空”。"}], "explanations": {"天堂": "天堂：好人死后会去的地方，与句意吻合。", "地狱": "语义：地狱是惩罚坏人的地方，与“好人死后”相矛盾。", "医院": "语义：医院是看病的地方，好人死后不会去医院，句意不通。", "天空": "搭配：“去”后面要接可以到达的具体地点，不说“去天空”，要说“飞上天空”。"}, "sentence_index": 0, "correct_answer": "天堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳慢慢落下，天堂变成了橘红色。", "explanation": "这里应该用〈天空〉。天堂指故事或信仰中死后去的美好地方，不指天空；太阳落山后天空变色，不能说天堂变色。"}, {"text": "下午三点，天堂是灰蒙蒙的，看起来快要下雨了。", "explanation": "这里应该用〈天色〉。天堂指死后去的美好地方，不指天空的颜色和样子；描写天阴要说〈天色〉。"}, {"text": "他一个人走遍了天堂，就是为了找一味药。", "explanation": "这里应该用〈天下〉（指各地、世界）。天堂指死后去的美好地方，不能说走遍天堂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：天使从那里飞到人间的地方，与句意吻合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，天使不会从那里飞到人间，与“从…飞到”的起点不合。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，与天使飞行的起点无关，句意不通。"}, {"text": "地铁站", "is_correct": false, "explanation": "搭配：“从…飞到”的起点应是天上或远方，地铁站在地下，不说“从地铁站飞到”。"}], "explanations": {"天堂": "天堂：天使从那里飞到人间的地方，与句意吻合。", "厨房": "语义：厨房是做饭的地方，天使不会从那里飞到人间，与“从…飞到”的起点不合。", "教室": "语义：教室是上课的地方，与天使飞行的起点无关，句意不通。", "地铁站": "搭配：“从…飞到”的起点应是天上或远方，地铁站在地下，不说“从地铁站飞到”。"}, "sentence_index": 6, "correct_answer": "天堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯挂在天堂上，照亮了整个房间。", "explanation": "这里应该用〈天花板〉。天堂指故事中死后去的美好地方，不指房顶；灯挂在天花板上才合理。"}, {"text": "夕阳慢慢沉入远处的天堂。", "explanation": "这里应该用〈天际〉（天与地相接的远方）。天堂指死后去的美好地方，不指远处的地平线。"}, {"text": "站在山顶，眼前是开阔的天堂。", "explanation": "这里应该用〈天地〉（广阔的空间）。天堂指死后去的美好地方，不用来形容山顶看到的广阔空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他相信妈妈现在住天堂里。", "corrected_sentence": "他相信妈妈现在住在天堂里。", "error_description": "“住”后面接表示处所的“天堂里”时，前面要加“在”，应说“住在天堂里”，不说“住天堂里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想象妈妈是天堂里很快乐。", "corrected_sentence": "我想象妈妈在天堂里很快乐。", "error_description": "“在…里”表示处所，“在”不能换成“是”，应说“在天堂里”，不说“是天堂里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91610, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "地狱", "is_correct": true, "explanation": "反义词：比喻义中，天堂指让人幸福的好地方，地狱指痛苦的地方，二者相反。"}, {"text": "厨房", "is_correct": false, "explanation": "与天堂没有反义关系，厨房是做饭的地方，与比喻义无关。"}, {"text": "海洋", "is_correct": false, "explanation": "与天堂没有反义关系，海洋指大片的水域，不构成相对的概念。"}, {"text": "图书馆", "is_correct": false, "explanation": "与天堂没有反义关系，图书馆是借书读书的地方，不是相对的概念。"}], "correct_answer": "地狱", "explanations": {"地狱": "反义词：比喻义中，天堂指让人幸福的好地方，地狱指痛苦的地方，二者相反。", "厨房": "与天堂没有反义关系，厨房是做饭的地方，与比喻义无关。", "海洋": "与天堂没有反义关系，海洋指大片的水域，不构成相对的概念。", "图书馆": "与天堂没有反义关系，图书馆是借书读书的地方，不是相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91610, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "地狱", "is_correct": true, "explanation": "反义词：比喻义中，天堂指让人幸福的地方，地狱指痛苦的地方，二者相反。"}, {"text": "森林", "is_correct": false, "explanation": "与天堂没有反义关系，森林是树木成片生长的地方，不构成相对的概念。"}, {"text": "剧场", "is_correct": false, "explanation": "与天堂没有反义关系，剧场是演出的场所，与比喻义无关。"}, {"text": "田野", "is_correct": false, "explanation": "与天堂没有反义关系，田野指平坦的开阔地，不构成相对的概念。"}], "correct_answer": "地狱", "explanations": {"地狱": "反义词：比喻义中，天堂指让人幸福的地方，地狱指痛苦的地方，二者相反。", "森林": "与天堂没有反义关系，森林是树木成片生长的地方，不构成相对的概念。", "剧场": "与天堂没有反义关系，剧场是演出的场所，与比喻义无关。", "田野": "与天堂没有反义关系，田野指平坦的开阔地，不构成相对的概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻让人幸福、最适合某类人的好地方。", "primary_collocate": null, "pronunciation": "tiān táng", "ipa": "tʰjɛn˥ tʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座岛的海边是游客的天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对爱吃甜点的人来说，这家店就是天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天泡温泉，对怕冷的人来说就是天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末在家看书，对我来说就是天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有很多玩具，是孩子们的天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片大草原是摄影爱好者的天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫觉得这个大花园是它的天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书店是爱读书的人的天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，有网络的地方就是天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有一百家小吃店，真是吃货的天堂。", "target_word": "天堂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人间天堂", "label": "复合"}], "register": "中性", "sense_fingerprint": "比喻让人幸福、最适合某类人的好地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c68a36c9-e59c-427d-8e93-883fc38f78dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：让人幸福、最适合某类人的好地方。"}, {"text": "甜糖", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，甜糖指甜甜的糖。"}, {"text": "甜汤", "is_correct": false, "explanation": "tián tāng 与 tiān táng 两个音节声调都不同，甜汤指加了糖的汤。"}, {"text": "添汤", "is_correct": false, "explanation": "tiān tāng 只有第二个音节声调不同（táng 与 tāng），添汤指再盛些汤。"}, {"text": "天坛", "is_correct": false, "explanation": "tiān tán 与 tiān táng 的韵尾不同（-n 与 -ng），天坛指祭天的高台。"}], "explanations": {"天堂": "天堂：让人幸福、最适合某类人的好地方。", "甜糖": "tián（第二声）与 tiān（第一声）声调不同，甜糖指甜甜的糖。", "甜汤": "tián tāng 与 tiān táng 两个音节声调都不同，甜汤指加了糖的汤。", "添汤": "tiān tāng 只有第二个音节声调不同（táng 与 tāng），添汤指再盛些汤。", "天坛": "tiān tán 与 tiān táng 的韵尾不同（-n 与 -ng），天坛指祭天的高台。"}, "sentence_index": null, "correct_answer": "天堂"}, "level_3": {"options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：让人幸福、最适合某类人的好地方，与句意吻合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是上课用的书，不是地方，海边不能是“游客的课本”。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱限制人的自由，与“游客的好去处”完全相反。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“游客的”后面要接游客去玩或享受的地方，不说“游客的工厂”。"}], "explanations": {"天堂": "天堂：让人幸福、最适合某类人的好地方，与句意吻合。", "课本": "语义：课本是上课用的书，不是地方，海边不能是“游客的课本”。", "监狱": "语义：监狱限制人的自由，与“游客的好去处”完全相反。", "工厂": "搭配：“游客的”后面要接游客去玩或享受的地方，不说“游客的工厂”。"}, "sentence_index": 0, "correct_answer": "天堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳落山后，天堂变成了橘红色。", "explanation": "这里应该用〈天空〉。天堂在这里比喻让人幸福的好地方，不指天空；天空才会变色。"}, {"text": "下午三点，天堂是灰蒙蒙的，看起来快要下雨了。", "explanation": "这里应该用〈天色〉。天堂不指天空的颜色和样子；描写天阴要说〈天色〉。"}, {"text": "这位老人走遍了天堂，见过很多山水。", "explanation": "这里应该用〈天下〉（指各地、世界）。天堂比喻让人幸福的好地方，不能说走遍天堂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：让人幸福的好地方，与“小猫喜欢这个花园”的句意吻合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，小猫不会觉得花园是医院，句意不通。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是工作的地方，与小猫喜欢的花园相矛盾。"}, {"text": "地铁站", "is_correct": false, "explanation": "搭配：“它的”后面接的多是它能喜爱或占有的地方，地铁站不搭配。"}], "explanations": {"天堂": "天堂：让人幸福的好地方，与“小猫喜欢这个花园”的句意吻合。", "医院": "语义：医院是看病的地方，小猫不会觉得花园是医院，句意不通。", "办公室": "语义：办公室是工作的地方，与小猫喜欢的花园相矛盾。", "地铁站": "搭配：“它的”后面接的多是它能喜爱或占有的地方，地铁站不搭配。"}, "sentence_index": 6, "correct_answer": "天堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯挂在天堂上，照亮了整个房间。", "explanation": "这里应该用〈天花板〉。天堂指死后去的美好地方或幸福的地方，不指房顶；灯挂在天花板上才合理。"}, {"text": "夕阳慢慢沉入远处的天堂。", "explanation": "这里应该用〈天际〉（天与地相接的远方）。天堂不指远处的地平线。"}, {"text": "站在山顶，眼前是开阔的天堂。", "explanation": "这里应该用〈天地〉（广阔的空间）。天堂不用来形容山顶看到的广阔空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在图书馆里，我觉得自己像天堂里。", "corrected_sentence": "在图书馆里，我觉得自己像在天堂里。", "error_description": "“像在天堂里”的“在”不能省略，应说“像在天堂里”，不说“像天堂里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市是很美食家的天堂。", "corrected_sentence": "这座城市是美食家的天堂。", "error_description": "“很”不能修饰名词“美食家”，应说“美食家的天堂”，不说“很美食家的天堂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8a15572-f0ee-46c7-a625-1cca33a93d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
