INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91611, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吵架以后不再生气，重新做朋友。", "primary_collocate": null, "pronunciation": "jiǎng hé", "ipa": "tɕjɑŋ˨˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他们吵了一架，后来又讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快去跟妹妹讲和吧。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个朋友吵架后，很快就讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟他讲和，可是不知道怎么说。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥先说了对不起，我们就讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们已经讲和了，又一起去逛街了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩讲和以后，还是好朋友。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气了，跟老同学讲和吧。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架以后，我先找她讲和。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们打了架，不到一个小时就讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讲和了", "label": "体标"}, {"form": "讲和过", "label": "体标"}, {"form": "講和", "label": "繁体"}], "register": "口语", "sense_fingerprint": "个人之间吵架后和好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲和", "is_correct": true, "explanation": "「讲和」指吵架后不再生气、恢复和好，符合「吵了一架，后来又」的语境。"}, {"text": "怀念", "is_correct": false, "explanation": "配价：「怀念」后面要带宾语，这里没有宾语，句子不成立。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：「欢迎」的对象不合语境，吵架之后不能说「又欢迎了」。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：「祝贺」表示庆贺喜事，与吵架后的情境不符。"}], "explanations": {"讲和": "「讲和」指吵架后不再生气、恢复和好，符合「吵了一架，后来又」的语境。", "怀念": "配价：「怀念」后面要带宾语，这里没有宾语，句子不成立。", "欢迎": "语义：「欢迎」的对象不合语境，吵架之后不能说「又欢迎了」。", "祝贺": "语义：「祝贺」表示庆贺喜事，与吵架后的情境不符。"}, "sentence_index": 0, "correct_answer": "讲和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们开会讲和，讨论了三个小时。", "explanation": "这里应该用〈讨论〉。「讲和」指吵架后重新和好，不能用于开会商议。"}, {"text": "你做事太不讲和，大家都讨厌你。", "explanation": "这里应该用〈讲理〉。「讲和」指吵架后和好，说人做事有没有道理要用「讲理」。"}, {"text": "他在台上讲和，声音很大。", "explanation": "这里应该用〈演讲〉。「讲和」只指冲突后和好，人在台上发言要说「演讲」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲和", "is_correct": true, "explanation": "「讲和」指吵架后和好，与「还是好朋友」相符。"}, {"text": "绝交", "is_correct": false, "explanation": "语义：「绝交」指断绝交往，与「还是好朋友」矛盾。"}, {"text": "翻脸", "is_correct": false, "explanation": "语义：「翻脸」指关系闹翻，与「还是好朋友」矛盾。"}, {"text": "怨恨", "is_correct": false, "explanation": "配价：「怨恨」后面要带宾语，这里没有宾语，句子不成立。"}], "explanations": {"讲和": "「讲和」指吵架后和好，与「还是好朋友」相符。", "绝交": "语义：「绝交」指断绝交往，与「还是好朋友」矛盾。", "翻脸": "语义：「翻脸」指关系闹翻，与「还是好朋友」矛盾。", "怨恨": "配价：「怨恨」后面要带宾语，这里没有宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "讲和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在教室里讲和，同学们都认真听。", "explanation": "这里应该用〈讲课〉。「讲课」指教师授课，「讲和」只指冲突双方和好，不能用于上课。"}, {"text": "我们为价格讲和了很久，最后买下了。", "explanation": "这里应该用〈讲价〉。「讲价」指买卖时商量价格，「讲和」只指冲突后和好。"}, {"text": "他在会上讲和很激动。", "explanation": "这里应该用〈讲话〉。「讲话」指发言，「讲和」只指和好，不能用于会议发言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩吵了一天，晚上终于把讲和了。", "corrected_sentence": "他们俩吵了一天，晚上终于讲和了。", "error_description": "「讲和」是不及物动词，不能用「把」字句。错误形式是「把讲和了」，正确形式是「讲和了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吵完架以后，他们很快就讲和着。", "corrected_sentence": "吵完架以后，他们很快就讲和了。", "error_description": "「讲和」表示动作已经完成，应用「了」，不能用「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
