INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "争执或战斗的双方停止冲突，恢复和好。", "primary_collocate": null, "pronunciation": "jiǎng hé", "ipa": "tɕjɑŋ˨˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "两个国家打了很多年，最后讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司争了很久，终于讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，双方决定讲和。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个村子为水打架，后来在老人的劝说下讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个部落不再打仗，开始讲和。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个大国已经讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家人为一块地争了很久，今天终于讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方谈了三天，还是没有讲和。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国王打累了，只好讲和。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队的球迷打了架，后来在警察的帮助下讲和了。", "target_word": "讲和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讲和了", "label": "体标"}, {"form": "讲和过", "label": "体标"}, {"form": "講和", "label": "繁体"}], "register": "口语", "sense_fingerprint": "国家、团体等冲突双方停战和解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲和", "is_correct": true, "explanation": "「讲和」指冲突双方停止打仗、恢复和好，符合「打了很多年，最后」的语境。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：两个国家不能「结婚」，与「打了很多年」的语境不符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：「旅游」与长期战争的语境毫无关联，句子不通。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：「表扬」后面要带宾语，这里没有宾语，句子不成立。"}], "explanations": {"讲和": "「讲和」指冲突双方停止打仗、恢复和好，符合「打了很多年，最后」的语境。", "结婚": "语义：两个国家不能「结婚」，与「打了很多年」的语境不符。", "旅游": "语义：「旅游」与长期战争的语境毫无关联，句子不通。", "表扬": "配价：「表扬」后面要带宾语，这里没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "讲和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长在操场上讲和，大家都站着听。", "explanation": "这里应该用〈讲话〉。「讲和」只指冲突双方和好，在操场上发言要说「讲话」。"}, {"text": "睡觉前，妈妈给孩子讲和。", "explanation": "这里应该用〈讲故事〉。「讲和」指冲突双方停止冲突、恢复和好，给孩子讲故事不是和解。"}, {"text": "比赛输了，他们只好讲和。", "explanation": "这里应该用〈认输〉。「讲和」指双方和解，输了比赛只能认输，不能说讲和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲和", "is_correct": true, "explanation": "「讲和」指停止争执、恢复和好，符合「争了很久，今天终于」的语境。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」与「为一块地争了很久」毫无关联，句子不通。"}, {"text": "上学", "is_correct": false, "explanation": "语义：「上学」与争夺土地的语境不符，句子不通。"}, {"text": "通知", "is_correct": false, "explanation": "配价：「通知」后面要带宾语，这里没有宾语，句子不成立。"}], "explanations": {"讲和": "「讲和」指停止争执、恢复和好，符合「争了很久，今天终于」的语境。", "散步": "语义：「散步」与「为一块地争了很久」毫无关联，句子不通。", "上学": "语义：「上学」与争夺土地的语境不符，句子不通。", "通知": "配价：「通知」后面要带宾语，这里没有宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "讲和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们为价格讲和了很久，最后买下了。", "explanation": "这里应该用〈讲价〉。「讲价」指买卖时商量价格，「讲和」只指冲突后和好。"}, {"text": "老师在教室里讲和，同学们都认真听。", "explanation": "这里应该用〈讲课〉。「讲课」指教师授课，「讲和」只指冲突双方和好，不能用于上课。"}, {"text": "两队打成平局，所以讲和了。", "explanation": "这里应该用〈打平〉。「讲和」指冲突双方停止冲突，比赛打平不是冲突停止，不能说讲和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国打了几年仗，今年终于把讲和了。", "corrected_sentence": "两国打了几年仗，今年终于讲和了。", "error_description": "「讲和」是不及物动词，不能用「把」字句。错误形式是「把讲和了」，正确形式是「讲和了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "双方停火以后，很快就讲和着。", "corrected_sentence": "双方停火以后，很快就讲和了。", "error_description": "「讲和」表示动作已经完成，应用「了」，不能用「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
