INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行径是一个人做的事，常是不好的。", "primary_collocate": null, "pronunciation": "xíng jìng", "ipa": "ɕiŋ˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他偷别人东西的行径，让大家很生气。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批评了他这种不讲理的行径。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骗老人钱的行径，谁都看不起。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的行径是不对的，你要向她道歉。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居发现了他的可耻行径。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上写了那个人的坏行径。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他欺负同学的行径，我们都很不喜欢。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友知道了他的这些行径，不再理他了。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种自私的行径，在学校里不能有。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人喜欢他那种霸道的行径。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "行徑", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "一个人做的事，多指不好的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91613, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行径", "is_correct": true, "explanation": "正确：行径（xíng jìng）指人做的事，多指不好的行为。"}, {"text": "行进", "is_correct": false, "explanation": "「行进」与「行径」第二个音节韵尾不同（jìn 与 jìng），意思是向前走。"}, {"text": "刑警", "is_correct": false, "explanation": "「刑警」与「行径」第二个音节声调不同（jǐng 第三声与 jìng 第四声），意思是刑事侦查的警察。"}, {"text": "行经", "is_correct": false, "explanation": "「行经」与「行径」第二个音节声调不同（jīng 第一声与 jìng 第四声），意思是经过某地。"}], "explanations": {"行径": "正确：行径（xíng jìng）指人做的事，多指不好的行为。", "行进": "「行进」与「行径」第二个音节韵尾不同（jìn 与 jìng），意思是向前走。", "刑警": "「刑警」与「行径」第二个音节声调不同（jǐng 第三声与 jìng 第四声），意思是刑事侦查的警察。", "行经": "「行经」与「行径」第二个音节声调不同（jīng 第一声与 jìng 第四声），意思是经过某地。"}, "sentence_index": null, "correct_answer": "行径"}, "level_3": {"options": [{"text": "行径", "is_correct": true, "explanation": "正确：行径指人做的事，这里指偷别人东西的行为。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心感受，不是人做的事，“偷别人东西的心情让大家很生气”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“偷别人东西”是具体的行为，不能用来修饰“脾气”。"}, {"text": "相貌", "is_correct": false, "explanation": "语义：“相貌”指外貌长相，不是做的事，不能说“偷别人东西的相貌”。"}], "explanations": {"行径": "正确：行径指人做的事，这里指偷别人东西的行为。", "心情": "语义：“心情”是内心感受，不是人做的事，“偷别人东西的心情让大家很生气”说不通。", "脾气": "搭配：“偷别人东西”是具体的行为，不能用来修饰“脾气”。", "相貌": "语义：“相貌”指外貌长相，不是做的事，不能说“偷别人东西的相貌”。"}, "sentence_index": 0, "correct_answer": "行径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要马上采取行径。", "explanation": "这里应该用〈行动〉。采取用于行动、措施，行径指人做的事，不能说采取行径。"}, {"text": "这一把行径让大家很生气。", "explanation": "这里应该用〈种〉。行径是抽象的做法，量词应用“种”，“把”用于有柄的东西。"}, {"text": "他的行径很严谨。", "explanation": "这里应该用〈作风〉。严谨用于作风、态度，行径指具体做的事，不能说行径很严谨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行径", "is_correct": true, "explanation": "正确：行径指人做的事，这里指欺负同学的行为。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”是送给别人的东西，不是做的事，与“欺负同学”矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“欺负同学”是行为，不能用来修饰“颜色”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是东西值多少钱，不是做的事，不能说“欺负同学的价格”。"}], "explanations": {"行径": "正确：行径指人做的事，这里指欺负同学的行为。", "礼物": "语义：“礼物”是送给别人的东西，不是做的事，与“欺负同学”矛盾。", "颜色": "语义：“欺负同学”是行为，不能用来修饰“颜色”。", "价格": "语义：“价格”是东西值多少钱，不是做的事，不能说“欺负同学的价格”。"}, "sentence_index": 6, "correct_answer": "行径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养成了一个很坏的行径。", "explanation": "这里应该用〈习惯〉。养成用于习惯、品行，行径指做的具体事情，不能说养成行径。"}, {"text": "他对朋友的行径很真诚。", "explanation": "这里应该用〈态度〉。真诚用于态度、感情，行径指做的事，不能用真诚来形容。"}, {"text": "这台行径让大家很失望。", "explanation": "这里应该用〈种〉。量词“台”用于机器、设备，行径应用“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他那只行径让大家很失望。", "corrected_sentence": "他那种行径让大家很失望。", "error_description": "错误：「那只行径」；正确：「那种行径」。行径是抽象的做法，量词应用“种”，“只”多用于动物或单个小物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都讨厌他那种自私地行径。", "corrected_sentence": "大家都讨厌他那种自私的行径。", "error_description": "错误：「自私地行径」；正确：「自私的行径」。“行径”是名词，修饰语要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
