INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行为；做法，多指不好的。", "primary_collocate": null, "pronunciation": "xíng jìng", "ipa": "ɕiŋ˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "摄像头拍下了小偷的行径。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都在说他那卑鄙的行径。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种行径会让别人不再相信你。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打人的行径太过分了，应该受到批评。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不喜欢弟弟说谎的行径。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司对他的恶劣行径很失望。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随地吐痰是不文明的行径。", "target_word": "行径", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样的行径，在哪里都不受欢迎。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不要学他那种坏行径。", "target_word": "行径", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的行径让全家人都很丢脸。", "target_word": "行径", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "行徑", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "行为、做法，多含贬义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行径", "is_correct": true, "explanation": "正确：行径（xíng jìng）指做的事，多指不好的行为。"}, {"text": "行进", "is_correct": false, "explanation": "「行进」与「行径」第二个音节韵尾不同（jìn 与 jìng），意思是向前走。"}, {"text": "刑警", "is_correct": false, "explanation": "「刑警」与「行径」第二个音节声调不同（jǐng 第三声与 jìng 第四声），意思是刑事侦查的警察。"}, {"text": "行经", "is_correct": false, "explanation": "「行经」与「行径」第二个音节声调不同（jīng 第一声与 jìng 第四声），意思是经过某地。"}], "explanations": {"行径": "正确：行径（xíng jìng）指做的事，多指不好的行为。", "行进": "「行进」与「行径」第二个音节韵尾不同（jìn 与 jìng），意思是向前走。", "刑警": "「刑警」与「行径」第二个音节声调不同（jǐng 第三声与 jìng 第四声），意思是刑事侦查的警察。", "行经": "「行经」与「行径」第二个音节声调不同（jīng 第一声与 jìng 第四声），意思是经过某地。"}, "sentence_index": null, "correct_answer": "行径"}, "level_3": {"options": [{"text": "行径", "is_correct": true, "explanation": "正确：行径指做的事，这里指小偷的偷窃行为。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心感受，摄像头拍不下来，也不是小偷做的事。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“拍下”的是可见的行为或场景，不能拍下“脾气”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不是做的事，摄像头拍不下年龄。"}], "explanations": {"行径": "正确：行径指做的事，这里指小偷的偷窃行为。", "心情": "语义：“心情”是内心感受，摄像头拍不下来，也不是小偷做的事。", "脾气": "搭配：“拍下”的是可见的行为或场景，不能拍下“脾气”。", "年龄": "语义：“年龄”是人的岁数，不是做的事，摄像头拍不下年龄。"}, "sentence_index": 0, "correct_answer": "行径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们决定采取行径，保护这片森林。", "explanation": "这里应该用〈行动〉。采取用于行动、措施，行径指人做的事，不能说采取行径。"}, {"text": "他对工作的行径很认真。", "explanation": "这里应该用〈态度〉。认真用于态度，行径指做的具体事，不能用来形容工作的认真程度。"}, {"text": "这一把行径让人很失望。", "explanation": "这里应该用〈种〉。量词用错：行径应用“种”，“把”用于有柄的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行径", "is_correct": true, "explanation": "正确：行径指人做的事，这里指随地吐痰这种不文明的行为。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”是送给别人的东西，随地吐痰不是礼物。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“不文明”修饰行为，不能修饰颜色。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指外貌长相，“不文明”不能修饰相貌。"}], "explanations": {"行径": "正确：行径指人做的事，这里指随地吐痰这种不文明的行为。", "礼物": "语义：“礼物”是送给别人的东西，随地吐痰不是礼物。", "颜色": "搭配：“不文明”修饰行为，不能修饰颜色。", "相貌": "体貌：“相貌”指外貌长相，“不文明”不能修饰相貌。"}, "sentence_index": 6, "correct_answer": "行径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经养成了早睡的行径。", "explanation": "这里应该用〈习惯〉。养成用于习惯，行径指做的事，不能说养成行径。"}, {"text": "他在比赛中的行径很出色。", "explanation": "这里应该用〈表现〉。出色用于表现、成绩；行径指做的事，且多指不好的行为，不能评价为出色。"}, {"text": "这台行径让全家人很生气。", "explanation": "这里应该用〈种〉。量词用错：行径应用“种”，“台”用于机器、设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那样地行径让邻居们都很难过。", "corrected_sentence": "那样的行径让邻居们都很难过。", "error_description": "错误：「那样地行径」；正确：「那样的行径」。“行径”是名词，前面的修饰语要用结构助词“的”，“地”用于修饰动词、形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只行径，在哪里都会被人讨厌。", "corrected_sentence": "这种行径，在哪里都会被人讨厌。", "error_description": "错误：「这只行径」；正确：「这种行径」。行径是抽象的做法，量词应用“种”，“只”多用于动物或单个小物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
