INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91617, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请别人让一让，走到旁边去。", "primary_collocate": null, "pronunciation": "qǐ kāi", "ipa": "tɕʰi˨˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "请你起开一点，我要过去。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起开，别挡着我的路！", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麻烦你起开一下，我拿东西。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快起开，车要过来了。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对前面的人说：“请起开！”", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：“起开，让我进去。”", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅喊了一声：“都起开，小心烫！”", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们起开点儿，让医生过来。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挤不过去，只好说：“劳驾，起开一下。”", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家起开，让老人先走。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "动词，口语中请求或招呼别人让路、走到一边，多用于祈使句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91617, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "躺下", "is_correct": false, "explanation": "语义：“躺下”表示躺倒，请人躺下来让路不合情理，与“我要过去”的语境无关。"}, {"text": "起开", "is_correct": true, "explanation": "“起开”表示请别人让一让、走到旁边去，正好符合“请你起开一点，我要过去”的语境。"}, {"text": "放低", "is_correct": false, "explanation": "搭配：“放低”多用于声音、姿态、价格，不能用来请人让路。"}, {"text": "站近", "is_correct": false, "explanation": "语义：“站近”表示靠近，与请对方让出路好让我过去的意思正好相反。"}], "explanations": {"躺下": "语义：“躺下”表示躺倒，请人躺下来让路不合情理，与“我要过去”的语境无关。", "起开": "“起开”表示请别人让一让、走到旁边去，正好符合“请你起开一点，我要过去”的语境。", "放低": "搭配：“放低”多用于声音、姿态、价格，不能用来请人让路。", "站近": "语义：“站近”表示靠近，与请对方让出路好让我过去的意思正好相反。"}, "sentence_index": 0, "correct_answer": "起开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从沙发上起开。", "explanation": "这里应该用〈站起来〉。起开表示请别人让路、走到旁边去，不表示从座位上起身。"}, {"text": "我每天六点起开。", "explanation": "这里应该用〈起床〉。起开是请人让路的用法，不能用于早晨醒来后起床。"}, {"text": "她匆忙起开，没有回头。", "explanation": "这里应该用〈离开〉。起开多用于请别人让路，不用于叙述“她”自己离去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "让步", "is_correct": false, "explanation": "语义：“让步”表示退让、迁就，与请大家走到旁边去的意思不同。"}, {"text": "闭嘴", "is_correct": false, "explanation": "语义：“闭嘴”表示不再说话，与“小心烫”的提醒对不上，也不是让开的意思。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与让开、给师傅让出空间无关，和“小心烫”的提醒对不上。"}, {"text": "起开", "is_correct": true, "explanation": "“起开”表示请大家让开，给师傅让出空间，与“小心烫”的语境相符。"}], "explanations": {"让步": "语义：“让步”表示退让、迁就，与请大家走到旁边去的意思不同。", "闭嘴": "语义：“闭嘴”表示不再说话，与“小心烫”的提醒对不上，也不是让开的意思。", "唱歌": "语义：“唱歌”与让开、给师傅让出空间无关，和“小心烫”的提醒对不上。", "起开": "“起开”表示请大家让开，给师傅让出空间，与“小心烫”的语境相符。"}, "sentence_index": 6, "correct_answer": "起开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "升旗时，大家都起开敬礼。", "explanation": "这里应该用〈起立〉。起开表示让开，不表示站起身来。"}, {"text": "他把墙起开了。", "explanation": "这里应该用〈推开〉。起开多用于请人让路，不能用于对墙这类东西施力使其移开。"}, {"text": "他一早起开，揉了揉眼睛。", "explanation": "这里应该用〈醒来〉。起开表示请人让路，不表示睡醒后起身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请您起开了一下，我要进屋。", "corrected_sentence": "请您起开一下，我要进屋。", "error_description": "“了”误用：请人让路的祈使请求中，“起开”后不用“了”，应说“请您起开一下，我要进屋”，不能说“请您起开了一下，我要进屋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请大家起开了一下，让老人先走。", "corrected_sentence": "请大家起开一下，让老人先走。", "error_description": "“了”误用：祈使请求中不用“了”，应说“请大家起开一下”，不能说“起开了一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
