INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "方言，叫人让开、走开。", "primary_collocate": null, "pronunciation": "qǐ kāi", "ipa": "tɕʰi˨˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "你给我起开，别在这儿捣乱！", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起开起开，别站在这儿！", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气就喊：“起开！”", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张推开门，说：“都起开，让我看看。”", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你起开，这活儿我来干。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快起开，水洒了你一身。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌弟弟碍事，让他起开。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的人太多，大爷喊着让大家起开。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别挡路，起开点儿！", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子，你先起开，让我把车开过去。", "target_word": "起开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "方言", "sense_fingerprint": "动词，方言中带不耐烦的语气叫人让开、走开，多用于命令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91618, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与叫人让开、走开毫无关系，不能用来斥责对方在这儿捣乱。"}, {"text": "起开", "is_correct": true, "explanation": "“起开”是方言，带着不耐烦的语气叫人让开、走开，正好符合“别在这儿捣乱”的斥责语境。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”与斥责对方捣乱、叫人走开无关，“你给我写字”说不通。"}, {"text": "说话", "is_correct": false, "explanation": "语义：“说话”只表示开口，不表示让开，“你给我说话”与赶人走开的语境不符。"}], "explanations": {"吃饭": "语义：“吃饭”与叫人让开、走开毫无关系，不能用来斥责对方在这儿捣乱。", "起开": "“起开”是方言，带着不耐烦的语气叫人让开、走开，正好符合“别在这儿捣乱”的斥责语境。", "写字": "语义：“写字”与斥责对方捣乱、叫人走开无关，“你给我写字”说不通。", "说话": "语义：“说话”只表示开口，不表示让开，“你给我说话”与赶人走开的语境不符。"}, "sentence_index": 0, "correct_answer": "起开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从凳子上起开，伸了个懒腰。", "explanation": "这里应该用〈站起来〉。起开是叫人让开的方言用法，不表示自己从座位上起身。"}, {"text": "他一醒来就起开。", "explanation": "这里应该用〈起床〉。起开表示叫人让开，不表示睡醒后起身下床。"}, {"text": "音乐响起来，舞会起开了。", "explanation": "这里应该用〈开始〉。起开是叫人让开的方言用法，不表示活动或事情开始进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长大", "is_correct": false, "explanation": "语义：“长大”指年龄增长，与弟弟碍事、要他让开没有关系，“让他长大”说不通。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”不能表示让开、避开，与“碍事”的语境不符。"}, {"text": "扔掉", "is_correct": false, "explanation": "配价：“扔掉”是及物动词，需要受事宾语，“让他扔掉”缺少宾语，也不是让开的意思。"}, {"text": "起开", "is_correct": true, "explanation": "“起开”表示让人让开、走到旁边去，正好说明弟弟挡了路、碍事。"}], "explanations": {"长大": "语义：“长大”指年龄增长，与弟弟碍事、要他让开没有关系，“让他长大”说不通。", "写字": "语义：“写字”不能表示让开、避开，与“碍事”的语境不符。", "扔掉": "配价：“扔掉”是及物动词，需要受事宾语，“让他扔掉”缺少宾语，也不是让开的意思。", "起开": "“起开”表示让人让开、走到旁边去，正好说明弟弟挡了路、碍事。"}, "sentence_index": 6, "correct_answer": "起开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师一进教室，全班同学都起开问好。", "explanation": "这里应该用〈起立〉。起开表示让开，不表示站起身来。"}, {"text": "部队起开了，阵地空了。", "explanation": "这里应该用〈撤退〉。起开是请人让路的用法，不表示军队有组织地后撤。"}, {"text": "他带头起开了这次活动。", "explanation": "这里应该用〈发起〉。起开表示叫人让开，不表示倡导、发动某项活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你给我起开过，别挡着门口！", "corrected_sentence": "你给我起开，别挡着门口！", "error_description": "“过”误用：命令语气中“起开”后不能加表示经历的“过”，应说“你给我起开，别挡着门口！”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们都先起开了一下，让我过去。", "corrected_sentence": "你们都先起开一下，让我过去。", "error_description": "“了”误用：叫人让路的祈使请求中，“起开”后不用“了”，应说“你们都先起开一下，让我过去”，不能说“你们都先起开了一下，让我过去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
