INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91619, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行情是日常买东西时，东西现在卖多少钱的情况。", "primary_collocate": null, "pronunciation": "háng qíng", "ipa": "xɑŋ˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我先问问今天菜市场的行情。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近水果的行情不错，卖得很快。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买二手手机以前，要先看看行情。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说现在的猪肉行情比去年高。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂行情，把东西买贵了。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶叶现在是什么行情？", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去市场看看行情，再决定买不买。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开店以前，她每天都去了解行情。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在大米的行情很稳，没有涨也没有跌。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友告诉我，旧车的行情这个月下降了。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市场行情", "label": "复合"}], "register": "中性", "sense_fingerprint": "行情：日常买卖中东西现在的价格情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行情", "is_correct": true, "explanation": "正确：这里指市场上的价格和供求情况，可以在菜市场打听，与句意相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是可以在菜市场打听的对象。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是需要打听的情况。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是具体的东西，不是去菜市场打听的价格情况，句意不通。"}], "explanations": {"行情": "正确：这里指市场上的价格和供求情况，可以在菜市场打听，与句意相符。", "电脑": "语义：电脑不是可以在菜市场打听的对象。", "书包": "语义：书包不是需要打听的情况。", "冰箱": "语义：冰箱是具体的东西，不是去菜市场打听的价格情况，句意不通。"}, "sentence_index": 0, "correct_answer": "行情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身体行情很好，每天都能跑步。", "explanation": "这里应该用〈状况〉。行情指东西现在卖多少钱的情况，说人的身体状态不能用行情。"}, {"text": "明天的行情是晴天，很适合出去玩。", "explanation": "这里应该用〈天气〉。行情指东西现在卖多少钱的情况，描述晴雨要说天气。"}, {"text": "这场比赛的行情是三比一。", "explanation": "这里应该用〈比分〉。行情指东西现在卖多少钱的情况，比赛的得分要说比分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行情", "is_correct": true, "explanation": "正确：这里指东西现在的价格情况，去市场看看行情才能决定买不买，与句意相符。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史不能在市场上看，句意不通。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“看看”后接可以观察的对象，感情不能这样搭配。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不能在市场上看，与买东西无关。"}], "explanations": {"行情": "正确：这里指东西现在的价格情况，去市场看看行情才能决定买不买，与句意相符。", "历史": "语义：历史不能在市场上看，句意不通。", "感情": "搭配：“看看”后接可以观察的对象，感情不能这样搭配。", "心情": "语义：心情不能在市场上看，与买东西无关。"}, "sentence_index": 6, "correct_answer": "行情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的行情已经稳定了，医生很放心。", "explanation": "这里应该用〈病情〉。行情指东西现在卖多少钱的情况，病人的身体状况要用病情。"}, {"text": "这门课的行情是三个小时。", "explanation": "这里应该用〈课时〉。行情指东西现在卖多少钱的情况，课程的时长要用课时。"}, {"text": "这家店的行情已经有十年了。", "explanation": "这里应该用〈历史〉。行情指东西现在卖多少钱的情况，店铺存在的时间要用历史。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只行情的变化很大。", "corrected_sentence": "这种行情的变化很大。", "error_description": "量词错误：“行情”是抽象概念，应用量词“种”。“只”多用于动物等具体事物，所以“这只行情”错误，应改为“这种行情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友告诉我，旧车的行情这个月下降了很厉害。", "corrected_sentence": "朋友告诉我，旧车的行情这个月下降得很厉害。", "error_description": "补语错误：“下降”后接程度补语应用“得”，不能用“了”，应为“下降得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
