INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91620, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "市场上商品、股市或房地产等的价格与供求走势。", "primary_collocate": null, "pronunciation": "háng qíng", "ipa": "xɑŋ˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "专家分析了今年房地产市场的行情。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受天气影响，蔬菜的行情很不稳定。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批大米要运往外地，商人先打听了一下行情。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司每天都会发布原油行情。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为需求增加，钢铁行情一路上涨。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看新闻，关注黄金的行情变化。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年茶叶供过于求，行情一直不好。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场行情经常变化，商人要及时调整价格。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上每天都有各种商品的行情。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受战争影响，国际石油行情大幅波动。", "target_word": "行情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股市行情", "label": "复合"}], "register": "中性", "sense_fingerprint": "行情：商品、股市或房地产市场的价格与供求走势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行情", "is_correct": true, "explanation": "正确：这里指房地产市场的价格和供求情况，与“分析”的对象相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是市场分析的对象。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是市场分析的对象。"}, {"text": "爱好", "is_correct": false, "explanation": "搭配：“分析”的对象应是市场情况，爱好不能与房地产市场搭配。"}], "explanations": {"行情": "正确：这里指房地产市场的价格和供求情况，与“分析”的对象相符。", "电脑": "语义：电脑不是市场分析的对象。", "书包": "语义：书包不是市场分析的对象。", "爱好": "搭配：“分析”的对象应是市场情况，爱好不能与房地产市场搭配。"}, "sentence_index": 0, "correct_answer": "行情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个病人的行情很稳定，明天可以出院了。", "explanation": "这里应该用〈病情〉。行情指市场上商品的价格和供求情况，病人的身体状况要用病情。"}, {"text": "这次晚会的行情很火爆，大家都很开心。", "explanation": "这里应该用〈气氛〉。行情指市场上商品的价格和供求情况，晚会热闹的场面要说气氛。"}, {"text": "这个周末的行情是雨天，我们取消了郊游。", "explanation": "这里应该用〈天气〉。行情指市场上商品的价格和供求情况，描述雨晴要说天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行情", "is_correct": true, "explanation": "正确：这里指茶叶市场的价格和供求情况，与“供过于求”相符。"}, {"text": "身体", "is_correct": false, "explanation": "语义：身体的好坏与茶叶的供求无关。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户的好坏与供过于求无关。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”不能与“一直不好”组成与茶叶供求相关的说法。"}], "explanations": {"行情": "正确：这里指茶叶市场的价格和供求情况，与“供过于求”相符。", "身体": "语义：身体的好坏与茶叶的供求无关。", "窗户": "语义：窗户的好坏与供过于求无关。", "人口": "搭配：“人口”不能与“一直不好”组成与茶叶供求相关的说法。"}, "sentence_index": 6, "correct_answer": "行情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段路的行情是五公里。", "explanation": "这里应该用〈路程〉。行情指市场上商品的价格和供求情况，路的长度要用路程。"}, {"text": "这项工程的行情已经完成了一半。", "explanation": "这里应该用〈进度〉。行情指市场上商品的价格和供求情况，工程的进展要说进度。"}, {"text": "这部电影的行情是两个小时。", "explanation": "这里应该用〈时长〉。行情指市场上商品的价格和供求情况，电影的时间长度要说时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只行情让农民很高兴。", "corrected_sentence": "这种行情让农民很高兴。", "error_description": "量词错误：“行情”是抽象概念，应用量词“种”。“只”多用于动物等具体事物，所以“这只行情”错误，应改为“这种行情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都说，市场行情涨了很快。", "corrected_sentence": "大家都说，市场行情涨得很快。", "error_description": "补语错误：“涨”后接程度补语应用“得”，不能用“了”，应为“涨得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
