INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91621, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在工作的地方做事。", "primary_collocate": null, "pronunciation": "bàn gōng", "ipa": "pan˥˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我们公司九点开始办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在公司里办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王喜欢在安静的地方办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行下午五点停止办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的电脑坏了，没法办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新大楼很大，几百人可以一起办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在房间里办公，请别打扰。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间，银行不办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里太吵了，没办法办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换了新地方，在这里办公很舒服。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在工作的地方做事，指在单位或工作场所上班做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办公", "is_correct": true, "explanation": "办公：在工作的地方做事，与“九点开始”相合。"}, {"text": "下班", "is_correct": false, "explanation": "语义：“下班”指结束工作，与“九点开始”矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是工作活动，“公司九点开始睡觉”语义荒谬。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指停止工作休息，与“九点开始”的工作开端矛盾。"}], "explanations": {"办公": "办公：在工作的地方做事，与“九点开始”相合。", "下班": "语义：“下班”指结束工作，与“九点开始”矛盾。", "睡觉": "语义：“睡觉”不是工作活动，“公司九点开始睡觉”语义荒谬。", "放假": "语义：“放假”指停止工作休息，与“九点开始”的工作开端矛盾。"}, "sentence_index": 0, "correct_answer": "办公"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在教室里办公。", "explanation": "这里应该用〈学习〉。办公指在工作单位处理工作，学生在教室里学习不能说办公。"}, {"text": "孩子们在公园里办公。", "explanation": "这里应该用〈玩〉。办公指做工作，孩子在公园玩不能说办公。"}, {"text": "游客们在游泳池里办公。", "explanation": "这里应该用〈游泳〉。办公指在工作场所处理事务，游客在游泳池里游泳不能说办公。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办公", "is_correct": true, "explanation": "办公：在工作的地方做事，与“请别打扰”的工作语境相合。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指到外地工作，与“在房间里”矛盾。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”指离开国家，与“在房间里”矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水池或水域，不能在房间里进行，与句意不符。"}], "explanations": {"办公": "办公：在工作的地方做事，与“请别打扰”的工作语境相合。", "出差": "语义：“出差”指到外地工作，与“在房间里”矛盾。", "出国": "语义：“出国”指离开国家，与“在房间里”矛盾。", "游泳": "语义：“游泳”需要水池或水域，不能在房间里进行，与句意不符。"}, "sentence_index": 6, "correct_answer": "办公"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "婴儿在婴儿床上办公。", "explanation": "这里应该用〈睡觉〉。办公指在工作场所处理事务，婴儿在婴儿床上睡觉不能说办公。"}, {"text": "她在舞台上办公。", "explanation": "这里应该用〈唱歌〉。办公指做工作，在舞台上唱歌不能说办公。"}, {"text": "我们周末去商场办公。", "explanation": "这里应该用〈逛街〉。办公指在工作场所处理事务，去商场逛街不能说办公。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们部门搬到新楼以后，大家在二层的办公。", "corrected_sentence": "我们部门搬到新楼以后，大家在二层办公。", "error_description": "结构错误：“在二层”是状语，后面直接接动词，加上“的”就变成名词短语，句子没有谓语，应说“大家在二层办公”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的老板一般在二楼把办公，很少下来。", "corrected_sentence": "这家公司的老板一般在二楼办公，很少下来。", "error_description": "把字用错：“办公”是不带宾语的动作，“把办公”不成立，应去掉“把”，说“在二楼办公”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
