INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91622, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "处理公务。", "primary_collocate": null, "pronunciation": "bàn gōng", "ipa": "pan˥˩ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "市长每天都要办公到很晚。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长出国时，也在飞机上办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长今天出差，不能办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老书记生病了，还坚持办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边吃饭一边办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统在新的地方办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院长病好以后又开始办公了。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县长下乡也带着文件办公。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在车里办公，非常忙。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导们要认真办公，为大家做事。", "target_word": "办公", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "处理公务，指官员或工作人员处理公家的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办公", "is_correct": true, "explanation": "办公：处理公务，与“市长每天都要……到很晚”相合。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”是一次性的事，不能“每天都要……到很晚”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”只发生一次，市长不能每天出生，句意荒谬。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”不是每天进行到很晚的事，句意不通。"}], "explanations": {"办公": "办公：处理公务，与“市长每天都要……到很晚”相合。", "毕业": "语义：“毕业”是一次性的事，不能“每天都要……到很晚”。", "出生": "语义：“出生”只发生一次，市长不能每天出生，句意荒谬。", "结婚": "语义：“结婚”不是每天进行到很晚的事，句意不通。"}, "sentence_index": 0, "correct_answer": "办公"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们放假时还在办公。", "explanation": "这里应该用〈玩游戏〉。办公指处理公务，孩子放假时玩游戏不能说办公。"}, {"text": "保姆每天都办公。", "explanation": "这里应该用〈打扫〉。办公指处理公务，保姆每天打扫房子不能说办公。"}, {"text": "学生每晚都办公。", "explanation": "这里应该用〈做作业〉。办公指处理公务，学生每晚做作业不能说办公。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办公", "is_correct": true, "explanation": "办公：处理公务，与“病好以后又开始”的工作语境相合。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不是院长的活动，“院长……又开始下雨”语义不通。"}, {"text": "刮风", "is_correct": false, "explanation": "语义：“刮风”是天气现象，不是人的活动，与院长的身份不搭。"}, {"text": "打雷", "is_correct": false, "explanation": "语义：“打雷”是天气现象，不能由院长进行，句意不通。"}], "explanations": {"办公": "办公：处理公务，与“病好以后又开始”的工作语境相合。", "下雨": "语义：“下雨”是天气现象，不是院长的活动，“院长……又开始下雨”语义不通。", "刮风": "语义：“刮风”是天气现象，不是人的活动，与院长的身份不搭。", "打雷": "语义：“打雷”是天气现象，不能由院长进行，句意不通。"}, "sentence_index": 6, "correct_answer": "办公"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动员每天都在训练场办公。", "explanation": "这里应该用〈训练〉。办公指处理公务，运动员在训练场训练不能说办公。"}, {"text": "农民春天要认真办公。", "explanation": "这里应该用〈种地〉。办公指处理公务，农民春天种地不能说办公。"}, {"text": "演员在舞台上认真办公。", "explanation": "这里应该用〈表演〉。办公指处理公务，演员在舞台上表演不能说办公。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县长每天都要亲自处理公文，常常办公得深夜。", "corrected_sentence": "县长每天都要亲自处理公文，常常办公到深夜。", "error_description": "补语标记用错：表示时间终点要用“到”，不能用“得”，应说“常常办公到深夜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位副市长平时把熬夜办公，身体很辛苦。", "corrected_sentence": "这位副市长平时熬夜办公，身体很辛苦。", "error_description": "把字用错：“熬夜办公”是动词短语，“把”后面不能直接接动词，应去掉“把”，说“熬夜办公”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
