INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被子外层的面料。", "primary_collocate": null, "pronunciation": "bèi miàn", "ipa": "peɪ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种被面是纯棉的，很舒服。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天最好选凉快的被面。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这床被子的被面是丝绸做的。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被面太硬，睡觉不舒服。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一个红色的被面，过年用。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的被面有点味道，先洗一洗。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她挑了一块带花的被面，打算做新被子。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个被面用了十年，还是很好看。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被面的颜色洗过以后变浅了。", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板，请问这个被面多少钱一米？", "target_word": "被面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：被子外层所用的面料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6fc0c8a-a2f4-4258-9b79-7225f30965f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被面", "is_correct": true, "explanation": "正确：被面是布料，可以是纯棉的，与“这种……是纯棉的”相合。"}, {"text": "丝绸", "is_correct": false, "explanation": "语义：丝绸是蚕丝织成的，与“纯棉的”矛盾。"}, {"text": "皮革", "is_correct": false, "explanation": "语义：皮革不是棉制品，与“纯棉的”矛盾。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“纯棉”只修饰织物，不能修饰食品。"}], "explanations": {"被面": "正确：被面是布料，可以是纯棉的，与“这种……是纯棉的”相合。", "丝绸": "语义：丝绸是蚕丝织成的，与“纯棉的”矛盾。", "皮革": "语义：皮革不是棉制品，与“纯棉的”矛盾。", "面包": "搭配：“纯棉”只修饰织物，不能修饰食品。"}, "sentence_index": 0, "correct_answer": "被面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厚被面盖着很暖和，冬天很舒服。", "explanation": "这里应该用〈被子〉。被面只是外层的布，保暖的是整床被子，不能说“被面盖着很暖和”。"}, {"text": "他拿被面当毛巾擦了擦手上的水。", "explanation": "这里应该用〈毛巾〉。被面是做被子外层的面料，不是擦手用的毛巾。"}, {"text": "被面是棉花做的，很蓬松。", "explanation": "这里应该用〈被芯〉。被面是布料，棉花是填在被子里的被芯，不能说“被面是棉花做的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被面", "is_correct": true, "explanation": "正确：被面是用来做被子外层的布，与“打算做新被子”相合。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花是未加工的纤维，不是布，也不会“带花”。"}, {"text": "砖", "is_correct": false, "explanation": "语义：砖不是布，与“带花的”和“做新被子”都不合。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“块”不用于花瓶，花瓶用“个”或“只”计量，而且不能拿来做被子。"}], "explanations": {"被面": "正确：被面是用来做被子外层的布，与“打算做新被子”相合。", "棉花": "语义：棉花是未加工的纤维，不是布，也不会“带花”。", "砖": "语义：砖不是布，与“带花的”和“做新被子”都不合。", "花瓶": "搭配：“块”不用于花瓶，花瓶用“个”或“只”计量，而且不能拿来做被子。"}, "sentence_index": 6, "correct_answer": "被面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的被面晒得很黑，常年在地里干活。", "explanation": "这里把“被面”用来指人的皮肤，被面只指被子外面的面料，不能这样说。"}, {"text": "妈妈用被面做了一锅热腾腾的面条。", "explanation": "这里应该用〈面粉〉。“被面”指被子外层的面料，不能用来做面条，做面条要用面粉。"}, {"text": "这座房子的被面刷成了白色。", "explanation": "这里把“被面”用来指房子的外墙，被面只指被子外层的面料，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想给新被子换一朵漂亮的被面。", "corrected_sentence": "我想给新被子换一条漂亮的被面。", "error_description": "错误形式：一朵漂亮的被面；正确形式：一条漂亮的被面。被面是一长条布，应用“条”计量；“朵”用于花、云等，不能用于被面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想要这种的被面，颜色要浅一点。", "corrected_sentence": "我想要这种被面，颜色要浅一点。", "error_description": "助词错误：错误形式是“这种的被面”，正确形式是“这种被面”。“这种”修饰名词时后面不加“的”，直接接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
