INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "选举时用来写明或标明所选对象的票。", "primary_collocate": null, "pronunciation": "xuǎn piào", "ipa": "ɕɥɛn˨˩ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "每个人都有一张选票。", "target_word": "选票", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工作人员在门口发选票。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在选票上写了自己喜欢的人的名字。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举结束后，大家开始数选票。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把选票放进了投票箱。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次选举一共收到了五百张选票。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选票上有三个名字，你只能选一个。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有一张选票没有写名字，所以不能算。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在选票上画圈，选出你支持的人。", "target_word": "选票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选举那天，他拿着选票走进了学校的大厅。", "target_word": "选票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "選票", "label": "繁体"}], "register": "中性", "sense_fingerprint": "正式选举中投票人用来写明或标明所选对象的票", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选票", "is_correct": true, "explanation": "选票：选举时用来写所选对象的票，“每个人都有一张”指每位选民各得一张。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：奖状是颁给获奖者的，不是每个人都有，与“每个人都有”不符。"}, {"text": "罚单", "is_correct": false, "explanation": "语义：罚单是开给违规者的，说每个人都有一张罚单不合常理。"}, {"text": "病假条", "is_correct": false, "explanation": "语义：病假条只有生病请假的人才有，不是每个人都有一张。"}], "explanations": {"选票": "选票：选举时用来写所选对象的票，“每个人都有一张”指每位选民各得一张。", "奖状": "语义：奖状是颁给获奖者的，不是每个人都有，与“每个人都有”不符。", "罚单": "语义：罚单是开给违规者的，说每个人都有一张罚单不合常理。", "病假条": "语义：病假条只有生病请假的人才有，不是每个人都有一张。"}, "sentence_index": 0, "correct_answer": "选票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站买了一张选票。", "explanation": "这里应该用〈车票〉。选票是选举时投给候选人的票，不能买，也不能用来乘车。"}, {"text": "演出开始前，他拿出选票检查了一遍。", "explanation": "这里应该用〈门票〉。选票不用于进入场所，不能用来检票。"}, {"text": "选举那天，他把选票当作生日礼物送给了朋友。", "explanation": "选票是选举时投给候选人的票，不能当作礼物送人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选票", "is_correct": true, "explanation": "选票：选举时写所选对象的票，与“上有三个名字，你只能选一个”的选举语境相符。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单上列的是费用，不会列出可以选的人名。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片上通常只印一个人的名字，不会列出三个供选择的名字。"}, {"text": "床单", "is_correct": false, "explanation": "语义：床单是铺床用的布，上面不会列出可以选的名字，与“你只能选一个”不符。"}], "explanations": {"选票": "选票：选举时写所选对象的票，与“上有三个名字，你只能选一个”的选举语境相符。", "账单": "语义：账单上列的是费用，不会列出可以选的人名。", "名片": "语义：名片上通常只印一个人的名字，不会列出三个供选择的名字。", "床单": "语义：床单是铺床用的布，上面不会列出可以选的名字，与“你只能选一个”不符。"}, "sentence_index": 6, "correct_answer": "选票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考场上交了一张选票。", "explanation": "选票是选举时投给候选人的票，不能像考卷那样交给考官。"}, {"text": "他拿着选票上了火车。", "explanation": "这里应该用〈车票〉。选票只用于选举，不能用来乘车。"}, {"text": "他向店员要了一张选票。", "explanation": "这里应该用〈收据〉。选票不是购物凭证，不能向店员索要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次选举中，有几百个选票被认定无效。", "corrected_sentence": "这次选举中，有几百张选票被认定无效。", "error_description": "错误：选票的量词用了“个”。正确：选票是纸片，量词用“张”，写作“几百张选票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员正在清点过选票。", "corrected_sentence": "工作人员正在清点选票。", "error_description": "错误：“正在”表示动作进行中，不能与表示经历的“过”同用，句中多出了“过”。正确：去掉“过”，写作“工作人员正在清点选票。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
