INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91627, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "要嘛是说要选这一个，或者选另一个。", "primary_collocate": null, "pronunciation": "yào ma", "ipa": "iau˥˩ ma", "syllable_count": 2, "sentences": [{"text": "周末我们要嘛看电影，要嘛去爬山。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要嘛现在去，要嘛明天再去。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚饭要嘛吃米饭，要嘛吃面条，都可以。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天要嘛骑车，要嘛走路去上班。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要嘛你来我家，要嘛我去你家。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事要嘛不做，要嘛就做好。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年时我要嘛回老家，要嘛去旅行。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说要嘛今天开会，要嘛明天开会。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，我要嘛在家看书，要嘛睡觉。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要嘛听我的，要嘛自己决定。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示二选一，常成对使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91627, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要嘛", "is_correct": true, "explanation": "正确：要嘛表示二选一，与后面的“要嘛去爬山”成对使用。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，不表示二选一。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”配合，不能与“要嘛”搭配。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或并列，不表示二选一。"}], "explanations": {"要嘛": "正确：要嘛表示二选一，与后面的“要嘛去爬山”成对使用。", "然后": "语义：“然后”表示先后顺序，不表示二选一。", "不但": "搭配：“不但”要与“而且”配合，不能与“要嘛”搭配。", "而且": "语义：“而且”表示递进或并列，不表示二选一。"}, "sentence_index": 0, "correct_answer": "要嘛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很聪明，要嘛很努力。", "explanation": "这里应该用〈而且〉。要嘛表示二选一，这里是并列补充，要用“而且”。"}, {"text": "他吃完饭要嘛去上班。", "explanation": "这里应该用〈然后〉。要嘛表示二选一，这里是先后顺序，要用“然后”。"}, {"text": "今天下大雨，要嘛比赛取消了。", "explanation": "这里应该用〈所以〉。要嘛表示二选一，这里是因果关系，要用“所以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要嘛", "is_correct": true, "explanation": "正确：要嘛表示二选一，与后面的“要嘛回老家”形成选择。"}, {"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，与“要嘛……要嘛……”不搭配。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”呼应，这里没有转折。"}, {"text": "并且", "is_correct": false, "explanation": "语义：“并且”表示并列，不表示二选一。"}], "explanations": {"要嘛": "正确：要嘛表示二选一，与后面的“要嘛回老家”形成选择。", "因为": "搭配：“因为”要引出原因，与“要嘛……要嘛……”不搭配。", "虽然": "搭配：“虽然”要与“但是”呼应，这里没有转折。", "并且": "语义：“并且”表示并列，不表示二选一。"}, "sentence_index": 6, "correct_answer": "要嘛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很累，要嘛很开心。", "explanation": "这里应该用〈但是〉。要嘛表示二选一，这里是转折，要用“但是”。"}, {"text": "天气冷，要嘛我们穿了厚衣服。", "explanation": "这里应该用〈所以〉。要嘛表示二选一，这里是因果关系，要用“所以”。"}, {"text": "他一边唱歌，要嘛跳舞。", "explanation": "这里应该用〈一边〉。要嘛表示二选一，这里是同时进行，要用“一边……一边……”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上我们要嘛听歌，看剧。", "corrected_sentence": "晚上我们要嘛听歌，要嘛看剧。", "error_description": "错误：「晚上我们要嘛听歌，看剧。」漏掉了第二个“要嘛”；正确：「晚上我们要嘛听歌，要嘛看剧。」。“要嘛”表示二选一，两个选项前要成对出现，后一个选项前不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我们要吗在家休息，要嘛出去逛街。", "corrected_sentence": "周末我们要嘛在家休息，要嘛出去逛街。", "error_description": "错误：「要吗」；正确：「要嘛」。要嘛表示二选一，“要吗”是疑问语气，读音相同但意思不同，此处应写“要嘛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
