INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91628, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示选择，相当于要么。", "primary_collocate": null, "pronunciation": "yào ma", "ipa": "iau˥˩ ma", "syllable_count": 2, "sentences": [{"text": "要嘛坐地铁，要嘛打车，你自己选。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末，我要嘛加班，要嘛在家休息。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要嘛努力学习，要嘛别抱怨成绩不好。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要嘛喝茶，要嘛喝咖啡，我都行。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他要嘛不说话，要嘛一开口就笑。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题，要嘛问老师，要嘛问同学。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天晚上，我们要嘛去看电影，要嘛在家休息。", "target_word": "要嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要嘛现在出发，要嘛等雨停了再走。", "target_word": "要嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期里，她要嘛看书，要嘛画画。", "target_word": "要嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要嘛说清楚，要嘛不要说。", "target_word": "要嘛", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "连词，表示选择，相当于要么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要嘛", "is_correct": true, "explanation": "正确：要嘛表示二选一，相当于“要么”，与后面的“要嘛打车”成对使用。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或并列，不表示二选一。"}, {"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，与“要嘛……要嘛……”不搭配。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”呼应，句中没有转折。"}], "explanations": {"要嘛": "正确：要嘛表示二选一，相当于“要么”，与后面的“要嘛打车”成对使用。", "而且": "语义：“而且”表示递进或并列，不表示二选一。", "因为": "搭配：“因为”要引出原因，与“要嘛……要嘛……”不搭配。", "虽然": "搭配：“虽然”要与“但是”呼应，句中没有转折。"}, "sentence_index": 0, "correct_answer": "要嘛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气很好，要嘛很暖和。", "explanation": "这里应该用〈而且〉。要嘛表示二选一，这里是并列补充，要用“而且”。"}, {"text": "他洗完澡要嘛睡觉。", "explanation": "这里应该用〈然后〉。要嘛表示二选一，这里是先后顺序，要用“然后”。"}, {"text": "他没带伞，要嘛淋湿了。", "explanation": "这里应该用〈所以〉。要嘛表示二选一，这里是因果关系，要用“所以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要嘛", "is_correct": true, "explanation": "正确：要嘛表示二选一，与后面的“要嘛在家休息”成对使用。"}, {"text": "并且", "is_correct": false, "explanation": "语义：“并且”表示并列，不表示二选一。"}, {"text": "不管", "is_correct": false, "explanation": "搭配：“不管”要与“都”呼应，句中没有“都”。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，不表示二选一。"}], "explanations": {"要嘛": "正确：要嘛表示二选一，与后面的“要嘛在家休息”成对使用。", "并且": "语义：“并且”表示并列，不表示二选一。", "不管": "搭配：“不管”要与“都”呼应，句中没有“都”。", "所以": "语义：“所以”表示因果，不表示二选一。"}, "sentence_index": 6, "correct_answer": "要嘛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很想去，要嘛没有时间。", "explanation": "这里应该用〈但是〉。要嘛表示二选一，这里是转折，要用“但是”。"}, {"text": "他很聪明，要嘛很努力。", "explanation": "这里应该用〈还〉。要嘛表示二选一，这里是递进补充，要用“还”。"}, {"text": "无论天气好坏，我们要嘛去爬山。", "explanation": "这里应该用〈都〉。“无论……都……”表示任何情况下结论都成立；要嘛表示二选一，不能用于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次假期，我们要吗去海边，要嘛去山里。", "corrected_sentence": "这次假期，我们要嘛去海边，要嘛去山里。", "error_description": "错误：「要吗」；正确：「要嘛」。要嘛表示二选一，“要吗”是疑问语气，读音相同但意思不同，此处应写“要嘛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要是去书店，要嘛去图书馆。", "corrected_sentence": "我们要嘛去书店，要嘛去图书馆。", "error_description": "错误：「我们要是去书店」；正确：「我们要嘛去书店」。要是表示假设（“如果”），与表示二选一的要嘛不同；前后两项是并列选择，此处应用“要嘛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
