INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91629, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有黑白琴键，按下去会发出好听声音的大乐器。", "primary_collocate": null, "pronunciation": "gāng qín", "ipa": "kɑŋ˥ tɕʰin˧˥", "syllable_count": 2, "sentences": [{"text": "客厅里有一架黑色的钢琴。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹每天晚上都弹钢琴。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架钢琴的琴键又白又黑。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手放在钢琴的琴键上。", "target_word": "钢琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师正在教小朋友弹钢琴。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一架钢琴，在家练琴。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从五岁开始学钢琴。", "target_word": "钢琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他坐在钢琴前慢慢弹起一首歌。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台钢琴的声音很好听。", "target_word": "钢琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钢琴是一种很大的乐器。", "target_word": "钢琴", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "钢琴家", "label": "复合"}, {"form": "钢琴课", "label": "复合"}, {"form": "鋼琴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钢琴：有黑白琴键、声音好听的大乐器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钢琴", "is_correct": true, "explanation": "正确。“一架黑色的钢琴”中，“架”可以用于钢琴这类大型乐器。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：沙发用“张”计量，不说“一架黑色的沙发”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以放在客厅里的物品。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不是可以放在客厅里的乐器。"}], "explanations": {"钢琴": "正确。“一架黑色的钢琴”中，“架”可以用于钢琴这类大型乐器。", "沙发": "搭配：沙发用“张”计量，不说“一架黑色的沙发”。", "天气": "语义：天气不是可以放在客厅里的物品。", "窗户": "语义：窗户是建筑部件，不是可以放在客厅里的乐器。"}, "sentence_index": 0, "correct_answer": "钢琴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用钢琴吹了一首歌。", "explanation": "这里应该用〈口琴〉。钢琴靠按键和琴弦发声，不能用“吹”；吹奏的是口琴这类乐器。"}, {"text": "这把刀是用钢琴做的。", "explanation": "这里应该用〈钢〉。“钢琴”是乐器，做刀的金属材料要用“钢”。"}, {"text": "他用钢琴写字。", "explanation": "这里应该用〈钢笔〉。钢琴是乐器，写字用的是钢笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢琴", "is_correct": true, "explanation": "正确。“学钢琴”指学习弹奏钢琴，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“学”的对象是技能或知识，“桌子”不是可以学习的内容。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，不能用“学”来搭配。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“学”后接技能或知识，不接“房子”这类建筑。"}], "explanations": {"钢琴": "正确。“学钢琴”指学习弹奏钢琴，符合语境。", "桌子": "语义：“学”的对象是技能或知识，“桌子”不是可以学习的内容。", "河流": "语义：河流是自然事物，不能用“学”来搭配。", "房子": "搭配：“学”后接技能或知识，不接“房子”这类建筑。"}, "sentence_index": 6, "correct_answer": "钢琴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是很有名的钢琴。", "explanation": "这里应该用〈钢琴家〉。“钢琴”指乐器，指演奏钢琴的人要用“钢琴家”。"}, {"text": "电脑的钢琴坏了。", "explanation": "这里应该用〈键盘〉。钢琴是乐器，电脑上输入文字的按键装置是“键盘”。"}, {"text": "钢琴有五个成员。", "explanation": "这里应该用〈乐队〉。钢琴是乐器，不是团体，“五个成员”指的是乐队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这只钢琴搬进了客厅。", "corrected_sentence": "我把这架钢琴搬进了客厅。", "error_description": "量词错误：“只”多用于动物等，钢琴这类大型乐器应用“架”，应说“这架钢琴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他弹钢琴弹很好。", "corrected_sentence": "他弹钢琴弹得很好。", "error_description": "程度补语要用“得”连接，应说“弹得很好”，不能说“弹很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
