INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通过按键敲击琴弦发音的大型键盘乐器。", "primary_collocate": null, "pronunciation": "gāng qín", "ipa": "kɑŋ˥ tɕʰin˧˥", "syllable_count": 2, "sentences": [{"text": "钢琴里有很多琴弦。", "target_word": "钢琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "按下琴键，小锤会敲到琴弦，钢琴就响了。", "target_word": "钢琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴有键盘，小提琴没有键盘。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "调琴师来我家给钢琴调音。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂每年做几百架钢琴。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钢琴的琴盖打开后，能看到里面的琴弦。", "target_word": "钢琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹钢琴时，脚要踩踏板。", "target_word": "钢琴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "演奏钢琴时，手指要轻轻按下琴键。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校音乐室里有两架旧钢琴。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台钢琴用了二十年，声音还是很准。", "target_word": "钢琴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "钢琴家", "label": "复合"}, {"form": "钢琴课", "label": "复合"}, {"form": "鋼琴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "钢琴：按键敲击琴弦发音的大型键盘乐器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钢琴", "is_correct": true, "explanation": "正确。钢琴内部有琴弦，“钢琴里有很多琴弦”符合事实。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里放的是食物，不会有琴弦。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，里面没有琴弦。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是户外场所，里面没有琴弦。"}], "explanations": {"钢琴": "正确。钢琴内部有琴弦，“钢琴里有很多琴弦”符合事实。", "冰箱": "语义：冰箱里放的是食物，不会有琴弦。", "厨房": "语义：厨房是做饭的房间，里面没有琴弦。", "花园": "语义：花园是户外场所，里面没有琴弦。"}, "sentence_index": 0, "correct_answer": "钢琴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天用钢琴打字。", "explanation": "这里应该用〈键盘〉。打字要用键盘输入，钢琴是乐器，不能用来打字。"}, {"text": "钢琴很长，可以用来搭架子。", "explanation": "这里应该用〈钢管〉。钢琴是乐器，搭架子用的是钢管。"}, {"text": "妈妈每天用钢琴做饭。", "explanation": "这里应该用〈锅〉。做饭要用锅，钢琴是乐器，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢琴", "is_correct": true, "explanation": "正确。“弹钢琴时，脚要踩踏板”符合事实。"}, {"text": "琵琶", "is_correct": false, "explanation": "语义：琵琶是弹拨乐器，没有踏板，“脚要踩踏板”说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是乐器，“脚要踩踏板”只适用于乐器，说不通。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是用手弹奏的乐器，也没有踏板。"}], "explanations": {"钢琴": "正确。“弹钢琴时，脚要踩踏板”符合事实。", "琵琶": "语义：琵琶是弹拨乐器，没有踏板，“脚要踩踏板”说不通。", "歌曲": "语义：歌曲不是乐器，“脚要踩踏板”只适用于乐器，说不通。", "电视": "语义：电视不是用手弹奏的乐器，也没有踏板。"}, "sentence_index": 6, "correct_answer": "钢琴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钢琴写了很多歌。", "explanation": "这里应该用〈作曲家〉。钢琴是乐器，写歌的是作曲家，钢琴不能写歌。"}, {"text": "他戴着钢琴看书。", "explanation": "这里应该用〈眼镜〉。钢琴是乐器，戴在脸上的是眼镜。"}, {"text": "今天的钢琴很冷，出门要多穿衣服。", "explanation": "这里应该用〈天气〉。钢琴是乐器，说今天冷不冷要用“天气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这只钢琴搬到了楼上。", "corrected_sentence": "我把这架钢琴搬到了楼上。", "error_description": "量词错误：“只”多用于动物等，钢琴这类大型乐器应用“架”，应说“这架钢琴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天练钢琴练很累。", "corrected_sentence": "她每天练钢琴练得很累。", "error_description": "程度补语要用“得”连接，应说“练得很累”，不能说“练很累”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91631, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91631, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91631, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规模经济是东西做得越多，每一个就越便宜。", "primary_collocate": null, "pronunciation": "guī mó jīng jì", "ipa": "kʷei˥ mwo˧˥ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "工厂做得越多，成本越低，这就是规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司买东西便宜，是因为有规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有规模经济，大超市的价格比小店低。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机做得越多，每一部就越便宜，这是规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包做得多，每个更便宜，就是规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂靠规模经济降低了价格。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店没有规模经济，所以东西比较贵。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我讲了什么是规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用做衣服的例子说明规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多生产一些，就能得到规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "規模經濟", "label": "繁体"}, {"form": "规模经济效应", "label": "复合"}], "register": "中性", "sense_fingerprint": "规模经济：东西做得越多，每一个越便宜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规模经济", "is_correct": true, "explanation": "正确：工厂做得越多、成本越低，正是规模经济的含义。"}, {"text": "通货膨胀", "is_correct": false, "explanation": "语义：通货膨胀指物价普遍上涨，与“成本越低”的描述相反。"}, {"text": "价格歧视", "is_correct": false, "explanation": "语义：价格歧视指对不同顾客定不同价格，与“做得越多、成本越低”无关。"}, {"text": "边际效用", "is_correct": false, "explanation": "语义：边际效用指多消费一单位带来的满足感，与成本下降无关，句意不通。"}], "explanations": {"规模经济": "正确：工厂做得越多、成本越低，正是规模经济的含义。", "通货膨胀": "语义：通货膨胀指物价普遍上涨，与“成本越低”的描述相反。", "价格歧视": "语义：价格歧视指对不同顾客定不同价格，与“做得越多、成本越低”无关。", "边际效用": "语义：边际效用指多消费一单位带来的满足感，与成本下降无关，句意不通。"}, "sentence_index": 0, "correct_answer": "规模经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的规模经济今年增长了百分之五。", "explanation": "这里应该用“国内生产总值”。规模经济指单位成本下降带来的效益，不是可以增长的总量。"}, {"text": "这家工厂的规模经济是三百个工人。", "explanation": "这里应该用“员工人数”。规模经济指做得越多每个越便宜的好处，不是工人的数量。"}, {"text": "这家工厂的规模经济降低了三成。", "explanation": "这里应该用“成本”。规模经济是效益，不是可以降低的数量，降低的是单位成本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规模经济", "is_correct": true, "explanation": "正确：小店没有规模经济，成本高，所以东西比较贵，符合句意。"}, {"text": "税收", "is_correct": false, "explanation": "语义：没有税收本应使东西更便宜，与“比较贵”的因果关系矛盾。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入的多少不是东西贵的直接原因，句中把“没有收入”当作涨价理由，语义不通。"}, {"text": "机会成本", "is_correct": false, "explanation": "语义：机会成本指放弃其它选择的代价，句中“没有”它就使东西更贵，因果不通。"}], "explanations": {"规模经济": "正确：小店没有规模经济，成本高，所以东西比较贵，符合句意。", "税收": "语义：没有税收本应使东西更便宜，与“比较贵”的因果关系矛盾。", "收入": "语义：收入的多少不是东西贵的直接原因，句中把“没有收入”当作涨价理由，语义不通。", "机会成本": "语义：机会成本指放弃其它选择的代价，句中“没有”它就使东西更贵，因果不通。"}, "sentence_index": 6, "correct_answer": "规模经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府给小企业发了规模经济。", "explanation": "这里应该用“补贴”。规模经济是企业生产的效益，不能像补贴那样发放。"}, {"text": "这家店买了一杯规模经济。", "explanation": "这里不能用“杯”，也不能说“买”。“杯”用于饮品等实物，规模经济是抽象的经济效益，不是能买到的商品。"}, {"text": "这家店今天有八折的规模经济。", "explanation": "这里应该用“折扣”。规模经济不是打折优惠，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂有一只规模经济，所以成本很低。", "corrected_sentence": "这家工厂有规模经济，所以成本很低。", "error_description": "量词错误：“规模经济”是抽象名词，不能用“只”（“只”多用于动物），一般直接说“有规模经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大量生产能让工厂形成一条规模经济。", "corrected_sentence": "大量生产能让工厂形成规模经济。", "error_description": "量词错误：“规模经济”是抽象名词，不能用“条”（“条”多指细长的东西），应直接说“形成规模经济”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91632, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91632, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生产规模扩大使单位产品成本下降而带来的经济效益。", "primary_collocate": null, "pronunciation": "guī mó jīng jì", "ipa": "kʷei˥ mwo˧˥ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "生产规模扩大后，企业获得了规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规模经济能使单位产品的成本下降。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家汽车企业通过扩大产量实现了规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规模经济是大型企业的一个重要优势。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产量太低的工厂很难形成规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家常用规模经济解释大企业的成功。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电商平台靠规模经济降低物流成本。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场太小，企业就无法发挥规模经济的作用。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合并以后，两家公司取得了规模经济。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规模经济带来的利润让企业更有竞争力。", "target_word": "规模经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "規模經濟", "label": "繁体"}, {"form": "规模经济效应", "label": "复合"}], "register": "书面", "sense_fingerprint": "规模经济：生产规模扩大使单位成本下降带来的效益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规模经济", "is_correct": true, "explanation": "正确：生产规模扩大后，企业获得的正是规模经济，符合句意。"}, {"text": "失业", "is_correct": false, "explanation": "语义：失业指劳动者失去工作，企业不能“获得”失业，与句意不符。"}, {"text": "竞争", "is_correct": false, "explanation": "搭配：“获得”一般搭配利益、优势等，“获得竞争”不成立。"}, {"text": "通货膨胀", "is_correct": false, "explanation": "语义：通货膨胀是物价普遍上涨的现象，不是企业可以获得的好处，与句意不符。"}], "explanations": {"规模经济": "正确：生产规模扩大后，企业获得的正是规模经济，符合句意。", "失业": "语义：失业指劳动者失去工作，企业不能“获得”失业，与句意不符。", "竞争": "搭配：“获得”一般搭配利益、优势等，“获得竞争”不成立。", "通货膨胀": "语义：通货膨胀是物价普遍上涨的现象，不是企业可以获得的好处，与句意不符。"}, "sentence_index": 0, "correct_answer": "规模经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "企业必须按时缴纳规模经济。", "explanation": "这里应该用“税收”。规模经济是效益，不能“缴纳”，缴纳的是税收。"}, {"text": "企业在城外建了一座规模经济。", "explanation": "这里不能用“座”。规模经济是抽象的经济效益，不是建筑，不能用量词“座”计量。"}, {"text": "这家公司雇用了大量规模经济。", "explanation": "这里应该用“劳动力”。规模经济不是人，不能被雇用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规模经济", "is_correct": true, "explanation": "正确：电商平台靠规模经济降低成本，是常见的经济学解释，符合句意。"}, {"text": "广告", "is_correct": false, "explanation": "语义：广告不能直接降低物流成本，句中“靠”后应是降低成本的手段。"}, {"text": "信用卡", "is_correct": false, "explanation": "语义：信用卡是支付工具，与降低物流成本无关。"}, {"text": "社会学", "is_correct": false, "explanation": "语义：社会学是学科名称，不能作为降低成本的手段，句意不通。"}], "explanations": {"规模经济": "正确：电商平台靠规模经济降低成本，是常见的经济学解释，符合句意。", "广告": "语义：广告不能直接降低物流成本，句中“靠”后应是降低成本的手段。", "信用卡": "语义：信用卡是支付工具，与降低物流成本无关。", "社会学": "语义：社会学是学科名称，不能作为降低成本的手段，句意不通。"}, "sentence_index": 6, "correct_answer": "规模经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "企业买了一瓶规模经济。", "explanation": "这里不能用“瓶”，也不能说“买”。“瓶”用于装在瓶中的实物，规模经济是抽象的经济效益，不是能买到的商品。"}, {"text": "企业因为违规，交了一笔规模经济。", "explanation": "这里应该用“罚款”。规模经济是效益，不能“交”，交的是罚款。"}, {"text": "这家工厂的规模经济有三万平方米。", "explanation": "这里应该用“面积”。规模经济是生产效益，不是有面积的空间，不能用平方米计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家电器厂的产量很大，所以形成了一座规模经济。", "corrected_sentence": "这家电器厂的产量很大，所以形成了规模经济。", "error_description": "量词错误：“规模经济”是抽象名词，不能用“座”（“座”用于建筑、山等），应直接说“形成了规模经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家连锁店把规模经济降低了进货成本。", "corrected_sentence": "这家连锁店靠规模经济降低了进货成本。", "error_description": "介词错误：表示原因的“规模经济”应由“靠”引出，用“把”会使“规模经济”被当作“降低”的受事，句子不通。正确说法是“靠规模经济降低了进货成本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
