INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91633, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用机器把会动的画面留下来。", "primary_collocate": null, "pronunciation": "lù xiàng", "ipa": "lu˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你可以用这台机器录像。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把摄像机放在桌子上开始录像。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把摄像机架在院子里录像。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个相机能录像，也能拍照。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，不能录像。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸想给我们的生日聚会录像。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在花园里玩，妈妈在旁边录像。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给这只猫录像，留个纪念。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会用这台照相机录像吗？", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先按红色的键，然后就开始录像。", "target_word": "录像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "录像机", "label": "复合"}, {"form": "录过像", "label": "体标"}, {"form": "录了像", "label": "体标"}, {"form": "錄像", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用机器把会动的画面留下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6953d5e5-dcdc-42fa-bb07-a85678b32b99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91633, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "录像", "is_correct": true, "explanation": "正确。用这台机器录下画面，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步不需要用机器，“用这台机器散步”句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：机器不能用来吃饭，句意不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：机器不能用来跳舞，与句子的意思无关。"}], "explanations": {"录像": "正确。用这台机器录下画面，符合句意。", "散步": "语义：散步不需要用机器，“用这台机器散步”句意不通。", "吃饭": "语义：机器不能用来吃饭，句意不通。", "跳舞": "语义：机器不能用来跳舞，与句子的意思无关。"}, "sentence_index": 0, "correct_answer": "录像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片是用相机录像的。", "explanation": "这里应该用〈拍〉。照片是静止的画面，要用“拍”；“录像”记录的是会动的画面。"}, {"text": "这支录音笔能录像，还能存文件。", "explanation": "这里应该用〈录音〉。录音笔只能记录声音，不能记录画面。"}, {"text": "这台扫描仪能录像，还能复印。", "explanation": "这里应该用〈扫描〉。扫描仪读取纸上的内容，不能录下会动的画面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录像", "is_correct": true, "explanation": "正确。妈妈在旁边录像，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：妈妈在旁边考试，与孩子在花园里玩的场景不符。"}, {"text": "做手术", "is_correct": false, "explanation": "语义：妈妈在旁边做手术，与孩子在花园里玩耍的场景明显不符。"}, {"text": "打仗", "is_correct": false, "explanation": "语义：妈妈在旁边打仗，与孩子玩耍的场景明显矛盾。"}], "explanations": {"录像": "正确。妈妈在旁边录像，符合句意。", "考试": "语义：妈妈在旁边考试，与孩子在花园里玩的场景不符。", "做手术": "语义：妈妈在旁边做手术，与孩子在花园里玩耍的场景明显不符。", "打仗": "语义：妈妈在旁边打仗，与孩子玩耍的场景明显矛盾。"}, "sentence_index": 6, "correct_answer": "录像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐在窗前录像，画出了一幅山水画。", "explanation": "这里应该用〈画〉。画山水要用“画”，“录像”是用机器留下会动的画面，不能用来作画。"}, {"text": "他坐在电脑前录像，写了一篇文章。", "explanation": "这里应该用〈打字〉。用电脑写文章是打字，“录像”是用机器记录会动的画面，不能用来输入文字。"}, {"text": "他把考试题目一道道录像下来，整理成了笔记。", "explanation": "这里应该用〈抄〉。把题目一道道记下来要用“抄”，“录像”是用机器留下画面，不能用来记文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把摄像机放好，开始录像机。", "corrected_sentence": "他把摄像机放好，开始录像。", "error_description": "错误：“开始录像机”，正确：“开始录像”。“录像机”是设备名词，不能表示“录”这个动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个相机录像得很清楚。", "corrected_sentence": "这个相机录像录得很清楚。", "error_description": "错误：“录像得很清楚”，正确：“录像录得很清楚”。动词后带“得”的补语时，要重复动词“录”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91635, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生疏", "is_correct": true, "explanation": "反义：“生疏”指不熟悉、不亲近，与“亲切”所表达的熟悉温暖相对。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说光线或颜色，与“亲切”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”说质地不平滑，与“亲切”没有反义关系。"}, {"text": "巨大", "is_correct": false, "explanation": "“巨大”形容体积或程度，与“亲切”不构成反义。"}], "correct_answer": "生疏", "explanations": {"生疏": "反义：“生疏”指不熟悉、不亲近，与“亲切”所表达的熟悉温暖相对。", "明亮": "“明亮”说光线或颜色，与“亲切”没有反义关系。", "粗糙": "“粗糙”说质地不平滑，与“亲切”没有反义关系。", "巨大": "“巨大”形容体积或程度，与“亲切”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91635, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生疏", "is_correct": true, "explanation": "反义：“生疏”指不熟悉、不亲近，与“亲切”所表达的熟悉温暖相对。"}, {"text": "宽阔", "is_correct": false, "explanation": "“宽阔”说空间大，与“亲切”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容地势，与“亲切”不构成反义。"}, {"text": "新鲜", "is_correct": false, "explanation": "“新鲜”说事物刚出现或刚生产，与“亲切”没有反义关系。"}], "correct_answer": "生疏", "explanations": {"生疏": "反义：“生疏”指不熟悉、不亲近，与“亲切”所表达的熟悉温暖相对。", "宽阔": "“宽阔”说空间大，与“亲切”没有反义关系。", "陡峭": "“陡峭”形容地势，与“亲切”不构成反义。", "新鲜": "“新鲜”说事物刚出现或刚生产，与“亲切”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91635, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "亲切是让人觉得温暖，像家人一样。", "primary_collocate": null, "pronunciation": "qīn qiè", "ipa": "tɕʰin˥˥ tɕʰjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "在外地听到家乡话，我觉得很亲切。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小饭馆让人觉得亲切，像回到了家。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶做的菜味道很亲切。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老房子的样子让我感到亲切。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们叫我小名，听起来特别亲切。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的人像一家人，大家都觉得很亲切。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路过那家熟悉的小店，我心里一暖，觉得很亲切。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的口音很亲切，像我老家的人。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外看见中国字，真亲切。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首老歌很亲切，让我想起了家。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲切地", "label": "状语形式"}, {"form": "亲切感", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物或声音让人感到温暖熟悉、像家人一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲切", "is_correct": true, "explanation": "正确。“在外地听到家乡话，我觉得很亲切”表达听到乡音后的温暖感受。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，不能表达听到家乡话的感受。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”说的是缺少水分，不能表达这种温暖的感受。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音乱，与“觉得很”后面的温暖感受不一致。"}], "explanations": {"亲切": "正确。“在外地听到家乡话，我觉得很亲切”表达听到乡音后的温暖感受。", "高大": "体貌：“高大”形容身材或外形，不能表达听到家乡话的感受。", "干燥": "语义：“干燥”说的是缺少水分，不能表达这种温暖的感受。", "嘈杂": "语义：“嘈杂”形容声音乱，与“觉得很”后面的温暖感受不一致。"}, "sentence_index": 0, "correct_answer": "亲切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里的山路很亲切，别一个人走。", "explanation": "这里应该用〈危险〉。“亲切”表示让人觉得温暖，像家人一样；夜里的山路让人害怕，要说“危险”。"}, {"text": "隔壁的音乐亲切得让人睡不着。", "explanation": "这里应该用〈吵闹〉。“亲切”表示温暖、熟悉，不能形容吵得人睡不着的声音，这里要说“吵闹”。"}, {"text": "考试前，他的心跳得很快，亲切得发抖。", "explanation": "这里应该用〈紧张〉。“亲切”表示温暖、像家人一样，不能形容考前紧张得发抖的心理状态，这里要说“紧张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲切", "is_correct": true, "explanation": "正确。前文说“熟悉的小店”、“心里一暖”，所以此处是“亲切”。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：前文说“熟悉的小店”，“陌生”与之矛盾。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“我心里一暖”与“冰冷”的感受相反。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“觉得很沉重”说的是压力或负担，与“心里一暖”的感受不符。"}], "explanations": {"亲切": "正确。前文说“熟悉的小店”、“心里一暖”，所以此处是“亲切”。", "陌生": "语义：前文说“熟悉的小店”，“陌生”与之矛盾。", "冰冷": "语义：“我心里一暖”与“冰冷”的感受相反。", "沉重": "搭配：“觉得很沉重”说的是压力或负担，与“心里一暖”的感受不符。"}, "sentence_index": 6, "correct_answer": "亲切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子亲切得让人恶心。", "explanation": "这里应该用〈肮脏〉。“亲切”表示温暖、像家人一样，不能形容脏得让人恶心的屋子，这里要说“肮脏”。"}, {"text": "这两个部门一直很亲切，互相不配合。", "explanation": "这里应该用〈对立〉。“亲切”表示温暖、融洽，两个部门互相不配合时要说“对立”，不能用“亲切”。"}, {"text": "深夜的古堡亲切得吓人。", "explanation": "这里应该用〈阴森〉。“亲切”表示温暖、让人安心，深夜的古堡让人害怕时要说“阴森”，不能说“亲切得吓人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老城让我感到很亲切地。", "corrected_sentence": "这座老城让我感到很亲切。", "error_description": "助词错误：句末的“亲切”作谓语时不加“地”，应说“很亲切”；“地”要用在动词前作状语，不能用在句末，写成“很亲切地”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我觉得这个地方很亲切得。", "corrected_sentence": "我觉得这个地方很亲切。", "error_description": "助词错误：“亲切”在句末作谓语，后面不能加“得”。“得”后面要接补语，比如“亲切得像家一样”。这里应去掉“得”，说“很亲切”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91636, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "反义：“冷淡”指对人态度冷漠、不热情，与“亲切”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说光线或颜色，与“亲切”的态度义没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”说质地不平滑，与“亲切”没有反义关系。"}, {"text": "巨大", "is_correct": false, "explanation": "“巨大”形容体积或程度，与“亲切”不构成反义。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "反义：“冷淡”指对人态度冷漠、不热情，与“亲切”相对。", "明亮": "“明亮”说光线或颜色，与“亲切”的态度义没有反义关系。", "粗糙": "“粗糙”说质地不平滑，与“亲切”没有反义关系。", "巨大": "“巨大”形容体积或程度，与“亲切”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
