INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91636, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容对人热情关切，使人感到亲近。", "primary_collocate": null, "pronunciation": "qīn qiè", "ipa": "tɕʰin˥˥ tɕʰjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "王老师对学生很亲切。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的话听起来很亲切。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着跟我打招呼，样子十分亲切。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的服务员都很亲切，客人很满意。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老校长亲切得像自己的爷爷。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话的声音很亲切，我一点儿也不怕。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们对新来的同学非常亲切。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的态度不冷淡，很亲切。", "target_word": "亲切", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说这位经理很亲切，没有架子。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到她亲切的声音，我心里暖和多了。", "target_word": "亲切", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲切地", "label": "状语形式"}, {"form": "亲切感", "label": "复合"}], "register": "中性", "sense_fingerprint": "人的态度热情关切、让人感到亲近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲切", "is_correct": true, "explanation": "正确。“王老师对学生很亲切”指老师对学生态度热情关切。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不用来形容对学生的态度。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”说颜色，与对学生的态度无关。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”说颜色或光线，不能形容一个人的态度。"}], "explanations": {"亲切": "正确。“王老师对学生很亲切”指老师对学生态度热情关切。", "响亮": "搭配：“响亮”形容声音，不用来形容对学生的态度。", "雪白": "语义：“雪白”说颜色，与对学生的态度无关。", "漆黑": "语义：“漆黑”说颜色或光线，不能形容一个人的态度。"}, "sentence_index": 0, "correct_answer": "亲切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "婚礼上，新郎亲切地吻了新娘。", "explanation": "这里应该用〈亲热〉。“亲切”形容对人态度和善，亲吻这样亲密的动作要用“亲热”，不能用“亲切”。"}, {"text": "这个月的房租很亲切，大家都很高兴。", "explanation": "这里应该用〈便宜〉。“亲切”形容人的态度，不能用来形容价格；房租低要说“便宜”。"}, {"text": "强盗亲切地抢走了我的包。", "explanation": "这里应该用〈凶狠〉。“亲切”形容态度和善，不能用来形容抢劫这种恶劣行为；这里要说“凶狠地抢走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲切", "is_correct": true, "explanation": "正确。“邻居们对新来的同学非常亲切”指邻居对同学态度热情。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，不用来形容对人的态度。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多用于心情、负担，“对同学非常沉重”说不通。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”说的是缺少水分，与人际态度无关。"}], "explanations": {"亲切": "正确。“邻居们对新来的同学非常亲切”指邻居对同学态度热情。", "高大": "体貌：“高大”形容身材或外形，不用来形容对人的态度。", "沉重": "搭配：“沉重”多用于心情、负担，“对同学非常沉重”说不通。", "干燥": "语义：“干燥”说的是缺少水分，与人际态度无关。"}, "sentence_index": 6, "correct_answer": "亲切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试很亲切，大家都没有紧张。", "explanation": "这里应该用〈容易〉。“亲切”形容人的态度，不能用来形容考试的难度；考试不难要说“容易”。"}, {"text": "两国的货运一直很亲切，每天都有船来往。", "explanation": "这里应该用〈顺畅〉。“亲切”形容人的态度或让人温暖的感觉，不能用来形容货运的状况；货运通畅要说“顺畅”。"}, {"text": "这种药的药性很亲切，吃了也不伤胃。", "explanation": "这里应该用〈温和〉。“亲切”形容人的态度或让人温暖的感觉，药性是事物的性质，要用“温和”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老奶奶待人很亲切地。", "corrected_sentence": "那位老奶奶待人很亲切。", "error_description": "助词错误：句末的“亲切”作谓语时不加“地”，应说“待人很亲切”；“地”要用在动词前作状语，不能用在句末，写成“很亲切地”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一张亲切脸。", "corrected_sentence": "她有一张亲切的脸。", "error_description": "漏字：“亲切”修饰名词“脸”时要加“的”，应说“亲切的脸”，不能说“亲切脸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留用", "is_correct": true, "explanation": "反义：「开除」让人离开，「留用」让人继续留在原单位。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：「研究」指探讨问题，与「开除」意思无关。"}, {"text": "出版", "is_correct": false, "explanation": "无反义关系：「出版」指把作品印刷发行，与「开除」无关。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：「散步」指随意走动，与「开除」无关。"}], "correct_answer": "留用", "explanations": {"留用": "反义：「开除」让人离开，「留用」让人继续留在原单位。", "研究": "无反义关系：「研究」指探讨问题，与「开除」意思无关。", "出版": "无反义关系：「出版」指把作品印刷发行，与「开除」无关。", "散步": "无反义关系：「散步」指随意走动，与「开除」无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "录用", "is_correct": true, "explanation": "反义：「开除」是让人离开，「录用」是接收人员入职，意思相反。"}, {"text": "报告", "is_correct": false, "explanation": "无反义关系：「报告」指陈述情况，与「开除」无关。"}, {"text": "游览", "is_correct": false, "explanation": "无反义关系：「游览」指参观风景，与「开除」无关。"}, {"text": "咨询", "is_correct": false, "explanation": "无反义关系：「咨询」指请人提供意见，与「开除」无关。"}], "correct_answer": "录用", "explanations": {"录用": "反义：「开除」是让人离开，「录用」是接收人员入职，意思相反。", "报告": "无反义关系：「报告」指陈述情况，与「开除」无关。", "游览": "无反义关系：「游览」指参观风景，与「开除」无关。", "咨询": "无反义关系：「咨询」指请人提供意见，与「开除」无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让他再留在学校或工作的地方。", "primary_collocate": null, "pronunciation": "kāi chú", "ipa": "kʰaɪ˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "小王常常迟到，老板把他开除了。", "target_word": "开除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在考试时作弊，学校开除了他。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司说，再迟到就要开除你。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师告诉我，那个学生打了人，学校决定开除他。", "target_word": "开除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是不来上班，老板就开除了他。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂开除了三个不好好工作的人。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再这样做，老板会开除你的。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕老板开除他，所以天天早到。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家饭店昨天开除了一个服务员。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板很生气，他说要马上开除小李。", "target_word": "开除", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开除了", "label": "完成体"}, {"form": "开除过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "老板或学校不再让人留在原来的学校或工作单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa83287-1e2b-4500-b69a-3fd58334cdca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开除", "is_correct": true, "explanation": "正确。「开除」指因犯错误而不让他留在单位，与「常常迟到」的语境相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」是称赞，与「常常迟到」的行为相矛盾。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：「讨论」的对象是问题或方案，不说「讨论他」。"}, {"text": "批准", "is_correct": false, "explanation": "语义：「批准」是同意某事，与老板因迟到而处理员工的语境不符。"}], "explanations": {"开除": "正确。「开除」指因犯错误而不让他留在单位，与「常常迟到」的语境相符。", "表扬": "语义：「表扬」是称赞，与「常常迟到」的行为相矛盾。", "讨论": "搭配：「讨论」的对象是问题或方案，不说「讨论他」。", "批准": "语义：「批准」是同意某事，与老板因迟到而处理员工的语境不符。"}, "sentence_index": 0, "correct_answer": "开除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用肥皂水可以开除衣服上的油渍。", "explanation": "这里应该用〈去除〉。开除只用于人及其身份（学籍、职务等），去除用于油渍、污渍等。"}, {"text": "学校今年开除了三百多份申请。", "explanation": "这里应该用〈受理〉。「开除」的对象是人或其身份，不能用于申请。"}, {"text": "公司因为业务调整，开除了一批合同。", "explanation": "这里应该用〈终止〉。「开除」的对象是人或其身份，不能用于合同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开除", "is_correct": true, "explanation": "正确。「你再这样做，老板会……你的」是威胁语气，「开除」符合这一语境。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：「奖励」是对好行为的回报，与带威胁语气的句子不符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：「感谢」表示对帮助的回应，与「会……你的」的威胁语气矛盾。"}, {"text": "嘉奖", "is_correct": false, "explanation": "语域：「嘉奖」是书面语的正式表彰，口语的威胁句中不用。"}], "explanations": {"开除": "正确。「你再这样做，老板会……你的」是威胁语气，「开除」符合这一语境。", "奖励": "语义：「奖励」是对好行为的回报，与带威胁语气的句子不符。", "感谢": "语义：「感谢」表示对帮助的回应，与「会……你的」的威胁语气矛盾。", "嘉奖": "语域：「嘉奖」是书面语的正式表彰，口语的威胁句中不用。"}, "sentence_index": 6, "correct_answer": "开除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我觉得工资太低，就开除了这家公司。", "explanation": "这里应该用〈辞职〉。「开除」的施事是学校或单位，对象是人；自己离开工作要说辞职。"}, {"text": "老板开除了我的意见。", "explanation": "这里应该用〈采纳〉。「开除」的对象是人或其身份，不能用于意见。"}, {"text": "公司决定开除这个部门。", "explanation": "这里应该用〈解散〉。「开除」的对象是人，不能用于部门或团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把那名迟到的员工开除。", "corrected_sentence": "公司把那名迟到的员工开除了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「把那名迟到的员工开除了」，只说「开除」句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把那个乱扔垃圾的工人开除。", "corrected_sentence": "工厂把那个乱扔垃圾的工人开除了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「把那个乱扔垃圾的工人开除了」，只说「开除」句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
