INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91639, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "赛车是用来比谁跑得快的车。", "primary_collocate": null, "pronunciation": "sài chē", "ipa": "sai˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "赛车跑得比普通汽车快得多。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥有一辆蓝色的赛车。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆赛车第一个到了终点。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开着赛车，比谁先到终点。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种车是赛车，不是家里用的车。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛车的速度可以超过每小时三百公里。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带我去看了一辆真正的赛车。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，所有的赛车一起出发。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛车的座位很低，坐进去不太舒服。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆赛车有红色的车身和黑色的轮子。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "賽車", "label": "繁体"}, {"form": "赛车手", "label": "复合"}], "register": "中性", "sense_fingerprint": "赛车：用来比谁跑得快的车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赛车", "is_correct": true, "explanation": "正确：赛车是用来比谁跑得快的车，与“跑得比普通汽车快得多”相符。"}, {"text": "自行车", "is_correct": false, "explanation": "语义：自行车的速度远低于汽车，与“快得多”矛盾。"}, {"text": "轮船", "is_correct": false, "explanation": "语义：轮船速度远低于汽车，说它“跑得比普通汽车快得多”与事实相反。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象的速度远不及汽车，句中说它“快得多”，与事实矛盾。"}], "explanations": {"赛车": "正确：赛车是用来比谁跑得快的车，与“跑得比普通汽车快得多”相符。", "自行车": "语义：自行车的速度远低于汽车，与“快得多”矛盾。", "轮船": "语义：轮船速度远低于汽车，说它“跑得比普通汽车快得多”与事实相反。", "大象": "语义：大象的速度远不及汽车，句中说它“快得多”，与事实矛盾。"}, "sentence_index": 0, "correct_answer": "赛车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐是一名赛车，周末常去参加比赛。", "explanation": "这里应该用“赛车手”。“赛车”指车，指驾驶赛车的人要说“赛车手”，不能直接用来指人。"}, {"text": "他刚修好一只赛车。", "explanation": "这里不应使用“只”。赛车是车辆，量词应用“辆”，“只”多用于动物或成对的东西。"}, {"text": "他们在湖上划赛车，比谁先到岸边。", "explanation": "这里应该用“赛艇”。赛车是陆上的车，不能用“划”，水上比赛要说赛艇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赛车", "is_correct": true, "explanation": "正确：爸爸带我去看的是真正的赛车，符合句意。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：量词“辆”只用于车辆，不能数人，“一辆歌手”不成立。"}, {"text": "玩具", "is_correct": false, "explanation": "量词：“辆”不用来数玩具，不能说“一辆玩具”；而且句子说的是一辆真正的车。"}, {"text": "摩天轮", "is_correct": false, "explanation": "量词：摩天轮用“座”，不用“辆”，且不是车辆。"}], "explanations": {"赛车": "正确：爸爸带我去看的是真正的赛车，符合句意。", "歌手": "搭配：量词“辆”只用于车辆，不能数人，“一辆歌手”不成立。", "玩具": "量词：“辆”不用来数玩具，不能说“一辆玩具”；而且句子说的是一辆真正的车。", "摩天轮": "量词：摩天轮用“座”，不用“辆”，且不是车辆。"}, "sentence_index": 6, "correct_answer": "赛车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的叔叔是一名赛车，经常在赛场上比赛。", "explanation": "这里应该用“赛车手”。“赛车”指车，指驾驶赛车的人要说“赛车手”。"}, {"text": "这座赛车有红色的车身和黑色的轮子。", "explanation": "这里不能用“座”。“座”多用于山、桥、楼房等，车辆应用“辆”。"}, {"text": "这张赛车的车身很亮，大家都在拍照。", "explanation": "这里不能用“张”。“张”用于纸、床等平面的东西，车辆应用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友昨天买了一只赛车。", "corrected_sentence": "我的朋友昨天买了一辆赛车。", "error_description": "量词错误：“赛车”是车辆，应用量词“辆”，不能说“一只”。正确说法是“一辆赛车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想在比赛里开一把赛车。", "corrected_sentence": "我想在比赛里开一辆赛车。", "error_description": "量词错误：“赛车”是车辆，应用量词“辆”，不能说“一把”（“把”用于有把手的东西）。正确说法是“一辆赛车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
