INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门用于竞速比赛的汽车或摩托车。", "primary_collocate": null, "pronunciation": "sài chē", "ipa": "sai˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "他开着一辆红色的赛车，速度特别快。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆赛车的发动机动力很强。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爸爸带我去看一辆漂亮的赛车。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车队正在检查赛车的轮胎。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆赛车只有一个座位，不能带朋友。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，工程师把赛车修好了。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛车的轮胎比普通汽车的宽得多。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就梦想开赛车，现在终于成功了。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路太窄，赛车开不进去。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一辆辆赛车冲过了终点，大家都在鼓掌。", "target_word": "赛车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "賽車", "label": "繁体"}, {"form": "赛车手", "label": "复合"}], "register": "中性", "sense_fingerprint": "赛车：竞速比赛专用的汽车或摩托车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赛车", "is_correct": true, "explanation": "正确：“赛车”指专门用于竞速比赛的车，与“速度特别快”相符。"}, {"text": "自行车", "is_correct": false, "explanation": "搭配：开的是汽车等车辆，不说“开自行车”，应说“骑自行车”。"}, {"text": "购物车", "is_correct": false, "explanation": "语义：购物车是推着用的，不能“开”，也不快，与句意不符。"}, {"text": "拖拉机", "is_correct": false, "explanation": "语义：拖拉机主要用于田间耕作，速度慢，与“速度特别快”矛盾。"}], "explanations": {"赛车": "正确：“赛车”指专门用于竞速比赛的车，与“速度特别快”相符。", "自行车": "搭配：开的是汽车等车辆，不说“开自行车”，应说“骑自行车”。", "购物车": "语义：购物车是推着用的，不能“开”，也不快，与句意不符。", "拖拉机": "语义：拖拉机主要用于田间耕作，速度慢，与“速度特别快”矛盾。"}, "sentence_index": 0, "correct_answer": "赛车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家买了一只赛车，周末常去玩。", "explanation": "这里不应使用“只”。赛车是车辆，量词应用“辆”，“只”多用于动物或成对的东西。"}, {"text": "这条赛车跑得很快，大家都想试一试。", "explanation": "这里不能用“条”。“条”用于细长的东西，车辆应用“辆”。"}, {"text": "他是一名赛车，每天都在训练。", "explanation": "这里应该用“赛车手”。“赛车”指车，指驾驶赛车的人要说“赛车手”，不能直接用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赛车", "is_correct": true, "explanation": "正确：赛车的轮胎比普通汽车的宽，符合句意。"}, {"text": "高铁", "is_correct": false, "explanation": "语义：高铁靠钢轮在钢轨上行驶，没有轮胎，与“轮胎”不符。"}, {"text": "摩天轮", "is_correct": false, "explanation": "搭配：摩天轮的结构不装轮胎，“轮胎”不能与它搭配。"}, {"text": "轮船", "is_correct": false, "explanation": "语义：轮船在水上航行，没有轮胎，与句中的“轮胎”矛盾。"}], "explanations": {"赛车": "正确：赛车的轮胎比普通汽车的宽，符合句意。", "高铁": "语义：高铁靠钢轮在钢轨上行驶，没有轮胎，与“轮胎”不符。", "摩天轮": "搭配：摩天轮的结构不装轮胎，“轮胎”不能与它搭配。", "轮船": "语义：轮船在水上航行，没有轮胎，与句中的“轮胎”矛盾。"}, "sentence_index": 6, "correct_answer": "赛车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在操场上赛车，跑得最快的人获胜。", "explanation": "这里应该用“赛跑”。赛车指车辆比赛，人用脚比快要说赛跑，不能说赛车。"}, {"text": "一艘艘赛车冲过了终点，大家都在鼓掌。", "explanation": "这里不能用“艘”。“艘”用于船只，赛车是车辆，应用“辆”。"}, {"text": "这张赛车跑得很快，观众都在欢呼。", "explanation": "这里不能用“张”。“张”用于纸、床等平面的东西，车辆应用“辆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他开着一只蓝色的赛车去比赛。", "corrected_sentence": "他开着一辆蓝色的赛车去比赛。", "error_description": "量词错误：“赛车”是车辆，应用量词“辆”，不能说“一只”。正确说法是“一辆蓝色的赛车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年买了一把赛车。", "corrected_sentence": "他去年买了一辆赛车。", "error_description": "量词错误：“赛车”是车辆，应用量词“辆”，不能说“一把”（“把”用于有把手的东西）。正确说法是“一辆赛车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
