INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91643, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "跑者是跑步的人。", "primary_collocate": null, "pronunciation": "pǎo zhě", "ipa": "pʰau˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位跑者每天早上跑十公里。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑者在路边停下来喝水了。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有很多跑者。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一名跑者，每个星期跑五天。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋很轻，很适合跑者穿。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "所有跑者都在起点等着比赛开始。", "target_word": "跑者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑者要多喝水，不要跑得太快。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一名跑者已经到终点了。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，路上的跑者还是很多。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位资深跑者已经跑了三十年。", "target_word": "跑者", "complexity_tier": "T3", "furigana": "nà wèi zī shēn pǎo zhě yǐ jīng pǎo le sān shí nián", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "长跑者", "label": "复合"}], "register": "中性", "sense_fingerprint": "指喜欢跑步或正在跑步的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跑者", "is_correct": true, "explanation": "跑者：跑步的人，“这位”指人，与“每天早上跑十公里”相符。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“位”用于人，不能说“这位小狗”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“位”只用于人，不能说“这位汽车”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能跑步。"}], "explanations": {"跑者": "跑者：跑步的人，“这位”指人，与“每天早上跑十公里”相符。", "小狗": "搭配：“位”用于人，不能说“这位小狗”。", "汽车": "搭配：“位”只用于人，不能说“这位汽车”。", "石头": "语义：石头没有生命，不能跑步。"}, "sentence_index": 0, "correct_answer": "跑者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一只跑者，每个星期跑五天。", "explanation": "这里应该用〈名〉或〈位〉。跑者指人，量词“只”多用于动物。"}, {"text": "他是一名篮球跑者，每个星期练五天。", "explanation": "这里应该用〈运动员〉。跑者专指跑步的人，不能说“篮球跑者”，篮球要用“运动员”。"}, {"text": "这辆汽车是一名跑者，每天跑很多路。", "explanation": "跑者指跑步的人，不指车辆；这里应该用〈赛车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跑者", "is_correct": true, "explanation": "跑者：跑步的人，能作“要多喝水，不要跑得太快”的对象。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不需要喝水，也不会跑步。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不需要喝水，也不会“跑得太快”，与句子的主语不合。"}, {"text": "树", "is_correct": false, "explanation": "配价：“跑得太快”要求能跑的主语，树不能自己“跑”，不能作主语。"}], "explanations": {"跑者": "跑者：跑步的人，能作“要多喝水，不要跑得太快”的对象。", "电脑": "语义：电脑不需要喝水，也不会跑步。", "椅子": "语义：椅子不需要喝水，也不会“跑得太快”，与句子的主语不合。", "树": "配价：“跑得太快”要求能跑的主语，树不能自己“跑”，不能作主语。"}, "sentence_index": 6, "correct_answer": "跑者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位资深跑者从来没有跑过步，只喜欢游泳。", "explanation": "跑者指跑步的人，“从来没有跑过步”与之矛盾；这里应该用〈游泳者〉。"}, {"text": "那位资深跑者三十年来从不运动，每天只在家看书。", "explanation": "跑者指跑步的人，三十年从不运动的人不能称作跑者；这里应该用〈读者〉。"}, {"text": "那位资深跑者已经躺在病床上三十年了，从未起身。", "explanation": "跑者指跑步的人，躺在病床上三十年从未起身的人不能称作跑者；这里应该用〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只跑者每天晚上在河边跑步。", "corrected_sentence": "那位跑者每天晚上在河边跑步。", "error_description": "量词错误：“只”用于动物或单个东西，跑者指人，应把“只”改为“位”，即“那位跑者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "第一条跑者刚刚冲过终点线。", "corrected_sentence": "第一名跑者刚刚冲过终点线。", "error_description": "量词错误：“条”用于细长的东西，跑者指人，应把“条”改为“名”，即“第一名跑者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
