INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "跑步的人。", "primary_collocate": null, "pronunciation": "pǎo zhě", "ipa": "pʰau˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨天的马拉松有三千名跑者参加。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小喜欢跑步，现在是一位专业跑者。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑者在比赛前要先做热身。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河边的路很安静，跑者很喜欢来。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手表可以告诉跑者跑了多远。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑者的膝盖常常会疼。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前是个胖子，现在成了跑者。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "终点有人给每位跑者一瓶水。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有经验的跑者知道怎样跑得更远。", "target_word": "跑者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上路灯下，几个跑者慢慢跑过。", "target_word": "跑者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "长跑者", "label": "复合"}], "register": "中性", "sense_fingerprint": "指以跑步为运动或比赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跑者", "is_correct": true, "explanation": "跑者：跑步的人，“三千名”指人，与马拉松参赛者相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能参加马拉松比赛。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“名”用于人，不能用于窗户，且窗户不能参赛。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能参加马拉松，比赛参加者必须是人。"}], "explanations": {"跑者": "跑者：跑步的人，“三千名”指人，与马拉松参赛者相符。", "石头": "语义：石头不能参加马拉松比赛。", "窗户": "搭配：“名”用于人，不能用于窗户，且窗户不能参赛。", "汽车": "语义：汽车不能参加马拉松，比赛参加者必须是人。"}, "sentence_index": 0, "correct_answer": "跑者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只跑者很喜欢来这条河边。", "explanation": "这里应该用〈位〉。“只”多用于动物，指人要用“位”或“名”。"}, {"text": "他是一名射箭跑者，比赛很厉害。", "explanation": "这里应该用〈选手〉。跑者专指跑步的人，射箭要用“选手”。"}, {"text": "这条河边的路很安静，那辆车是跑者。", "explanation": "跑者指跑步的人，不指车辆；这里应该用〈赛车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跑者", "is_correct": true, "explanation": "跑者：跑步的人，“现在成了”后面可以是人的身份，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：一个人不会变成桌子，与“是个胖子，现在成了”的人身份变化不符。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：一个人不会变成白菜，句子表示人的身份变化。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：人不会变成电脑，“现在成了”后接的应是人的身份，与句中的人物变化不符。"}], "explanations": {"跑者": "跑者：跑步的人，“现在成了”后面可以是人的身份，与句意相符。", "桌子": "语义：一个人不会变成桌子，与“是个胖子，现在成了”的人身份变化不符。", "白菜": "语义：一个人不会变成白菜，句子表示人的身份变化。", "电脑": "语义：人不会变成电脑，“现在成了”后接的应是人的身份，与句中的人物变化不符。"}, "sentence_index": 6, "correct_answer": "跑者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上路灯下，几个跑者从来不跑步，只在讲台上上课。", "explanation": "跑者指跑步的人，“从来不跑步”与之矛盾；这里应该用〈老师〉。"}, {"text": "晚上路灯下，几个跑者一辈子没跑过步，只在街角坐着。", "explanation": "跑者指跑步的人，“一辈子没跑过步”与之矛盾；这里应该用〈路人〉。"}, {"text": "晚上路灯下，那辆车是跑者，慢慢跑过。", "explanation": "跑者指跑步的人，不指车辆；这里应该用〈赛车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只跑者在清晨的公园里慢跑。", "corrected_sentence": "一位跑者在清晨的公园里慢跑。", "error_description": "量词错误：“只”用于动物或单个东西，跑者指人，应把“只”改为“位”，即“一位跑者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇来了一头年轻跑者。", "corrected_sentence": "这个小镇来了一位年轻跑者。", "error_description": "量词错误：“头”用于大型牲畜，跑者指人，应把“头”改为“位”，即“一位年轻跑者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
