INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "冬天从天上飘下来的白白的东西。", "primary_collocate": null, "pronunciation": "xuě", "ipa": "ɕɥe˨˩˦", "syllable_count": 1, "sentences": [{"text": "冬天到了，天上飘着雪。", "target_word": "雪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的雪越下越大。", "target_word": "雪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢看雪，不喜欢下雨。", "target_word": "雪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雪是白色的，很冷。", "target_word": "雪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "屋顶上都是雪。", "target_word": "雪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我用手捧起一把雪。", "target_word": "雪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方的冬天很少有雪。", "target_word": "雪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈让我穿厚衣服去玩雪。", "target_word": "雪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚的雪让整条路都变白了。", "target_word": "雪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次看到雪，高兴地叫了起来。", "target_word": "雪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "雪花", "label": "复合"}, {"form": "下雪", "label": "复合"}], "register": "中性", "sense_fingerprint": "冬天从天上飘落的白色东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91645, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雪", "is_correct": true, "explanation": "雪（xuě）：冬天从天上飘下来的白色东西，正是这个意思。"}, {"text": "学", "is_correct": false, "explanation": "学（xué）与雪（xuě）声调不同，学是第二声，意思是学习。"}, {"text": "血", "is_correct": false, "explanation": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。"}, {"text": "削", "is_correct": false, "explanation": "削（xuē）与雪（xuě）声调不同，削是第一声，意思是削去外皮。"}, {"text": "写", "is_correct": false, "explanation": "写（xiě）与雪（xuě）声调相同，韵母不同（ie 与 ue），意思是书写。"}], "explanations": {"雪": "雪（xuě）：冬天从天上飘下来的白色东西，正是这个意思。", "学": "学（xué）与雪（xuě）声调不同，学是第二声，意思是学习。", "血": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。", "削": "削（xuē）与雪（xuě）声调不同，削是第一声，意思是削去外皮。", "写": "写（xiě）与雪（xuě）声调相同，韵母不同（ie 与 ue），意思是书写。"}, "sentence_index": null, "correct_answer": "雪"}, "level_3": {"options": [{"text": "雪", "is_correct": true, "explanation": "冬天天上飘着的白色东西就是雪，“飘着”的主语是雪最合适。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会在天上飘，与“飘着”的描写不相容。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“飘”不搭配汽车，汽车不会飘在天上。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐不会自己在天上飘，句子描写的天空景象与盐不符。"}], "explanations": {"雪": "冬天天上飘着的白色东西就是雪，“飘着”的主语是雪最合适。", "石头": "语义：石头不会在天上飘，与“飘着”的描写不相容。", "汽车": "搭配：“飘”不搭配汽车，汽车不会飘在天上。", "盐": "语义：盐不会自己在天上飘，句子描写的天空景象与盐不符。"}, "sentence_index": 0, "correct_answer": "雪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天我们在湖上溜雪。", "explanation": "这里应该用〈冰〉。“溜冰”是在冰面上滑行，雪地上的滑行要说“滑雪”，不说“溜雪”。"}, {"text": "窗外飘着一只雪。", "explanation": "量词错误。这里应该用〈片〉：“一片雪”。“只”用于动物，不能用来数雪。"}, {"text": "屋顶的烟囱里冒出了雪。", "explanation": "这里应该用〈烟〉。烟从烟囱里冒出来；雪是从天上飘下来的，不能说“从烟囱里冒出雪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91645, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雪", "is_correct": true, "explanation": "雪（xuě）：冬天从天上飘下来的白色东西，正是这个意思。"}, {"text": "靴", "is_correct": false, "explanation": "靴（xuē）与雪（xuě）声调不同，靴是第一声，意思是靴子。"}, {"text": "血", "is_correct": false, "explanation": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。"}, {"text": "穴", "is_correct": false, "explanation": "穴（xué）与雪（xuě）声调不同，穴是第二声，意思是洞穴。"}], "explanations": {"雪": "雪（xuě）：冬天从天上飘下来的白色东西，正是这个意思。", "靴": "靴（xuē）与雪（xuě）声调不同，靴是第一声，意思是靴子。", "血": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。", "穴": "穴（xué）与雪（xuě）声调不同，穴是第二声，意思是洞穴。"}, "sentence_index": null, "correct_answer": "雪"}, "level_3": {"options": [{"text": "雪", "is_correct": true, "explanation": "南方冬天少雪是常见情况，“很少有雪”与句意相符。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能用“很少有”来描述，与句中的“冬天”也矛盾。"}, {"text": "暑假", "is_correct": false, "explanation": "语义：暑假是夏季的假期，与冬天的语境不符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“很少有”描述事物或现象的稀少，钢琴与南方冬天的天气无关，句意荒谬。"}], "explanations": {"雪": "南方冬天少雪是常见情况，“很少有雪”与句意相符。", "夏天": "语义：夏天是季节，不能用“很少有”来描述，与句中的“冬天”也矛盾。", "暑假": "语义：暑假是夏季的假期，与冬天的语境不符。", "钢琴": "语义：“很少有”描述事物或现象的稀少，钢琴与南方冬天的天气无关，句意荒谬。"}, "sentence_index": 6, "correct_answer": "雪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上起了大雪，路都看不清。", "explanation": "这里应该用〈雾〉。“起雾”指雾气升起，雪只能说“下”，不说“起大雪”。"}, {"text": "院子里铺了一张雪。", "explanation": "量词错误。这里应该用〈层〉：“一层雪”。“张”用于纸、桌子等平面的东西，不用来数雪。"}, {"text": "天边响起了一阵雪。", "explanation": "这里应该用〈雷〉。雷可以在天边响起；雪是从天上飘下来的，不能说“响起一阵雪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天早上又下起了一只雪。", "corrected_sentence": "今天早上又下起了一场雪。", "error_description": "量词错误：“只”用于动物，不能用来数雪；下雪的量词应用“场”，应说“下起了一场雪”，不说“下起了一只雪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把车上的一只雪扫掉了。", "corrected_sentence": "他把车上的一层雪扫掉了。", "error_description": "量词错误：“只”用于动物，不能用来数雪；积在车上的雪应用“层”，说“一层雪”，不说“一只雪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
