INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空气中的水蒸气遇冷凝结成白色晶体，从空中降下的东西。", "primary_collocate": null, "pronunciation": "xuě", "ipa": "ɕɥe˨˩˦", "syllable_count": 1, "sentences": [{"text": "昨天早上我起床时，院子里已经积了厚厚的雪。", "target_word": "雪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的冬天常常下雪。", "target_word": "雪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地上的雪很白，也很厚。", "target_word": "雪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在雪里玩。", "target_word": "雪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雪遇到热就会变成水。", "target_word": "雪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走在雪上，留下一行脚印。", "target_word": "雪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山上的雪一年四季都不化。", "target_word": "雪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把门前的雪扫干净了。", "target_word": "雪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下得太大，飞机不能起飞。", "target_word": "雪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有见过雪，所以很想去北方。", "target_word": "雪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "雪花", "label": "复合"}, {"form": "下雪", "label": "复合"}], "register": "中性", "sense_fingerprint": "空气中水汽遇冷凝成的白色结晶，从空中落下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91646, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雪", "is_correct": true, "explanation": "雪（xuě）：空气中水汽遇冷凝成的白色结晶，从天上落下，正是这个意思。"}, {"text": "学", "is_correct": false, "explanation": "学（xué）与雪（xuě）声调不同，学是第二声，意思是学习。"}, {"text": "血", "is_correct": false, "explanation": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。"}, {"text": "靴", "is_correct": false, "explanation": "靴（xuē）与雪（xuě）声调不同，靴是第一声，意思是靴子。"}, {"text": "写", "is_correct": false, "explanation": "写（xiě）与雪（xuě）声调相同，韵母不同（ie 与 ue），意思是书写。"}], "explanations": {"雪": "雪（xuě）：空气中水汽遇冷凝成的白色结晶，从天上落下，正是这个意思。", "学": "学（xué）与雪（xuě）声调不同，学是第二声，意思是学习。", "血": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。", "靴": "靴（xuē）与雪（xuě）声调不同，靴是第一声，意思是靴子。", "写": "写（xiě）与雪（xuě）声调相同，韵母不同（ie 与 ue），意思是书写。"}, "sentence_index": null, "correct_answer": "雪"}, "level_3": {"options": [{"text": "雪", "is_correct": true, "explanation": "“雪”是从天上落下、能在地上积成厚层的白色东西，与“积了厚厚的”搭配自然。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是液体，不会积成厚厚的一层，句中“积了厚厚的”不适用于雨。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不会从天上落下，在院子里积成厚厚一层，与句子描写的冬天早晨场景不符。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖不会从天上降落并在院子里积成厚层，与句子的场景不符。"}], "explanations": {"雪": "“雪”是从天上落下、能在地上积成厚层的白色东西，与“积了厚厚的”搭配自然。", "雨": "语义：雨是液体，不会积成厚厚的一层，句中“积了厚厚的”不适用于雨。", "花": "语义：花不会从天上落下，在院子里积成厚厚一层，与句子描写的冬天早晨场景不符。", "糖": "语义：糖不会从天上降落并在院子里积成厚层，与句子的场景不符。"}, "sentence_index": 0, "correct_answer": "雪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖面上结了一层厚厚的雪。", "explanation": "这里应该用〈冰〉。湖面冻结形成的白色固体是冰；雪是从天上落下、堆积在地面的东西，不说“结雪”。"}, {"text": "我们在院子里看见一只雪。", "explanation": "量词错误。这里应该用〈场〉：“一场雪”。“只”用于动物，不能用来数雪。"}, {"text": "清晨，山谷里升起了一层雪。", "explanation": "这里应该用〈雾〉。雾气从地面升起，飘浮在山谷间；雪是从天上落下来的，不能说“升起一层雪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91646, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雪", "is_correct": true, "explanation": "雪（xuě）：空中降下的白色结晶，正是这个意思。"}, {"text": "削", "is_correct": false, "explanation": "削（xuē）与雪（xuě）声调不同，削是第一声，意思是削去外皮。"}, {"text": "血", "is_correct": false, "explanation": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。"}, {"text": "穴", "is_correct": false, "explanation": "穴（xué）与雪（xuě）声调不同，穴是第二声，意思是洞穴。"}], "explanations": {"雪": "雪（xuě）：空中降下的白色结晶，正是这个意思。", "削": "削（xuē）与雪（xuě）声调不同，削是第一声，意思是削去外皮。", "血": "血（xuè）与雪（xuě）声调不同，血是第四声，意思是血液。", "穴": "穴（xué）与雪（xuě）声调不同，穴是第二声，意思是洞穴。"}, "sentence_index": null, "correct_answer": "雪"}, "level_3": {"options": [{"text": "雪", "is_correct": true, "explanation": "“雪”能在山上长久积存、一年四季不化，与“不化”的描述相符。"}, {"text": "水", "is_correct": false, "explanation": "语义：水本身已是液体，不存在“化”的问题，句子说“一年四季都不化”没有意义。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会融化，“不化”的说法不适用于书。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“化”不搭配树，树不会融化，这里的描述说不通。"}], "explanations": {"雪": "“雪”能在山上长久积存、一年四季不化，与“不化”的描述相符。", "水": "语义：水本身已是液体，不存在“化”的问题，句子说“一年四季都不化”没有意义。", "书": "语义：书不会融化，“不化”的说法不适用于书。", "树": "搭配：“化”不搭配树，树不会融化，这里的描述说不通。"}, "sentence_index": 6, "correct_answer": "雪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口的空地上堆了一张雪。", "explanation": "量词错误。“张”用于平面的东西，雪不用“张”来数；这里应该用〈层〉：“一层雪”。"}, {"text": "窗户上结了一层白雪。", "explanation": "这里应该用〈霜〉。窗户上遇冷凝结的白色晶体是霜；“结”不能用于雪。"}, {"text": "烟囱里冒出了雪。", "explanation": "这里应该用〈烟〉。烟从烟囱里冒出来；雪是从天上落下来的，不能说“从烟囱里冒出雪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天晚上下了一个雪。", "corrected_sentence": "昨天晚上下了一场雪。", "error_description": "量词错误：“雪”的量词应用“场”（一场雪），这里用了通用量词“个”，说“一个雪”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗外正在下一条雪。", "corrected_sentence": "窗外正在下一场雪。", "error_description": "量词错误：“条”用于细长的东西，不能用来数雪；下雪应用“场”，说“下一场雪”，不说“下一条雪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91648, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91648, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91648, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑着离开。", "primary_collocate": null, "pronunciation": "pǎo zǒu", "ipa": "pʰau̯˨˩˦ tsou̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他看见老板来了，赶紧跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩打碎了玻璃，一下子跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只兔子听到声音，一转眼就跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喊了他一声，他头也不回地跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷被我们发现后，慌慌张张地跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安一出现，门口的小贩就跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想听我解释，转身跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛突然跑走了，农夫在后面追。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们看到蛇，吓得大叫着跑走了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗以前也跑走了一次，后来被找回来了。", "target_word": "跑走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑走了", "label": "体标（了）"}, {"form": "跑走过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "跑着离开，强调突然、匆忙地走掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跑走", "is_correct": true, "explanation": "跑走：跑着离开，强调突然、匆忙地走掉，与“赶紧”和“老板来了”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：老板来了，人不会“赶紧游泳”，句意说不通。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：“赶紧”表示匆忙和紧张，与“大笑”的情绪矛盾。"}, {"text": "叫醒", "is_correct": false, "explanation": "配价：“叫醒”需要被叫的人作宾语，句中没有。"}], "explanations": {"跑走": "跑走：跑着离开，强调突然、匆忙地走掉，与“赶紧”和“老板来了”相符。", "游泳": "语义：老板来了，人不会“赶紧游泳”，句意说不通。", "大笑": "语义：“赶紧”表示匆忙和紧张，与“大笑”的情绪矛盾。", "叫醒": "配价：“叫醒”需要被叫的人作宾语，句中没有。"}, "sentence_index": 0, "correct_answer": "跑走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在操场上跑走，练习短跑。", "explanation": "这里应该用〈锻炼〉。跑走表示跑着离开，不能用来说在操场上练习短跑。"}, {"text": "他明明跑走了，却一直站在我的身边。", "explanation": "这里不能用〈跑走〉。跑走表示离开，与后半句“一直站在我的身边”相矛盾。"}, {"text": "我的钱包跑走了。", "explanation": "这里应该用〈丢〉。跑走只用于人或动物自己跑开，钱包不会自己跑；东西不见了要说〈丢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跑走", "is_correct": true, "explanation": "跑走：跑着离开，与“不想听我解释”后转身离开的情境相符。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“答应”表示应允，与“不想听我解释”的态度矛盾。"}, {"text": "修好", "is_correct": false, "explanation": "配价：“修好”需要被修的东西作宾语，句中没有。"}, {"text": "擦干", "is_correct": false, "explanation": "搭配：“擦干”搭配“手”“身子”等湿的东西，不与“转身”搭配。"}], "explanations": {"跑走": "跑走：跑着离开，与“不想听我解释”后转身离开的情境相符。", "答应": "语义：“答应”表示应允，与“不想听我解释”的态度矛盾。", "修好": "配价：“修好”需要被修的东西作宾语，句中没有。", "擦干": "搭配：“擦干”搭配“手”“身子”等湿的东西，不与“转身”搭配。"}, "sentence_index": 6, "correct_answer": "跑走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从外面跑走，气喘吁吁地站在门口。", "explanation": "这里应该用〈跑来〉。跑走表示离开，而“从外面”进来、站到门口是朝说话人的方向移动，要说〈跑来〉。"}, {"text": "周末我们去公园跑走。", "explanation": "这里应该用〈散步〉。跑走表示跑着离开，不能用来说去公园悠闲地走动。"}, {"text": "她的雨伞一阵风就跑走了。", "explanation": "这里应该用〈吹走〉。跑走只用于人或动物自己跑开，雨伞是被风吹走的，要说〈吹走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只狗听见门响，赶紧被跑走了。", "corrected_sentence": "那只狗听见门响，赶紧跑走了。", "error_description": "错误：“被跑走了”；正确：“跑走了”。“跑走”是不及物动词，没有受事可以承受动作，不能用“被”字句，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一有人靠近，那只猫就转身把跑走了。", "corrected_sentence": "一有人靠近，那只猫就转身跑走了。", "error_description": "错误：“转身把跑走了”；正确：“转身跑走了”。“跑走”没有可以被处置的宾语，不能用“把”字句，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
