INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91649, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91649, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一定要，不可以不这样。", "primary_collocate": null, "pronunciation": "fēi yào", "ipa": "feɪ˥ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "想学好汉语，非要多说多练不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要赶上火车，我们非要现在出发不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事非要你亲自去不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体不舒服，非要先去医院检查不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想参加比赛，非要先报名不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这道菜，非要用新鲜的鱼不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要考试，今晚非要早点儿睡不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间太脏了，非要打扫不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧了，非要带他去看医生不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写这篇文章，非要自己查资料不可。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "非要…不可：表示必须这样做，强调不这样做不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91649, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非要", "is_correct": true, "explanation": "“非要…不可”表示必须这样做、不这样不行，与“想学好汉语，多说多练”的意思相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“想学好汉语”这种主动的打算相矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，而句中说的是尚未实现的“想学好”。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示庆幸的好结果，句中没有已经发生的结果可以庆幸。"}], "explanations": {"非要": "“非要…不可”表示必须这样做、不这样不行，与“想学好汉语，多说多练”的意思相符。", "竟然": "语义：“竟然”表示出乎意料，与“想学好汉语”这种主动的打算相矛盾。", "已经": "体貌：“已经”表示动作已经完成，而句中说的是尚未实现的“想学好”。", "幸亏": "语义：“幸亏”表示庆幸的好结果，句中没有已经发生的结果可以庆幸。"}, "sentence_index": 0, "correct_answer": "非要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你非要准时到达。", "explanation": "这里应该用〈务必〉。“务必”表示恳切地请对方一定做到；“非要”表示当事人坚持、硬要，用在礼貌的请求中语气生硬。"}, {"text": "这家饭馆的菜非要好吃。", "explanation": "这里应该用〈非常〉。“非要”表示必须这样做，不能用来修饰形容词表示程度。"}, {"text": "这份合同非要你签字了吗？", "explanation": "这里应该用〈需要〉。“非要”表示坚持或必然的要求，用于询问已经发生的情况时语气不自然，直接说“需要你签字吗”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91649, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非要", "is_correct": true, "explanation": "“非要…不可”表示必须这样，句中“明天要考试，今晚要早点儿睡”正是这种必要的意思。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示证实先前的预料，而“明天要考试”是尚未发生的安排，无法被证实。"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：“刚刚”表示刚发生不久的动作，与“今晚”的未来安排不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数少，与“不可”所强调的必须语气，以及考前的必要性相冲突。"}], "explanations": {"非要": "“非要…不可”表示必须这样，句中“明天要考试，今晚要早点儿睡”正是这种必要的意思。", "果然": "语义：“果然”表示证实先前的预料，而“明天要考试”是尚未发生的安排，无法被证实。", "刚刚": "体貌：“刚刚”表示刚发生不久的动作，与“今晚”的未来安排不符。", "偶尔": "语义：“偶尔”表示次数少，与“不可”所强调的必须语气，以及考前的必要性相冲突。"}, "sentence_index": 6, "correct_answer": "非要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天非要下雨不可。", "explanation": "这里应该用〈一定会〉。“非要…不可”表示人为的必要或坚持，不用于自然现象；应说“明天一定会下雨”。"}, {"text": "大家都不同意，你为什么非要今天说？", "explanation": "这是“非要”的另一个义项“坚决要、偏偏要”，表示不顾他人反对仍坚持，与“一定要、不可以不这样”的义项不同。不需要换词。"}, {"text": "周末你非要陪陪奶奶，这是原则问题。", "explanation": "这里应该用〈得〉。“非要”强调必须并常与“不可”搭配，语气过重；日常的需要只说“周末你得陪陪奶奶”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气这么冷，你非要穿了厚衣服不可。", "corrected_sentence": "天气这么冷，你非要穿厚衣服不可。", "error_description": "“了”误用：“非要…不可”表示尚未发生的必要行为，“穿”后不能加“了”。正确：应说“天气这么冷，你非要穿厚衣服不可”，不能说“你非要穿了厚衣服不可”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他身体这么差，非要去了医院复查不可。", "corrected_sentence": "他身体这么差，非要去医院复查不可。", "error_description": "“了”误用：“非要…不可”表示尚未发生的必要行为，“去”后不能加“了”。正确：应说“他身体这么差，非要去医院复查不可”，不能说“非要去了医院复查不可”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
