INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91650, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91650, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "偏偏要；坚决要。", "primary_collocate": null, "pronunciation": "fēi yào", "ipa": "feɪ˥ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我说别去，他非要去。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下着大雨，弟弟非要出去玩。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让他穿外套，他非要穿短袖。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说不好吃，她非要尝一尝。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他休息，他非要去上班。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我劝过她很多次，她非要自己试试。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天已经黑了，孩子非要去公园。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不同意，你为什么非要今天说？", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经买了蓝色的，女儿非要红色的。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不让卖，他非要把那辆旧车卖了。", "target_word": "非要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别人劝阻或不同意，却固执地坚持要做某事或要某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed705e94-968e-41c7-a6e9-f6ef3ffbe67a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非要", "is_correct": true, "explanation": "“非要”表示偏偏坚持，与“我说别去”后他仍然要去的语境相符。"}, {"text": "务必", "is_correct": false, "explanation": "语域：“务必”是书面语，表示恳切的要求，与这句口语中劝阻后的叙述不协调。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示庆幸的好结果，与“我说别去”的劝阻语境不符。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多与“别、不要”搭配，不能直接修饰“去”来表示这个意思。"}], "explanations": {"非要": "“非要”表示偏偏坚持，与“我说别去”后他仍然要去的语境相符。", "务必": "语域：“务必”是书面语，表示恳切的要求，与这句口语中劝阻后的叙述不协调。", "幸亏": "语义：“幸亏”表示庆幸的好结果，与“我说别去”的劝阻语境不符。", "千万": "搭配：“千万”多与“别、不要”搭配，不能直接修饰“去”来表示这个意思。"}, "sentence_index": 0, "correct_answer": "非要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议非要准时召开不可。", "explanation": "这里应该用〈必须〉。“非要…不可”此处表示客观上的必要，与本义“偏偏要、坚决要”不同，句中没有坚持或劝阻的语境。"}, {"text": "按规定，申请人非要提交身份证。", "explanation": "这里应该用〈必须〉。“必须”用于客观规定的要求；“非要”表示当事人固执地坚持，用于规定时语气不当。"}, {"text": "你非要多喝水，这样对身体好。", "explanation": "这里应该用〈应该〉。“应该”是一般的建议；“非要”表示固执坚持，用来提出健康建议时语气过重，且没有对方反对的语境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非要", "is_correct": true, "explanation": "“非要”表示坚持要做，与孩子天黑仍执意出门、不听劝的语境相符。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，与这种口语叙述的语气不协调。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数少，与孩子执意出门的坚持语气不符。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与“不、没”等否定词连用，不能直接修饰肯定的“去”，“孩子根本去公园”说不通。"}], "explanations": {"非要": "“非要”表示坚持要做，与孩子天黑仍执意出门、不听劝的语境相符。", "业已": "语域：“业已”是书面语，与这种口语叙述的语气不协调。", "偶尔": "语义：“偶尔”表示次数少，与孩子执意出门的坚持语气不符。", "根本": "搭配：“根本”通常与“不、没”等否定词连用，不能直接修饰肯定的“去”，“孩子根本去公园”说不通。"}, "sentence_index": 6, "correct_answer": "非要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事非要尽快办。", "explanation": "这里应该用〈得〉。“非要”带有不顾劝阻、硬要的意味，句中没有劝阻的语境；一般的催促说“这件事得尽快办”即可。"}, {"text": "这笔钱非要今年还清不可。", "explanation": "这是“非要”的另一个义项“一定要、不可以不这样”，表示客观必要，与“偏偏坚持”的义项不同。不需要换词。"}, {"text": "学生非要按时交作业。", "explanation": "这里应该用〈务必〉。“务必”表示恳切的要求；“非要”表示当事人固执地坚持，用于要求学生时语气不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明明病了，非非要去上班。", "corrected_sentence": "他明明病了，非要去上班。", "error_description": "错误：“非要”中间被多写了一个“非”，写成了“非非要”。正确：应说“非要去上班”。“非要”是固定副词，表示偏偏坚持，不能重复“非”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子明明累了，非非要再玩一会儿。", "corrected_sentence": "孩子明明累了，非要再玩一会儿。", "error_description": "错误：“非要”中间被多写了一个“非”，写成了“非非要”。正确：应说“非要再玩一会儿”。“非要”是固定副词，表示偏偏坚持，不能重复“非”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce717d61-b31b-4c12-b29f-67097c2987f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
