INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91651, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91651, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "路条是一张纸，写着你可以走这条路。", "primary_collocate": null, "pronunciation": "lù tiáo", "ipa": "lu˥˩ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "老人给我一张路条，上面写着“可以通行”。", "target_word": "路条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在书里找到一张旧路条。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你拿着这张路条，就可以过桥。", "target_word": "路条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的人要看你的路条。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张路条是用红笔写的。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把路条递给了守桥的人。", "target_word": "路条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有路条的人不能走这条路。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路条上有一个红色的章。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在博物馆看到了一张老路条。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，这张路条是外公留下的。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "路條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一张写着允许走某条路的纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路条", "is_correct": true, "explanation": "路条是写着可以通行的纸，与句中“可以通行”的内容相合。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：照片上一般不写“可以通行”这样的字，与句子搭配不当。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单写的是金额和费用，不是通行许可。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片写的是个人信息，与“可以通行”的内容不符。"}], "explanations": {"路条": "路条是写着可以通行的纸，与句中“可以通行”的内容相合。", "照片": "搭配：照片上一般不写“可以通行”这样的字，与句子搭配不当。", "账单": "语义：账单写的是金额和费用，不是通行许可。", "名片": "语义：名片写的是个人信息，与“可以通行”的内容不符。"}, "sentence_index": 0, "correct_answer": "路条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找朋友借钱，写了一张路条。", "explanation": "这里应该用〈借条〉。借条是借钱时写的字据，路条是出行凭证。"}, {"text": "出国要带路条。", "explanation": "这里应该用〈护照〉。路条是国内通行的凭证，出国要用护照。"}, {"text": "付款后他拿到了路条。", "explanation": "这里应该用〈收据〉。付款后拿到的是收据，路条不是买卖中发放的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路条", "is_correct": true, "explanation": "路条是通行这条路的凭证，没有它就不能走。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用书，与走路无关。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不是通行凭证，“走这条路”不与它搭配。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的书写用具，与走路无关。"}], "explanations": {"路条": "路条是通行这条路的凭证，没有它就不能走。", "课本": "语义：课本是学习用书，与走路无关。", "作业": "搭配：“作业”不是通行凭证，“走这条路”不与它搭配。", "黑板": "语义：黑板是教室里的书写用具，与走路无关。"}, "sentence_index": 6, "correct_answer": "路条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路口的路条指向北边，我们就往北走了。", "explanation": "这里应该用〈路标〉。路条是通行凭证，指示方向的要用路标。"}, {"text": "进博物馆时，他买了一张路条，可以参观展览。", "explanation": "这里应该用〈门票〉。路条是旧时的通行凭证，买票入场要用门票。"}, {"text": "外公留下一张路条，上面写着要把房子留给长子。", "explanation": "这里应该用〈遗嘱〉。路条是通行凭证，写明遗产分配的要用遗嘱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桥头的人看了这只路条。", "corrected_sentence": "桥头的人看了这张路条。", "error_description": "“路条”的量词应为“张”，这里用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "守桥的人把一只路条收走了。", "corrected_sentence": "守桥的人把一张路条收走了。", "error_description": "“路条”的量词应为“张”，这里用“只”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
