INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91652, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧时通行的凭证，写明持有人可通行的纸条。", "primary_collocate": null, "pronunciation": "lù tiáo", "ipa": "lu˥˩ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "旧时没有路条，不能随便出城。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他手里拿着一张路条。", "target_word": "路条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵看了看路条，才让我们过去。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，以前走远路要带路条。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有路条，他们被拦在了城门外。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张路条上写着他的名字。", "target_word": "路条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生给了我一张路条，我就上路了。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路条丢了，他很着急。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里的人拿出路条给守门的人看。", "target_word": "路条", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把路条放在口袋里，走出了村子。", "target_word": "路条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "路條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "旧时写明持有人可以通行的凭证纸条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa7062f5-2af6-4f8f-accf-5e5f322266bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路条", "is_correct": true, "explanation": "路条是旧时的通行凭证，没有它不能随便出城。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，与出城无关。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是查字用的工具书，与出城无关。"}, {"text": "发票", "is_correct": false, "explanation": "搭配：“发票”是付款或报销的单据，不说凭它出城。"}], "explanations": {"路条": "路条是旧时的通行凭证，没有它不能随便出城。", "雨伞": "语义：雨伞是遮雨的用具，与出城无关。", "字典": "语义：字典是查字用的工具书，与出城无关。", "发票": "搭配：“发票”是付款或报销的单据，不说凭它出城。"}, "sentence_index": 0, "correct_answer": "路条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站买了一张路条，准备回家。", "explanation": "这里应该用〈车票〉。路条是官方发放的通行凭证，不能在车站买。"}, {"text": "他要去美国留学，先办了一张路条。", "explanation": "这里应该用〈护照〉。路条只在国内旧时通行，出国要用护照。"}, {"text": "他向朋友借钱，写下了一张路条。", "explanation": "这里应该用〈借条〉。路条是通行凭证，不是借钱的字据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路条", "is_correct": true, "explanation": "路条是旧时的通行凭证，有了它才能上路。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”用于入场，与“上路”没有搭配关系。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：奖状是颁给获奖者的证书，不是上路的凭证。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是付款时的单据，与上路无关。"}], "explanations": {"路条": "路条是旧时的通行凭证，有了它才能上路。", "门票": "搭配：“门票”用于入场，与“上路”没有搭配关系。", "奖状": "语义：奖状是颁给获奖者的证书，不是上路的凭证。", "账单": "语义：账单是付款时的单据，与上路无关。"}, "sentence_index": 6, "correct_answer": "路条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按照地图上的路条走到了山顶。", "explanation": "这里应该用〈路线〉。路条是旧时的通行凭证，地图上标示的走向要用路线。"}, {"text": "路口立着一块路条，上面写着“前方五公里”。", "explanation": "这里应该用〈路牌〉。路条是通行凭证，路口指示距离的标牌要用路牌。"}, {"text": "我在银行存钱后拿到了一张路条，上面写着金额。", "explanation": "这里应该用〈存单〉。路条是通行凭证，记录存款的凭证要用存单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "守门的人检查了一只路条。", "corrected_sentence": "守门的人检查了一张路条。", "error_description": "“路条”的量词应为“张”，“只”多用于动物等，这里说“一只路条”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "守门的人把路条还了给我。", "corrected_sentence": "守门的人把路条还给了我。", "error_description": "“还给”是动词加补语，“了”应放在“还给”之后。这里写成“还了给我”，“了”的位置错误，应说“还给了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f36225b-7c86-43fe-ae39-d16c750ab2cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
