INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91653, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "排在第一个的，最重要的。", "primary_collocate": null, "pronunciation": "shǒu xí", "ipa": "ʂoʊ˨˩ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这次会议的首席顾问是一位退休教授。", "target_word": "首席", "complexity_tier": "T3", "furigana": "zhè cì huì yì de shǒu xí gù wèn shì yí wèi tuì xiū jiào shòu.", "sentence_source": "generated"}, {"text": "今晚的首席嘉宾是一位老作家。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场发布会的首席发言人是公司的总裁。", "target_word": "首席", "complexity_tier": "T3", "furigana": "zhè chǎng fā bù huì de shǒu xí fā yán rén shì gōng sī de zǒng cái.", "sentence_source": "generated"}, {"text": "他被请来当晚会的首席嘉宾。", "target_word": "首席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的首席代言人是一位著名的歌手。", "target_word": "首席", "complexity_tier": "T3", "furigana": "zhè cì huó dòng de shǒu xí dài yán rén shì yí wèi zhù míng de gē shǒu.", "sentence_source": "generated"}, {"text": "他是这次评选的首席评委。", "target_word": "首席", "complexity_tier": "T3", "furigana": "tā shì zhè cì píng xuǎn de shǒu xí píng wěi.", "sentence_source": "generated"}, {"text": "这家医院的首席顾问说：病人需要休息。", "target_word": "首席", "complexity_tier": "T3", "furigana": "zhè jiā yī yuàn de shǒu xí gù wèn shuō: bìng rén xū yào xiū xi.", "sentence_source": "generated"}, {"text": "在这次比赛中，首席裁判是一位女士。", "target_word": "首席", "complexity_tier": "T3", "furigana": "zài zhè cì bǐ sài zhōng, shǒu xí cái pàn shì yí wèi nǚ shì.", "sentence_source": "generated"}, {"text": "首席发言人表示，我们会尽快解决问题。", "target_word": "首席", "complexity_tier": "T3", "furigana": "shǒu xí fā yán rén biǎo shì, wǒ men huì jìn kuài jiě jué wèn tí.", "sentence_source": "generated"}, {"text": "他担任首席代表，负责与各国谈判。", "target_word": "首席", "complexity_tier": "T3", "furigana": "tā dān rèn shǒu xí dài biǎo, fù zé yǔ gè guó tán pàn.", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "首席：排在第一个的、最重要的，如首席任务、首席嘉宾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae461367-2454-4efb-ad9b-fb4db9b634ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91653, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手提", "is_correct": false, "explanation": "tí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着，如手提包。"}, {"text": "首席", "is_correct": true, "explanation": "正确答案。首席指排在第一位、最重要的。"}, {"text": "手旗", "is_correct": false, "explanation": "qí（第二声）与 xí（第二声）只有声母不同，意思是挥动的小旗。"}, {"text": "守时", "is_correct": false, "explanation": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}], "explanations": {"手提": "tí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着，如手提包。", "首席": "正确答案。首席指排在第一位、最重要的。", "手旗": "qí（第二声）与 xí（第二声）只有声母不同，意思是挥动的小旗。", "守时": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}, "sentence_index": null, "correct_answer": "首席"}, "level_3": {"options": [{"text": "首席", "is_correct": true, "explanation": "正确答案。“首席顾问”指会议中居第一位、地位最重要的顾问，与句意相符。"}, {"text": "美容", "is_correct": false, "explanation": "语义：会议请退休教授当顾问，“美容顾问”与这样的会议和身份不相符，句意说不通。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物顾问”与会议请退休教授当顾问的情境不相符，句意说不通。"}, {"text": "洗车", "is_correct": false, "explanation": "语义：“洗车顾问”与会议请退休教授当顾问的情境不相符，句意说不通。"}], "explanations": {"首席": "正确答案。“首席顾问”指会议中居第一位、地位最重要的顾问，与句意相符。", "美容": "语义：会议请退休教授当顾问，“美容顾问”与这样的会议和身份不相符，句意说不通。", "宠物": "语义：“宠物顾问”与会议请退休教授当顾问的情境不相符，句意说不通。", "洗车": "语义：“洗车顾问”与会议请退休教授当顾问的情境不相符，句意说不通。"}, "sentence_index": 0, "correct_answer": "首席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她戴着一套漂亮的首席。", "explanation": "这里应该用〈首饰〉。首席指排在第一位、最重要的人或事，不指戴在身上的饰品；戴的装饰品要说“首饰”。"}, {"text": "我下个月要去首席出差。", "explanation": "这里应该用〈首尔〉，是韩国的城市名。首席指排在第一位、最重要的人或事，不指地点，不能用来说去哪里。"}, {"text": "买房要先交首席。", "explanation": "这里应该用〈首付〉。首席指排在第一位、最重要的人或事，不指购房时先付的款项；先付的那部分款项要说“首付”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91653, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手持", "is_correct": false, "explanation": "chí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着。"}, {"text": "首席", "is_correct": true, "explanation": "正确答案。首席指排在第一位、最重要的。"}, {"text": "手洗", "is_correct": false, "explanation": "xǐ（第三声）与 xí（第二声）只有声调不同，意思是用手洗。"}, {"text": "守时", "is_correct": false, "explanation": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}], "explanations": {"手持": "chí（第二声）与 xí（第二声）只有声母不同，意思是用手拿着。", "首席": "正确答案。首席指排在第一位、最重要的。", "手洗": "xǐ（第三声）与 xí（第二声）只有声调不同，意思是用手洗。", "守时": "shí（第二声）与 xí（第二声）只有声母不同，意思是遵守时间。"}, "sentence_index": null, "correct_answer": "首席"}, "level_3": {"options": [{"text": "首席", "is_correct": true, "explanation": "正确答案。“首席顾问”指医院中地位最重要的顾问，与“说：病人需要休息”相符。"}, {"text": "财务", "is_correct": false, "explanation": "语义：财务顾问不负责医疗建议，不会说“病人需要休息”。"}, {"text": "股票", "is_correct": false, "explanation": "搭配：“股票”限定的顾问指金融咨询，与医院场景不搭配。"}, {"text": "舞蹈", "is_correct": false, "explanation": "语义：舞蹈顾问不会就病人的休息问题发表意见，与医院场景不符。"}], "explanations": {"首席": "正确答案。“首席顾问”指医院中地位最重要的顾问，与“说：病人需要休息”相符。", "财务": "语义：财务顾问不负责医疗建议，不会说“病人需要休息”。", "股票": "搭配：“股票”限定的顾问指金融咨询，与医院场景不搭配。", "舞蹈": "语义：舞蹈顾问不会就病人的休息问题发表意见，与医院场景不符。"}, "sentence_index": 6, "correct_answer": "首席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的首席没电了。", "explanation": "这里应该用〈手机〉。首席指排在第一位、最重要的人或事，不指电子设备，“没电”的只能是手机。"}, {"text": "我最喜欢吃首席。", "explanation": "这里应该用〈寿司〉。首席指排在第一位、最重要的人或事，不指食物；想说的是一种日本食物，应说“寿司”。"}, {"text": "这台机器的首席很长。", "explanation": "这里应该用〈寿命〉。首席指排在第一位、最重要的人或事，不指使用的年限；机器能用多久应说“寿命”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首席讲师是张教授。", "corrected_sentence": "这位首席讲师是张教授。", "error_description": "量词漏掉：指示词“这”后应带量词“位”，说“这位首席讲师”，不能说“这首席讲师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院的首席的顾问很有经验。", "corrected_sentence": "这家医院的首席顾问很有经验。", "error_description": "多加了“的”：“首席”修饰“顾问”时直接连接，不加“的”，应说“首席顾问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
