INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拥有军队并割据一方、争夺权力的人。", "primary_collocate": null, "pronunciation": "jūn fá", "ipa": "tɕyn˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "几个军阀为了争地盘打了很多年仗。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民国时期，各地的军阀互相打仗。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀们都想得到更大的权力。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个军阀不听政府的话，自己管一方。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀打来打去，老百姓过得很苦。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个军阀为了抢城市，打了起来。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师讲了军阀割据的过程。", "target_word": "军阀", "complexity_tier": "T3", "furigana": "lì shǐ kè shàng, lǎo shī jiǎng le jūn fá gē jù de guò chéng.", "sentence_source": "generated"}, {"text": "北方的军阀想抢南方的地方。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位军阀带兵占了三个省。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军阀之间常常先合作，后又打起来。", "target_word": "军阀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "军阀混战", "label": "复合"}, {"form": "軍閥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "拥兵割据一方并互相争夺权力的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfa04d34-6d12-4e16-bb64-7be55add196d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
