= EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军阀", "is_correct": true, "explanation": "军阀指拥兵割据的人，“军阀割据”是常用搭配，与句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不会割据一方，“厨师割据”与历史内容不合。"}, {"text": "歌星", "is_correct": false, "explanation": "语义：歌星不会割据地方，与历史课上讲的内容不合。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“割据”指占据地方、拥兵自立，不与“学校”搭配。"}], "explanations": {"军阀": "军阀指拥兵割据的人，“军阀割据”是常用搭配，与句意相符。", "厨师": "语义：厨师不会割据一方，“厨师割据”与历史内容不合。", "歌星": "语义：歌星不会割据地方，与历史课上讲的内容不合。", "学校": "搭配：“割据”指占据地方、拥兵自立，不与“学校”搭配。"}, "sentence_index": 6, "correct_answer": "军阀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军阀给病人治病。", "explanation": "这里应该用〈医生〉。给病人治病的是医生；军阀指拥兵割据的人，不用来指医务人员。"}, {"text": "军阀在教室里认真听讲。", "explanation": "这里应该用〈学生〉。认真听讲的是学生；军阀不用来指在教室里听课的人。"}, {"text": "军阀在厨房里做饭。", "explanation": "这里应该用〈厨师〉。在厨房做饭的是厨师；军阀不用来指做饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一座军阀带着兵打进了城。", "corrected_sentence": "一个军阀带着兵打进了城。", "error_description": "量词错误：“军阀”指人，应用量词“个”或“位”，“座”用于建筑等，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个的军阀抢了一座城。", "corrected_sentence": "两个军阀抢了一座城。", "error_description": "“的”误加：数量词直接修饰名词时不加“的”，应说“两个军阀”，不说“两个的军阀”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
