INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政府部门或机构（局）的行政负责人。", "primary_collocate": null, "pronunciation": "jú zhǎng", "ipa": "tɕy˧˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "市教育局的局长去学校看了看。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位局长负责全市的交通工作。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长在会上说了新的计划。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三年前成为税务局局长。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问局长一个问题。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区的卫生局局长换人了。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长签了字，文件才能发出去。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长要对全局的工作负责。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民给局长写了一封信。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新局长上个月开始工作。", "target_word": "局长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位局长", "label": "量词搭配"}, {"form": "副局长", "label": "复合"}], "register": "中性", "sense_fingerprint": "政府部门或机构（局）的行政负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局长", "is_correct": true, "explanation": "“局长”是政府部门的行政负责人，与“市教育局的”相符，句子通顺。"}, {"text": "校长", "is_correct": false, "explanation": "搭配：教育局不设“校长”，“市教育局的校长”说不通。"}, {"text": "厂长", "is_correct": false, "explanation": "语义：“厂长”管理工厂，与政府部门“市教育局”无关。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”是企业的负责人，不是政府部门的行政负责人。"}], "explanations": {"局长": "“局长”是政府部门的行政负责人，与“市教育局的”相符，句子通顺。", "校长": "搭配：教育局不设“校长”，“市教育局的校长”说不通。", "厂长": "语义：“厂长”管理工厂，与政府部门“市教育局”无关。", "老板": "语义：“老板”是企业的负责人，不是政府部门的行政负责人。"}, "sentence_index": 0, "correct_answer": "局长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他三年前成为税务处局长。", "explanation": "这里应该用〈处长〉，应说“税务处处长”。“处”是处级机构，其负责人称“处长”，不称“局长”。"}, {"text": "他三年前成为一只税务局局长。", "explanation": "这里应该用〈位〉。指人的“局长”用“位”，“只”多用于动物或成对的物品。"}, {"text": "他三年前成为一家工厂的局长。", "explanation": "这里应该用〈厂长〉。“局长”管政府部门，工厂应用“厂长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局长", "is_correct": true, "explanation": "“局长”有签字权，“局长签了字，文件才能发出去”符合句意。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”不负责签署公文，“厨师签了字”与文件流程无关。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“签字”的主语须是有签字权的人，“小猫”不能签字。"}, {"text": "大树", "is_correct": false, "explanation": "语义：“大树”没有签字的能力，句子说不通。"}], "explanations": {"局长": "“局长”有签字权，“局长签了字，文件才能发出去”符合句意。", "厨师": "语义：“厨师”不负责签署公文，“厨师签了字”与文件流程无关。", "小猫": "配价：“签字”的主语须是有签字权的人，“小猫”不能签字。", "大树": "语义：“大树”没有签字的能力，句子说不通。"}, "sentence_index": 6, "correct_answer": "局长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家银行的新局长上个月开始工作。", "explanation": "这里应该用〈行长〉。“局长”是政府机构的负责人，银行应用“行长”。"}, {"text": "我们学校的新局长上个月来了。", "explanation": "这里应该用〈校长〉。“局长”管政府部门，学校应用“校长”。"}, {"text": "我们单位来了一条新局长。", "explanation": "这里应该用〈位〉。指人的“局长”用“位”，“条”用于细长的东西，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只局长负责全市的文化工作。", "corrected_sentence": "这位局长负责全市的文化工作。", "error_description": "“局长”指人，量词应用“位”，不能用“只”（“只”多用于动物或成对的物品）。应把“这只”改为“这位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一头局长昨天签了字。", "corrected_sentence": "一位局长昨天签了字。", "error_description": "“局长”指人，量词应用“位”；“头”用于牛、猪等动物，不能用于人。应把“一头”改为“一位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91659, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
