INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91659, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己做一做，看看是不是真的。", "primary_collocate": null, "pronunciation": "yàn zhèng", "ipa": "jɛn˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我想自己试试，验证一下他说的话。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不信，就自己去验证了。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说这家店很便宜，我去验证一下。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上说这个方法很好，我来验证一下。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说得对不对，我们一起验证吧。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说这样做菜更好吃，我验证过了，是真的。", "target_word": "验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想亲自验证一下这个消息。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人的话你要自己验证，不要都相信。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用手机验证了一下，他说的是真的。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明不相信水会结冰，就在冰箱里验证了一下。", "target_word": "验证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "验证了", "label": "完成体"}, {"form": "验证过", "label": "经历体"}, {"form": "验证一下", "label": "短时"}], "register": "中性", "sense_fingerprint": "亲自试一试，看别人说的话或消息是不是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa83287-1e2b-4500-b69a-3fd58334cdca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "验证", "is_correct": true, "explanation": "正确。「我想自己试试」之后，要亲自检查他的话，用「验证」。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：「打听」的对象是消息、情况，不说「打听他说的话」。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」与「自己试试」的动作矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：「放弃」表示不再进行，与「自己试试」的意图不符。"}], "explanations": {"验证": "正确。「我想自己试试」之后，要亲自检查他的话，用「验证」。", "打听": "搭配：「打听」的对象是消息、情况，不说「打听他说的话」。", "忘记": "语义：「忘记」与「自己试试」的动作矛盾。", "放弃": "语义：「放弃」表示不再进行，与「自己试试」的意图不符。"}, "sentence_index": 0, "correct_answer": "验证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想验证一下坐飞机的感觉。", "explanation": "这里应该用〈体验〉。「验证」是检查说法或消息的真假，亲身感受要说体验。"}, {"text": "他把那只旧杯子验证了一下。", "explanation": "这里应该用〈擦〉。「验证」用于检查说法或消息的真假，不用于擦拭物品。"}, {"text": "他去花园里验证了一朵花。", "explanation": "这里应该用〈摘〉。「验证」只用于说法或消息，不用于摘花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "验证", "is_correct": true, "explanation": "正确。「亲自」之后、「一下这个消息」之前，要用表示检查真假的「验证」。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：「忽视」表示不予理会，与「亲自」去做的意图相反。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：「赞美」的对象是人或作品，不用于消息。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：「欣赏」的对象是作品、景色，不说「欣赏这个消息」。"}], "explanations": {"验证": "正确。「亲自」之后、「一下这个消息」之前，要用表示检查真假的「验证」。", "忽视": "语义：「忽视」表示不予理会，与「亲自」去做的意图相反。", "赞美": "搭配：「赞美」的对象是人或作品，不用于消息。", "欣赏": "搭配：「欣赏」的对象是作品、景色，不说「欣赏这个消息」。"}, "sentence_index": 6, "correct_answer": "验证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在纸上验证了一只猫。", "explanation": "这里应该用〈画〉。「验证」是亲自试一试、看真假，不用于绘画。"}, {"text": "妈妈在厨房验证了一锅粥。", "explanation": "这里应该用〈煮〉。「验证」不用于烹饪。"}, {"text": "他在舞台上验证了一首歌。", "explanation": "这里应该用〈唱〉。「验证」的对象是说法或消息，不用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息是不是真的，你去把它验证。", "corrected_sentence": "这个消息是不是真的，你去把它验证一下。", "error_description": "错误：「把」字句缺少补语「一下」。正确：「把」字句要有补语，应说「把它验证一下」，只说「验证」句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈亲自把这条新闻验证。", "corrected_sentence": "妈妈亲自把这条新闻验证了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「把这条新闻验证了」，只说「验证」句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
