INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91660, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过检验使事物得到证实。", "primary_collocate": null, "pronunciation": "yàn zhèng", "ipa": "jɛn˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "科学家用实验验证了这个想法。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个结果还需要再验证一次。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想验证自己的猜想是不是对的。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验验证了老师说的话。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用新方法验证了药的作用。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要用数据验证这个办法有没有用。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个理论已经验证过很多次了。", "target_word": "验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师验证了新机器的安全性。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验结果验证了他的看法。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了验证这个公式，学生做了三次实验。", "target_word": "验证", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "验证了", "label": "完成体"}, {"form": "验证过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "用实验、数据等检验方法证实理论、结果或猜想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa83287-1e2b-4500-b69a-3fd58334cdca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "验证", "is_correct": true, "explanation": "正确。「用实验」检验想法，用「验证」，符合语境。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：「讨论」是交流意见，不说「用实验讨论」。"}, {"text": "设计", "is_correct": false, "explanation": "语义：「设计」是创造方案，与检验想法的语境不符。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：「庆祝」是庆贺喜事，与「用实验」检验想法的语境不符。"}], "explanations": {"验证": "正确。「用实验」检验想法，用「验证」，符合语境。", "讨论": "搭配：「讨论」是交流意见，不说「用实验讨论」。", "设计": "语义：「设计」是创造方案，与检验想法的语境不符。", "庆祝": "语义：「庆祝」是庆贺喜事，与「用实验」检验想法的语境不符。"}, "sentence_index": 0, "correct_answer": "验证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生验证了病人的身体。", "explanation": "这里应该用〈检查〉。「验证」用于理论、结果、猜想，不用于检查身体。"}, {"text": "我每天都在验证未来的生活。", "explanation": "这里应该用〈想象〉。「验证」要依据事实或实验来证实，想象未来不能用验证。"}, {"text": "作者把文章的结尾验证成了一首诗。", "explanation": "这里应该用〈改写〉。「验证」是证实真假，不能用来把文字变成诗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "验证", "is_correct": true, "explanation": "正确。「已经……过很多次」说的是反复检验理论，用「验证」。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：「表扬」的对象是人，不用于理论。"}, {"text": "销售", "is_correct": false, "explanation": "搭配：「销售」的对象是商品，理论不能被销售。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」与理论搭配不通，语义不成立。"}], "explanations": {"验证": "正确。「已经……过很多次」说的是反复检验理论，用「验证」。", "表扬": "搭配：「表扬」的对象是人，不用于理论。", "销售": "搭配：「销售」的对象是商品，理论不能被销售。", "吃": "语义：「吃」与理论搭配不通，语义不成立。"}, "sentence_index": 6, "correct_answer": "验证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都验证这幅画，觉得很美。", "explanation": "这里应该用〈欣赏〉。「验证」用于证实对错，不用于审美。"}, {"text": "妈妈验证了这道菜，觉得很好吃。", "explanation": "这里应该用〈品尝〉。「验证」是证实真假，尝菜要说品尝。"}, {"text": "他一边验证音乐，一边睡觉。", "explanation": "这里应该用〈聆听〉。「验证」的对象是说法或结果，不能用于听音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员用实验把这个假设验证。", "corrected_sentence": "研究人员用实验把这个假设验证了。", "error_description": "错误：「把」字句缺少「了」。正确：「把」字句要表示完成的动作，应说「把这个假设验证了」，只说「验证」句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个算法已经验证过很多次着。", "corrected_sentence": "这个算法已经验证过很多次了。", "error_description": "错误：句末体标用错。正确：「验证过很多次」表示经历之后出现了变化，句末应用「了」，应说「验证过很多次了」，不能用「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983e8213-f577-4194-b092-09a3c7d42335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
