INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91661, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赶快跑开，不想被抓到。", "primary_collocate": null, "pronunciation": "táo pǎo", "ipa": "tʰau˧˥ pʰau˨˩˦", "syllable_count": 2, "sentences": [{"text": "小偷看到警察就逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗从院子里逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想逃跑，可是门关着。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫怕人，一见我就逃跑。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人昨天晚上逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别想逃跑，我已经看到你了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听见有人敲门，那个小偷立刻逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷翻过墙，一下子逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要是逃跑，警察会追我们。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他逃跑过一次，后来又被抓回来了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃跑了", "label": "体标（了）"}, {"form": "逃跑过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "赶快跑开，不想被抓到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逃跑", "is_correct": true, "explanation": "“逃跑”指赶快跑开、躲避被抓，与小偷看到警察后的反应相符。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：小偷看到警察后不会去拍照，句子情境不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：看到警察后立刻睡觉与常理相悖，句中没有任何支持。"}, {"text": "请客", "is_correct": false, "explanation": "搭配：“请客”指宴请客人，不能接在“看到警察就……”后面。"}], "explanations": {"逃跑": "“逃跑”指赶快跑开、躲避被抓，与小偷看到警察后的反应相符。", "拍照": "语义：小偷看到警察后不会去拍照，句子情境不合。", "睡觉": "语义：看到警察后立刻睡觉与常理相悖，句中没有任何支持。", "请客": "搭配：“请客”指宴请客人，不能接在“看到警察就……”后面。"}, "sentence_index": 0, "correct_answer": "逃跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我在操场上逃跑了五圈。", "explanation": "这里应该用〈跑〉。逃跑指为躲避危险或追捕而快速跑开，绕操场跑圈只是日常运动，不能用逃跑。"}, {"text": "暑假我们全家逃跑去了海边。", "explanation": "这里应该用〈度假〉。逃跑指为躲避危险或追捕而快速跑开，全家去海边休息要说度假。"}, {"text": "下课以后，我们都逃跑回家了。", "explanation": "这里应该用〈走〉。逃跑含有躲避危险或追捕的意思，正常下课后走回家即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃跑", "is_correct": true, "explanation": "“逃跑”指听到敲门后赶快跑开，与“立刻”的紧急反应相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：听见有人敲门后立刻唱歌，不符合小偷慌张的心理。"}, {"text": "洗碗", "is_correct": false, "explanation": "搭配：“洗碗”是家务动作，不能接在“听见有人敲门”和“立刻”后面。"}, {"text": "写字", "is_correct": false, "explanation": "语义：小偷被敲门声惊动，不会立刻坐下来写字。"}], "explanations": {"逃跑": "“逃跑”指听到敲门后赶快跑开，与“立刻”的紧急反应相符。", "唱歌": "语义：听见有人敲门后立刻唱歌，不符合小偷慌张的心理。", "洗碗": "搭配：“洗碗”是家务动作，不能接在“听见有人敲门”和“立刻”后面。", "写字": "语义：小偷被敲门声惊动，不会立刻坐下来写字。"}, "sentence_index": 6, "correct_answer": "逃跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵们有秩序地逃跑到了后方。", "explanation": "这里应该用〈撤退〉。逃跑带有慌乱、不顾一切的意思，有秩序地后撤要用撤退。"}, {"text": "吃完早饭，我们就逃跑去学校了。", "explanation": "这里应该用〈出发〉。逃跑表示躲避危险或追捕，平常去学校要说出发。"}, {"text": "周末我们在公园里逃跑了一下午。", "explanation": "这里应该用〈游玩〉。逃跑是快速跑开躲避的意思，不能形容悠闲地玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小偷趁乱被逃跑了。", "corrected_sentence": "那个小偷趁乱逃跑了。", "error_description": "被字句错误：“逃跑”是不及物动词，不能用“被”字句，“被”应去掉。正确形式是“那个小偷趁乱逃跑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看见门口有警察，没逃跑了。", "corrected_sentence": "他看见门口有警察，没逃跑。", "error_description": "“没”和“了”不能同用，否定句中“逃跑”后面不加“了”。正确形式是“没逃跑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
