INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91662, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为躲避危险或追捕而跑开。", "primary_collocate": null, "pronunciation": "táo pǎo", "ipa": "tʰau˧˥ pʰau˨˩˦", "syllable_count": 2, "sentences": [{"text": "地震的时候，大家都逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到大火，孩子们吓得逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子看见狼，赶紧逃跑。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人打不过我们，只好逃跑。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从危险的地方逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎来了，小鹿快逃跑吧。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到坏人，他没有逃跑，而是大声喊人。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物们看到火，都向森林外逃跑。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人为了躲开警察，连夜逃跑。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把东西丢下，逃跑了。", "target_word": "逃跑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃跑了", "label": "体标（了）"}, {"form": "逃跑过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "为躲避危险或追捕而跑开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逃跑", "is_correct": true, "explanation": "“逃跑”指为躲避危险而跑开，与“地震的时候”的情境相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：地震发生时大家跳舞，与危险情境相悖。"}, {"text": "打牌", "is_correct": false, "explanation": "语义：地震时大家还去打牌，不合常理。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”需要私人空间，不能用在“地震的时候，大家都……”这样的集体反应中。"}], "explanations": {"逃跑": "“逃跑”指为躲避危险而跑开，与“地震的时候”的情境相符。", "跳舞": "语义：地震发生时大家跳舞，与危险情境相悖。", "打牌": "语义：地震时大家还去打牌，不合常理。", "洗澡": "搭配：“洗澡”需要私人空间，不能用在“地震的时候，大家都……”这样的集体反应中。"}, "sentence_index": 0, "correct_answer": "逃跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国庆节我们全家逃跑去了云南。", "explanation": "这里应该用〈旅游〉。逃跑指为躲避危险或追捕而快速跑开，全家去云南玩要说旅游。"}, {"text": "夏天我每天在河里逃跑。", "explanation": "这里应该用〈游泳〉。逃跑指为躲避危险而跑开，夏天在河里游水要说游泳。"}, {"text": "他每天早上在河边逃跑。", "explanation": "这里应该用〈锻炼〉。逃跑指为躲避危险而跑开，每天早上在河边跑步只是锻炼身体，不能用逃跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃跑", "is_correct": true, "explanation": "“逃跑”指躲开危险而跑开，与“没有……而是大声喊人”形成对比，正是要表达的意思。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：遇到坏人时，“唱歌”不是与“大声喊人”相对的应对方式，语境搭不上。"}, {"text": "打球", "is_correct": false, "explanation": "语义：遇到坏人时去打球，与“大声喊人”不构成对比，句意说不通。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：遇到坏人时去下棋，情境完全不合。"}], "explanations": {"逃跑": "“逃跑”指躲开危险而跑开，与“没有……而是大声喊人”形成对比，正是要表达的意思。", "唱歌": "搭配：遇到坏人时，“唱歌”不是与“大声喊人”相对的应对方式，语境搭不上。", "打球": "语义：遇到坏人时去打球，与“大声喊人”不构成对比，句意说不通。", "下棋": "语义：遇到坏人时去下棋，情境完全不合。"}, "sentence_index": 6, "correct_answer": "逃跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭后我们一起逃跑去公园。", "explanation": "这里应该用〈散步〉。逃跑表示躲避危险，饭后悠闲去公园要说散步。"}, {"text": "下课后，学生们逃跑出了教室。", "explanation": "这里应该用〈走〉。逃跑含有躲避的意思，正常下课后学生走出教室要用走。"}, {"text": "我们吃完早饭，逃跑去车站。", "explanation": "这里应该用〈出发〉。逃跑指躲避危险而跑开，去车站要说出发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家听见警报，都把逃跑了。", "corrected_sentence": "大家听见警报，都逃跑了。", "error_description": "“逃跑”是不及物动词，不能用“把”字结构。“把”应去掉，正确形式是“都逃跑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只老鼠看见猫，立刻逃跑着。", "corrected_sentence": "那只老鼠看见猫，立刻逃跑了。", "error_description": "体标错误：“着”表示动作持续进行的状态，与“立刻”表示的瞬间突发动作不搭；此处应用“了”表示完成，正确形式是“立刻逃跑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
