INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "市区是城市里人最多、房子最多的那一块。", "primary_collocate": null, "pronunciation": "shì qū", "ipa": "ʂɻ̩˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "市区的房子又高又多。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在市区，上班很方便。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区的人特别多，路上很堵。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天开车进市区上班。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区里有很多商店和饭馆。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区的房价比别的地方贵。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从机场到市区要一个小时。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去市区逛街。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区晚上很热闹，灯也很多。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司在市区的一栋高楼里。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "城市里人和房子最多、最热闹的那一块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市区", "is_correct": true, "explanation": "正确答案。市区 shì qū 指城市里人和房子最多的地方。"}, {"text": "时区", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是时区，不是市区。"}, {"text": "失去", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。"}, {"text": "拾取", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）、qǔ（第三声）与 qū（第一声）声调不同，意思是拾取。"}, {"text": "识趣", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调不同，意思是懂得分寸。"}], "explanations": {"市区": "正确答案。市区 shì qū 指城市里人和房子最多的地方。", "时区": "shí（第二声）与 shì（第四声）声调不同，意思是时区，不是市区。", "失去": "shī（第一声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。", "拾取": "shí（第二声）与 shì（第四声）、qǔ（第三声）与 qū（第一声）声调不同，意思是拾取。", "识趣": "shí（第二声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调不同，意思是懂得分寸。"}, "sentence_index": null, "correct_answer": "市区"}, "level_3": {"options": [{"text": "森林", "is_correct": false, "explanation": "语义：森林里几乎没有成片的房子，与“房子又高又多”明显矛盾。"}, {"text": "市区", "is_correct": true, "explanation": "市区：城市里人和房子最集中的地方，符合“又高又多”。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原上很少有高楼和成片的房子，与“又高又多”不符。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“公园”不能与“房子又高又多”搭配，公园里不说有很多房子。"}], "explanations": {"森林": "语义：森林里几乎没有成片的房子，与“房子又高又多”明显矛盾。", "市区": "市区：城市里人和房子最集中的地方，符合“又高又多”。", "草原": "语义：草原上很少有高楼和成片的房子，与“又高又多”不符。", "公园": "搭配：“公园”不能与“房子又高又多”搭配，公园里不说有很多房子。"}, "sentence_index": 0, "correct_answer": "市区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爷爷一辈子住在市区，每天赶着羊群上山。", "explanation": "这里应该用〈农村〉。市区是城市里人口和建筑集中的地方，赶羊上山是农村的生活，不说住在市区。"}, {"text": "周末我们去市区摘棉花，空气很好。", "explanation": "这里应该用〈田里〉。摘棉花要去田地，市区是城市建成区，不说去市区摘棉花。"}, {"text": "奶奶在市区挖了一口井，每天都去打水。", "explanation": "这里应该用〈乡下〉。市区是城市建成区，挖井打水是乡下的生活，不说在市区挖井。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书", "is_correct": false, "explanation": "语义：书不是地点，“从机场到书”说不通，句子说的是交通时间。"}, {"text": "市区", "is_correct": true, "explanation": "市区：城市里人和房子集中的地方，可以作为“到”的终点。"}, {"text": "飞机", "is_correct": false, "explanation": "配价：“到”后面要接地点，“飞机”是物体，不能作为“从机场到”的终点。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以到达的地方，与“从机场到”的地点语境不符。"}], "explanations": {"书": "语义：书不是地点，“从机场到书”说不通，句子说的是交通时间。", "市区": "市区：城市里人和房子集中的地方，可以作为“到”的终点。", "飞机": "配价：“到”后面要接地点，“飞机”是物体，不能作为“从机场到”的终点。", "空气": "语义：空气不是可以到达的地方，与“从机场到”的地点语境不符。"}, "sentence_index": 6, "correct_answer": "市区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在市区养了很多牛，每天都很忙。", "explanation": "这里应该用〈农场〉。养牛要在农场、牧场，不说在市区养牛。"}, {"text": "他们开垦了一大片市区，准备种菜。", "explanation": "这里应该用〈荒地〉。开垦针对的是荒地，市区是城市建成区，不能被开垦。"}, {"text": "这个市区一共有二十多个省，面积很大。", "explanation": "这里应该用〈国家〉。市区是城市内部的一片地区，不包含省份，说有二十多个省要用〈国家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候去着市区。", "corrected_sentence": "我小时候去过市区。", "error_description": "“去着市区”错误。“着”表示持续，不表示曾经有过的经历，要用“过”，应说“去过市区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈市区的医院工作。", "corrected_sentence": "妈妈在市区的医院工作。", "error_description": "漏掉“在”。“市区”作处所，前面要加介词“在”，应说“在市区的医院工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
