INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91664, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中人口和建筑集中的区域，与郊区相对。", "primary_collocate": null, "pronunciation": "shì qū", "ipa": "ʂɻ̩˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "市区很热闹，郊区很安静。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从郊区搬到了市区。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区的空气不如郊区好。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线通到市区。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区内不让大货车进来。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在市区上班，住在郊区。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区的路比郊区的路多。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区的学校比郊区的多。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐公交车去了市区。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市区停车很难，车位也贵。", "target_word": "市区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "城市中人口和建筑集中的区域，与郊区相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市区", "is_correct": true, "explanation": "正确答案。市区 shì qū 指城市中人口和建筑集中的区域。"}, {"text": "时区", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是时区，不是市区。"}, {"text": "失去", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。"}, {"text": "拾取", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）、qǔ（第三声）与 qū（第一声）声调不同，意思是拾取。"}, {"text": "识趣", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调不同，意思是懂得分寸。"}], "explanations": {"市区": "正确答案。市区 shì qū 指城市中人口和建筑集中的区域。", "时区": "shí（第二声）与 shì（第四声）声调不同，意思是时区，不是市区。", "失去": "shī（第一声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调都不同，意思是失去。", "拾取": "shí（第二声）与 shì（第四声）、qǔ（第三声）与 qū（第一声）声调不同，意思是拾取。", "识趣": "shí（第二声）与 shì（第四声）、qù（第四声）与 qū（第一声）声调不同，意思是懂得分寸。"}, "sentence_index": null, "correct_answer": "市区"}, "level_3": {"options": [{"text": "深山", "is_correct": false, "explanation": "语义：深山通常人少、很安静，与“很热闹”相矛盾。"}, {"text": "郊区", "is_correct": false, "explanation": "语义：句中已说“郊区很安静”，若也说“郊区很热闹”，前后矛盾。"}, {"text": "市区", "is_correct": true, "explanation": "市区：城市中人口和建筑集中的区域，与郊区相对，符合“很热闹”。"}, {"text": "荒野", "is_correct": false, "explanation": "搭配：“热闹”多用于人多的地方，一般不说荒野很热闹。"}], "explanations": {"深山": "语义：深山通常人少、很安静，与“很热闹”相矛盾。", "郊区": "语义：句中已说“郊区很安静”，若也说“郊区很热闹”，前后矛盾。", "市区": "市区：城市中人口和建筑集中的区域，与郊区相对，符合“很热闹”。", "荒野": "搭配：“热闹”多用于人多的地方，一般不说荒野很热闹。"}, "sentence_index": 0, "correct_answer": "市区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个市区下面有二十多个县，每个县都很大。", "explanation": "这里应该用〈省〉。市区是城市内部的区域，不包含县，说下面管辖二十多个县要用〈省〉。"}, {"text": "市区里有成群的骆驼，风景很特别。", "explanation": "这里应该用〈沙漠〉。市区是城市建成区，不会有成群的骆驼，骆驼一般生活在沙漠。"}, {"text": "我们每年秋天都去市区采蘑菇。", "explanation": "这里应该用〈山上〉。采蘑菇要去山林，不说去市区采蘑菇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荒漠", "is_correct": false, "explanation": "语义：荒漠里几乎没有路，与“路比郊区的路多”矛盾。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林里的路通常比城区少，“比郊区的路多”不成立。"}, {"text": "市区", "is_correct": true, "explanation": "市区：城市中人口和建筑集中的区域，路自然比郊区多。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：“草原”与“路多”不搭配，草原上一般路少，不说路多。"}], "explanations": {"荒漠": "语义：荒漠里几乎没有路，与“路比郊区的路多”矛盾。", "森林": "语义：森林里的路通常比城区少，“比郊区的路多”不成立。", "市区": "市区：城市中人口和建筑集中的区域，路自然比郊区多。", "草原": "搭配：“草原”与“路多”不搭配，草原上一般路少，不说路多。"}, "sentence_index": 6, "correct_answer": "市区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在市区养了很多牛，每天都很忙。", "explanation": "这里应该用〈农场〉。养牛要在农场、牧场，不说在市区养牛。"}, {"text": "他们开垦了一大片市区，准备种菜。", "explanation": "这里应该用〈荒地〉。开垦针对的是荒地，市区是城市建成区，不能被开垦。"}, {"text": "这个市区的人口有十几亿，边境线很长。", "explanation": "这里应该用〈国家〉。市区是城市内部的一片地区，不会有十几亿人口和边境线，说这些要用〈国家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就住了在市区。", "corrected_sentence": "他从小就住在市区。", "error_description": "“了”放错位置。“住在”之间不能插入“了”，应说“他从小就住在市区。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他全家都爬到市区了。", "corrected_sentence": "他全家都搬到市区了。", "error_description": "动词错误。“爬”表示攀登，不能用于全家迁居，应说“搬到市区了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
