INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山上最高的地方。", "primary_collocate": null, "pronunciation": "gāo fēng", "ipa": "kɑʊ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这座山的高峰有三千米高。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们终于爬到了山的高峰。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高峰上有很多雪，天气非常冷。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在高峰上，可以看到远处的云。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处那座高峰，一年四季都有白雪。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们爬了一天，才走到这座山的高峰。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很好，我在高峰上拍了很多照片。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的高峰很高，爬山的人要带上厚衣服。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳出来的时候，高峰先亮了。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的高峰常常在云里，很难看清。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一座山最高、最尖的那一处山峰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方。"}, {"text": "高分", "is_correct": false, "explanation": "fēn（第一声）与 fēng（第一声）韵尾不同（-n 与 -ng），意思是高分，即分数高。"}, {"text": "刀锋", "is_correct": false, "explanation": "dāo 与 gāo 声母不同（d 与 g），意思是刀刃的锋利部分。"}, {"text": "交锋", "is_correct": false, "explanation": "jiāo 与 gāo 声母不同（j 与 g），意思是双方交战或激烈辩论。"}], "explanations": {"高峰": "高峰：山上最高的地方。", "高分": "fēn（第一声）与 fēng（第一声）韵尾不同（-n 与 -ng），意思是高分，即分数高。", "刀锋": "dāo 与 gāo 声母不同（d 与 g），意思是刀刃的锋利部分。", "交锋": "jiāo 与 gāo 声母不同（j 与 g），意思是双方交战或激烈辩论。"}, "sentence_index": null, "correct_answer": "高峰"}, "level_3": {"options": [{"text": "山谷", "is_correct": false, "explanation": "语义：“山谷”是两山之间的低洼处，说它“有三千米高”不合常理。"}, {"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方，与“有三千米高”的高度描述相符。"}, {"text": "山洞", "is_correct": false, "explanation": "语义：“山洞”是山体内部的空间，不能说它“有三千米高”，句子说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是水流的通道，不能说它“有三千米高”，句子说不通。"}], "explanations": {"山谷": "语义：“山谷”是两山之间的低洼处，说它“有三千米高”不合常理。", "高峰": "高峰：山上最高的地方，与“有三千米高”的高度描述相符。", "山洞": "语义：“山洞”是山体内部的空间，不能说它“有三千米高”，句子说不通。", "河流": "语义：“河流”是水流的通道，不能说它“有三千米高”，句子说不通。"}, "sentence_index": 0, "correct_answer": "高峰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的事业终于到了高峰，然后慢慢下降。", "explanation": "句中的高峰用的是抽象义（事物发展的最高点），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "这部电影的票房到了高峰。", "explanation": "句中的高峰用的是抽象义（数量或水平达到的最高点），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "考试期间是学习的高峰，图书馆里挤满了人。", "explanation": "句中的高峰用的是抽象义（最忙的阶段），与本词条指山上最高的地方不同，不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方。"}, {"text": "高僧", "is_correct": false, "explanation": "sēng 与 fēng 声母不同（s 与 f），意思是德高望重的僧人。"}, {"text": "高飞", "is_correct": false, "explanation": "fēi 与 fēng 韵尾不同（-i 与 -ng），意思是高高地飞。"}, {"text": "高分", "is_correct": false, "explanation": "fēn 与 fēng 韵尾不同（-n 与 -ng），意思是分数高。"}], "explanations": {"高峰": "高峰：山上最高的地方。", "高僧": "sēng 与 fēng 声母不同（s 与 f），意思是德高望重的僧人。", "高飞": "fēi 与 fēng 韵尾不同（-i 与 -ng），意思是高高地飞。", "高分": "fēn 与 fēng 韵尾不同（-n 与 -ng），意思是分数高。"}, "sentence_index": null, "correct_answer": "高峰"}, "level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”是天体，人不能“在太阳上”拍照，句子说不通。"}, {"text": "春天", "is_correct": false, "explanation": "配价：“在……上”需要处所，“春天”是时间，不能作站立或拍照的地点。"}, {"text": "高峰", "is_correct": true, "explanation": "高峰：山上最高的地方，人可以站在上面拍照。"}, {"text": "冬天", "is_correct": false, "explanation": "配价：“在……上”需要处所，“冬天”是时间，不能作拍照的地点。"}], "explanations": {"太阳": "语义：“太阳”是天体，人不能“在太阳上”拍照，句子说不通。", "春天": "配价：“在……上”需要处所，“春天”是时间，不能作站立或拍照的地点。", "高峰": "高峰：山上最高的地方，人可以站在上面拍照。", "冬天": "配价：“在……上”需要处所，“冬天”是时间，不能作拍照的地点。"}, "sentence_index": 6, "correct_answer": "高峰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的购物高峰比去年来得早。", "explanation": "句中的高峰用的是抽象义（最忙的购物阶段），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "春运的客流已经到了高峰。", "explanation": "句中的高峰用的是抽象义（人流最多的阶段），与本词条指山上最高的地方不同，不符合本义。"}, {"text": "两国的高峰会谈定在下个月举行。", "explanation": "高峰在这里指“首脑级别的会议”（高峰会），与本词条“山上最高的地方”不同，不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山有一条高峰，常年有雪。", "corrected_sentence": "这座山有一座高峰，常年有雪。", "error_description": "量词误用：山峰应搭配量词“座”；“条”多用于河流、道路等长条形事物，说“一条高峰”不符合习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条高峰很陡，不好爬。", "corrected_sentence": "那座高峰很陡，不好爬。", "error_description": "量词误用：“高峰”指山顶，应搭配量词“座”；“条”多用于河流、道路等长条形事物，说“那条高峰”不符合习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低谷", "is_correct": true, "explanation": "低谷与高峰构成反义：高峰指发展或数量的最高点，低谷指最低点。"}, {"text": "起点", "is_correct": false, "explanation": "起点指开始的地方，与“最高点”不构成反义。"}, {"text": "中段", "is_correct": false, "explanation": "中段指中间的部分，与高峰不构成反义。"}, {"text": "边缘", "is_correct": false, "explanation": "边缘指事物的外沿，与高峰不构成反义。"}], "correct_answer": "低谷", "explanations": {"低谷": "低谷与高峰构成反义：高峰指发展或数量的最高点，低谷指最低点。", "起点": "起点指开始的地方，与“最高点”不构成反义。", "中段": "中段指中间的部分，与高峰不构成反义。", "边缘": "边缘指事物的外沿，与高峰不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低谷", "is_correct": true, "explanation": "低谷与高峰构成反义：高峰指发展或数量的最高点，低谷指最低点。"}, {"text": "开端", "is_correct": false, "explanation": "开端指事情的起头，与高峰不构成反义。"}, {"text": "中期", "is_correct": false, "explanation": "中期指中间的时期，与高峰不构成反义。"}, {"text": "边界", "is_correct": false, "explanation": "边界指地区或事物的分界线，与高峰不构成反义。"}], "correct_answer": "低谷", "explanations": {"低谷": "低谷与高峰构成反义：高峰指发展或数量的最高点，低谷指最低点。", "开端": "开端指事情的起头，与高峰不构成反义。", "中期": "中期指中间的时期，与高峰不构成反义。", "边界": "边界指地区或事物的分界线，与高峰不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻事物发展或数量达到的最高点，也指人流、车流最多的阶段。", "primary_collocate": null, "pronunciation": "gāo fēng", "ipa": "kɑʊ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "早上八点是上班的高峰，路上车很多。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位歌手的名气已经到了高峰。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上六点，地铁站里的人数达到了高峰。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前，火车票的买票高峰又来了。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三十岁时事业到了高峰，后来慢慢下来了。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的游客在夏天会出现高峰。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要避开高峰，换个时间出门。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个运动员二十五岁时，成绩到达了高峰。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的唐朝是诗歌发展的高峰。", "target_word": "高峰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影的票房很快到了高峰，然后慢慢下降。", "target_word": "高峰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高峰期", "label": "复合"}], "register": "中性", "sense_fingerprint": "比喻事物发展或数量达到的最高点、最多最忙的阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高峰", "is_correct": true, "explanation": "高峰：事物发展的最高点，或人流、车流最多的时段。"}, {"text": "高分", "is_correct": false, "explanation": "fēn（第一声）与 fēng（第一声）韵尾不同（-n 与 -ng），意思是高分，即分数高。"}, {"text": "刀锋", "is_correct": false, "explanation": "dāo 与 gāo 声母不同（d 与 g），意思是刀刃的锋利部分。"}, {"text": "交锋", "is_correct": false, "explanation": "jiāo 与 gāo 声母不同（j 与 g），意思是双方交战或激烈辩论。"}], "explanations": {"高峰": "高峰：事物发展的最高点，或人流、车流最多的时段。", "高分": "fēn（第一声）与 fēng（第一声）韵尾不同（-n 与 -ng），意思是高分，即分数高。", "刀锋": "dāo 与 gāo 声母不同（d 与 g），意思是刀刃的锋利部分。", "交锋": "jiāo 与 gāo 声母不同（j 与 g），意思是双方交战或激烈辩论。"}, "sentence_index": null, "correct_answer": "高峰"}, "level_3": {"options": [{"text": "低谷", "is_correct": false, "explanation": "语义：“低谷”指事物最低、最萧条的阶段，与“路上车很多”的繁忙情形相反。"}, {"text": "高峰", "is_correct": true, "explanation": "高峰：人、车最多的时段，与“上班”和“路上车很多”一致。"}, {"text": "淡季", "is_correct": false, "explanation": "搭配：“淡季”多指销售、旅游等行业的冷清季节，不能用来指一天中的时段。"}, {"text": "山峰", "is_correct": false, "explanation": "语义：“山峰”指具体的山顶，不能用来指上班的时间段。"}], "explanations": {"低谷": "语义：“低谷”指事物最低、最萧条的阶段，与“路上车很多”的繁忙情形相反。", "高峰": "高峰：人、车最多的时段，与“上班”和“路上车很多”一致。", "淡季": "搭配：“淡季”多指销售、旅游等行业的冷清季节，不能用来指一天中的时段。", "山峰": "语义：“山峰”指具体的山顶，不能用来指上班的时间段。"}, "sentence_index": 0, "correct_answer": "高峰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国领导人下周要举行高峰会谈。", "explanation": "高峰在这里指“首脑级别的会议”（高峰会），与本词条“事物发展的最高点”不同，不符合本词条的用法。"}, {"text": "我们爬上了这座山的高峰，看到了整片云海。", "explanation": "这里的高峰指山上最高的地方，是具体的地点义，与“事物发展的最高点”不同，不符合本词条在句中的用法。"}, {"text": "这座大楼的高峰是一百米。", "explanation": "这里应该用〈高度〉。高峰指山顶或事物发展的最高点，不用来说建筑的高矮；说楼的高矮应用高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高峰", "is_correct": true, "explanation": "高峰：事物发展的最高点，或人流、车流最多的时段。"}, {"text": "高僧", "is_correct": false, "explanation": "sēng 与 fēng 声母不同（s 与 f），意思是德高望重的僧人。"}, {"text": "高升", "is_correct": false, "explanation": "shēng 与 fēng 声母不同（sh 与 f），意思是职位或地位提高。"}, {"text": "高飞", "is_correct": false, "explanation": "fēi 与 fēng 韵尾不同（-i 与 -ng），意思是高高地飞。"}], "explanations": {"高峰": "高峰：事物发展的最高点，或人流、车流最多的时段。", "高僧": "sēng 与 fēng 声母不同（s 与 f），意思是德高望重的僧人。", "高升": "shēng 与 fēng 声母不同（sh 与 f），意思是职位或地位提高。", "高飞": "fēi 与 fēng 韵尾不同（-i 与 -ng），意思是高高地飞。"}, "sentence_index": null, "correct_answer": "高峰"}, "level_3": {"options": [{"text": "山腰", "is_correct": false, "explanation": "语义：“山腰”指山的中间部位，与“换个时间出门”无关，句子语义说不通。"}, {"text": "尽头", "is_correct": false, "explanation": "搭配：“避开”后接的是需要绕过的情况，“尽头”指终点，不能用“避开”来搭配。"}, {"text": "高峰", "is_correct": true, "explanation": "高峰：人最多、最拥挤的时段，与“避开”和“换个时间出门”相符。"}, {"text": "谷底", "is_correct": false, "explanation": "语义：“谷底”指山谷的最低处，是地点，不是可以“避开”的时段或情况。"}], "explanations": {"山腰": "语义：“山腰”指山的中间部位，与“换个时间出门”无关，句子语义说不通。", "尽头": "搭配：“避开”后接的是需要绕过的情况，“尽头”指终点，不能用“避开”来搭配。", "高峰": "高峰：人最多、最拥挤的时段，与“避开”和“换个时间出门”相符。", "谷底": "语义：“谷底”指山谷的最低处，是地点，不是可以“避开”的时段或情况。"}, "sentence_index": 6, "correct_answer": "高峰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三角形的高峰有三个。", "explanation": "这里应该用〈顶点〉。高峰指山顶或事物发展的最高点，不指几何图形的角；三角形的角叫顶点。"}, {"text": "这座山的高峰上常年有雪，爬山的人要带厚衣服。", "explanation": "这里的高峰指山顶，是具体的地点义，与“事物发展的最高点”不同，不符合本词条在句中的用法。"}, {"text": "他去年考上了高峰。", "explanation": "这里应该用〈高中〉。高峰指山顶或事物发展的最高点，不指学校的阶段；考上的是高中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春运的这座高峰已经过去了。", "corrected_sentence": "春运的这个高峰已经过去了。", "error_description": "量词误用：“高峰”指抽象的最忙时段，应搭配量词“个”；“座”用于山、楼等大型固定物，说“这座高峰”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车流很快就达了到高峰。", "corrected_sentence": "车流很快就达到了高峰。", "error_description": "错误：补语“到”与动词“达”分开，写成了“达了到”。正确：“到”须紧跟“达”，写作“达到了高峰”，“了”放在“达到”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
