INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91667, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重来是再来一次。", "primary_collocate": null, "pronunciation": "chóng lái", "ipa": "ʈʂʰʊŋ˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这次不算，我们重来一次。", "target_word": "重来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "画错了，我只好重来。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏输了，你可以选择重来。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这份作业不合格，让他重来一遍。", "target_word": "重来", "complexity_tier": "T3", "furigana": "lǎo shī shuō zhè fèn zuò yè bù hé gé, ràng tā chóng lái yí biàn.", "sentence_source": "generated"}, {"text": "这道菜太咸了，只能重来。", "target_word": "重来", "complexity_tier": "T3", "furigana": "zhè dào cài tài xián le, zhǐ néng chóng lái.", "sentence_source": "generated"}, {"text": "球没进，裁判让大家重来一次。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑突然关机，我只好从头重来。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他唱错了一句，乐队只好重来。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摄影师不满意，让大家重来了三次。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片没拍好，我们重来吧。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "重来了", "label": "体标（了）"}, {"form": "重来过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "重来|做错或不满意后再做一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91667, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重来", "is_correct": true, "explanation": "正确：“重来”是再做一次，与“这次不算”相呼应。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”表示做成了，与“这次不算”的意思相矛盾。"}, {"text": "参加", "is_correct": false, "explanation": "语义：“参加”指加入某项活动，与“这次不算，我们……一次”的语境不合。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：“结束”一般接活动、比赛，不说“结束一次”。"}], "explanations": {"重来": "正确：“重来”是再做一次，与“这次不算”相呼应。", "完成": "语义：“完成”表示做成了，与“这次不算”的意思相矛盾。", "参加": "语义：“参加”指加入某项活动，与“这次不算，我们……一次”的语境不合。", "结束": "搭配：“结束”一般接活动、比赛，不说“结束一次”。"}, "sentence_index": 0, "correct_answer": "重来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个错误很容易重来。", "explanation": "这里应该用〈改正〉。重来指整件事从头再做一遍，改正局部错误只需修正，不必重做。"}, {"text": "他下个月从国外重来，我们一起吃饭。", "explanation": "这里应该用〈回来〉。重来指把已做的事再做一遍，不用于人从国外返回。"}, {"text": "老师让学生重来那位同学。", "explanation": "这里应该用〈叫〉。重来的对象是已做的事，不能是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重来", "is_correct": true, "explanation": "正确：“重来”指从头再做，与“从头”以及电脑关机后只能重做的语境相合。"}, {"text": "休息", "is_correct": false, "explanation": "语义：“休息”与电脑关机后的重做无关，“从头休息”说不通。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指人睡不着，不能用于电脑操作的语境。"}, {"text": "答应", "is_correct": false, "explanation": "配价：“答应”需要说明答应的对象或内容，这里后面没有宾语，句意不通。"}], "explanations": {"重来": "正确：“重来”指从头再做，与“从头”以及电脑关机后只能重做的语境相合。", "休息": "语义：“休息”与电脑关机后的重做无关，“从头休息”说不通。", "失眠": "语义：“失眠”指人睡不着，不能用于电脑操作的语境。", "答应": "配价：“答应”需要说明答应的对象或内容，这里后面没有宾语，句意不通。"}, "sentence_index": 6, "correct_answer": "重来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨停了，我们重来往前走。", "explanation": "这里应该用〈继续〉。重来指把已做的事从头再做一遍，不表示接着往下做。"}, {"text": "他想重来丢失的钱包。", "explanation": "这里应该用〈找回〉。重来指把已做的事从头再做一遍，不表示把丢失的东西重新拿回来。"}, {"text": "这家店准备重来两个服务员。", "explanation": "这里应该用〈增加〉。重来表示再做一遍，不能用来表示增加人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张海报的颜色不对，设计师只好从头了重来。", "corrected_sentence": "这张海报的颜色不对，设计师只好从头重来。", "error_description": "体标位置错误：“了”不能插在状语“从头”和动词“重来”之间。应说“从头重来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次拍摄的光线太暗，摄影师只好重来一个。", "corrected_sentence": "这次拍摄的光线太暗，摄影师只好重来一遍。", "error_description": "量词错误：“重来”表示再做一遍，动作的量词应用“遍”或“次”，不能用“个”。应说“重来一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
