INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91668, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91668, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重来指时间、机会等一去之后再次到来。", "primary_collocate": null, "pronunciation": "chóng lái", "ipa": "ʈʂʰʊŋ˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "时间不会重来。", "target_word": "重来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人生不能重来。", "target_word": "重来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "青春一去，就不会重来。", "target_word": "重来", "complexity_tier": "T3", "furigana": "qīng chūn yí qù, jiù bú huì chóng lái.", "sentence_source": "generated"}, {"text": "这样的好机会不会重来。", "target_word": "重来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "历史不能重来，我们要珍惜现在。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "童年的夏天，再也不会重来。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他错过的那次机会，再也不会重来了。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去的日子再也不能重来了。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天年年重来，人却一年比一年老了。", "target_word": "重来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的好运没有重来过。", "target_word": "重来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重来了", "label": "体标（了）"}, {"form": "重来过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "重来|时间机会一去之后再次到来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重来", "is_correct": true, "explanation": "正确：“时间不会重来”指时间一去不再回来，是“再次到来”的意思。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”需要有生命的主体，时间不会吃饭。"}, {"text": "写字", "is_correct": false, "explanation": "搭配：“写字”的主体是能动笔的人，不能搭配“时间”作主语。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指人或动物的身体状况，与“时间”不相符。"}], "explanations": {"重来": "正确：“时间不会重来”指时间一去不再回来，是“再次到来”的意思。", "吃饭": "语义：“吃饭”需要有生命的主体，时间不会吃饭。", "写字": "搭配：“写字”的主体是能动笔的人，不能搭配“时间”作主语。", "生病": "语义：“生病”指人或动物的身体状况，与“时间”不相符。"}, "sentence_index": 0, "correct_answer": "重来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的旧朋友终于重来他的生活。", "explanation": "这里应该用〈进入〉。重来表示时间、机会等再次到来，不表示人进入别人的生活。"}, {"text": "他把丢了的书包重来了。", "explanation": "这里应该用〈找回〉。重来表示时间、机会等再次到来，不表示把丢失的东西拿回来。"}, {"text": "他把钥匙重来好了。", "explanation": "这里应该用〈保管〉。重来表示时间、机会等再次到来，不表示把东西妥善保存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重来", "is_correct": true, "explanation": "正确：“重来”指时间、机会一去不再回来，与“错过”以及“再也不会”相合。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”需要有意志的主体，班车不能作“放弃”的主体，句意不通。"}, {"text": "答应", "is_correct": false, "explanation": "配价：“答应”需要有意志的人作主语，班车无法答应，句意不通。"}, {"text": "回答", "is_correct": false, "explanation": "语义：“回答”需要人来作答，班车不能回答，句意不通。"}], "explanations": {"重来": "正确：“重来”指时间、机会一去不再回来，与“错过”以及“再也不会”相合。", "放弃": "语义：“放弃”需要有意志的主体，班车不能作“放弃”的主体，句意不通。", "答应": "配价：“答应”需要有意志的人作主语，班车无法答应，句意不通。", "回答": "语义：“回答”需要人来作答，班车不能回答，句意不通。"}, "sentence_index": 6, "correct_answer": "重来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于重来了出生的村子。", "explanation": "这里应该用〈回到〉。重来表示时间、机会等再次到来，不表示人回到某地。"}, {"text": "我们想重来失去的信任。", "explanation": "这里应该用〈挽回〉。重来不表示找回已经失去的东西，挽回信任要用“挽回”。"}, {"text": "医院努力重来病人的健康。", "explanation": "这里应该用〈恢复〉。重来不用于身体状况的恢复，恢复健康要用“恢复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样的机会一去，就不会重来一个。", "corrected_sentence": "这样的机会一去，就不会重来。", "error_description": "量词错误：“重来”表示再次到来，后面不接量词，“一个”应去掉。应说“不会重来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这样的好运一去就不会重来了了。", "corrected_sentence": "这样的好运一去就不会重来了。", "error_description": "体标错误：句末的“了”多写了一个，“重来了了”只应用一个“了”。应说“不会重来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
